import { MathUtils, Material, Mesh, Object3D } from 'three'

import {
  deferSceneMaterialDisposal,
  type SceneMaterialDisposalErrorHandler,
} from './sceneMaterialLifecycle'

export const FOREGROUND_FADE_MIN_OPACITY = 0.22
export const FOREGROUND_FADE_NEAR_DISTANCE = 3
export const FOREGROUND_FADE_FAR_DISTANCE = 5
export const FOREGROUND_FADE_SETTLE_SECONDS = 0.18

const FULLY_OPAQUE_THRESHOLD = 0.999
const TEN_PERCENT_REMAINDER = -Math.log(0.1)

function normalizeOpacity(opacity: number): number {
  return Number.isFinite(opacity) ? MathUtils.clamp(opacity, 0, 1) : 1
}

export function getForegroundFadeOpacity(distanceToWall: number): number {
  if (!Number.isFinite(distanceToWall)) return 1

  const linearProgress = MathUtils.clamp(
    (distanceToWall - FOREGROUND_FADE_NEAR_DISTANCE) /
      (FOREGROUND_FADE_FAR_DISTANCE - FOREGROUND_FADE_NEAR_DISTANCE),
    0,
    1,
  )
  const smoothProgress =
    linearProgress * linearProgress * (3 - 2 * linearProgress)

  return MathUtils.lerp(FOREGROUND_FADE_MIN_OPACITY, 1, smoothProgress)
}

export function dampForegroundFadeOpacity(
  currentOpacity: number,
  targetOpacity: number,
  deltaSeconds: number,
  reducedMotion = false,
): number {
  const target = normalizeOpacity(targetOpacity)
  if (reducedMotion || !Number.isFinite(currentOpacity)) return target

  const current = normalizeOpacity(currentOpacity)
  const delta = Number.isFinite(deltaSeconds) ? Math.max(0, deltaSeconds) : 0
  if (delta === 0) return current

  const remainder = Math.exp(
    (-TEN_PERCENT_REMAINDER * delta) / FOREGROUND_FADE_SETTLE_SECONDS,
  )
  return target + (current - target) * remainder
}

interface MaterialSnapshot {
  readonly material: Material
  readonly opacity: number
  readonly transparent: boolean
  readonly depthWrite: boolean
}

interface MeshSnapshot {
  readonly mesh: Mesh
  readonly material: Material | Material[]
  readonly castShadow: boolean
}

export interface ForegroundMaterialController {
  setOpacity: (opacity: number) => void
  dispose: () => void
}

export interface ForegroundMaterialOptions {
  onDisposalError?: SceneMaterialDisposalErrorHandler
}

/**
 * Gives one foreground model its own material instances before they are faded.
 * Loaded environment models otherwise share cached materials across every wall.
 */
export function isolateForegroundMaterials(
  root: Object3D,
  options: ForegroundMaterialOptions = {},
): ForegroundMaterialController {
  const clonedMaterials = new Map<Material, Material>()
  const materialSnapshots: MaterialSnapshot[] = []
  const meshSnapshots: MeshSnapshot[] = []

  const isolateMaterial = (source: Material): Material => {
    const cached = clonedMaterials.get(source)
    if (cached) return cached

    const material = source.clone()
    material.name = `${source.name || 'material'}-foreground-fade`
    clonedMaterials.set(source, material)
    materialSnapshots.push({
      material,
      opacity: material.opacity,
      transparent: material.transparent,
      depthWrite: material.depthWrite,
    })
    return material
  }

  root.traverse((object) => {
    if (!(object instanceof Mesh)) return

    const sourceMaterial = object.material
    meshSnapshots.push({
      mesh: object,
      material: sourceMaterial,
      castShadow: object.castShadow,
    })
    object.material = Array.isArray(sourceMaterial)
      ? sourceMaterial.map(isolateMaterial)
      : isolateMaterial(sourceMaterial)
  })

  let disposed = false

  const setOpacity = (opacity: number) => {
    if (disposed) return

    const normalizedOpacity = normalizeOpacity(opacity)
    const faded = normalizedOpacity < FULLY_OPAQUE_THRESHOLD

    for (const snapshot of materialSnapshots) {
      const { material } = snapshot
      const transparent = faded ? true : snapshot.transparent
      if (material.transparent !== transparent) {
        material.transparent = transparent
        material.needsUpdate = true
      }
      material.depthWrite = faded ? false : snapshot.depthWrite
      material.opacity = faded
        ? snapshot.opacity * normalizedOpacity
        : snapshot.opacity
    }

    for (const snapshot of meshSnapshots) {
      snapshot.mesh.castShadow = faded ? false : snapshot.castShadow
    }
  }

  return {
    setOpacity,
    dispose: () => {
      if (disposed) return
      setOpacity(1)
      disposed = true

      for (const snapshot of meshSnapshots) {
        snapshot.mesh.material = snapshot.material
        snapshot.mesh.castShadow = snapshot.castShadow
      }
      const ownedMaterials = [...clonedMaterials.values()]
      for (const material of ownedMaterials) {
        deferSceneMaterialDisposal(() => material.dispose(), {
          label: material.name || 'foreground material',
          onError: options.onDisposalError,
        })
      }
    },
  }
}
