import { useFrame } from '@react-three/fiber'
import { Html } from '@react-three/drei'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  AdditiveBlending,
  DoubleSide,
  Group,
  Mesh,
  Sprite,
  SRGBColorSpace,
  Texture,
  TextureLoader,
  Vector3,
} from 'three'

import { useGameStore, type EffectSpawn } from '../runtime/gameStore'
import { SLASH_ART_ROTATION_Z, yawFromNegativeZForward } from './direction'
import { drainVfx } from './vfx/vfxQueue'

const VFX_ROOT = `${import.meta.env.BASE_URL}assets/vfx/`
const textureCache = new Map<string, Promise<Texture | null>>()

function loadOptionalTexture(url: string): Promise<Texture | null> {
  const cached = textureCache.get(url)
  if (cached) return cached
  const promise = new Promise<Texture | null>((resolve) => {
    new TextureLoader().load(
      url,
      (texture) => {
        texture.colorSpace = SRGBColorSpace
        texture.needsUpdate = true
        resolve(texture)
      },
      undefined,
      () => resolve(null),
    )
  })
  textureCache.set(url, promise)
  return promise
}

function useOptionalTexture(filename: string): Texture | null | undefined {
  const url = `${VFX_ROOT}${filename}`
  const [texture, setTexture] = useState<Texture | null>()
  useEffect(() => {
    let active = true
    void loadOptionalTexture(url).then((loaded) => {
      if (active) setTexture(loaded)
    })
    return () => {
      active = false
    }
  }, [url])
  return texture
}

interface EffectTextures {
  slash: Texture | null | undefined
  spark: Texture | null | undefined
  flare: Texture | null | undefined
  magic: Texture | null | undefined
  smoke: Texture | null | undefined
  trail: Texture | null | undefined
}

/**
 * Fixed shard layout for the veil break.
 *
 * Deliberately deterministic rather than randomised: this fires on a gameplay
 * beat the player is meant to read, so it should look the same every time. The
 * VFX random stream exists for ambient variety, not for signature moments.
 */
const SHATTER_SHARDS = Array.from({ length: 7 }, (_, index) => {
  const angle = (index / 7) * Math.PI * 2
  return {
    angle,
    length: 0.4 + ((index * 13) % 5) * 0.055,
    rise: ((index * 7) % 4) * 0.09 - 0.13,
    tilt: ((index * 11) % 5) * 0.22 - 0.44,
  }
})

function SparkBurst({ color }: { color: string }) {
  const sparks = useMemo(
    () =>
      Array.from({ length: 8 }, (_, index) => ({
        angle: (index / 8) * Math.PI * 2,
        length: 0.24 + ((index * 37) % 5) * 0.035,
      })),
    [],
  )
  return (
    <group rotation={[-Math.PI / 2, 0, 0]}>
      {sparks.map((spark) => (
        <mesh
          key={spark.angle}
          position={[
            Math.cos(spark.angle) * 0.28,
            Math.sin(spark.angle) * 0.28,
            0,
          ]}
          rotation={[0, 0, spark.angle]}
        >
          <planeGeometry args={[spark.length, 0.035]} />
          <meshBasicMaterial
            color={color}
            transparent
            opacity={0.9}
            depthWrite={false}
            blending={AdditiveBlending}
            toneMapped={false}
            side={DoubleSide}
          />
        </mesh>
      ))}
    </group>
  )
}

function GazeDrain({ color, length }: { color: string; length: number }) {
  return (
    <group>
      {Array.from({ length: 7 }, (_, index) => {
        const progress = (index + 1) / 8
        return (
          <mesh
            key={index}
            position={[
              ((index % 3) - 1) * 0.11 * (1 - progress),
              (index % 2) * 0.08 - 0.04,
              -length * progress,
            ]}
            rotation={[0, 0, Math.PI / 4 + index * 0.19]}
          >
            <octahedronGeometry args={[0.09 + (index % 2) * 0.025, 0]} />
            <meshBasicMaterial
              color={color}
              transparent
              opacity={0.92}
              depthWrite={false}
              blending={AdditiveBlending}
              toneMapped={false}
            />
          </mesh>
        )
      })}
    </group>
  )
}

function Effect({
  effect,
  textures,
  onRetire,
}: {
  effect: EffectSpawn
  textures: EffectTextures
  onRetire: (id: string) => void
}) {
  const groupRef = useRef<Group>(null)
  const age = useRef(0)
  const reducedMotion = useGameStore((state) => state.settings.reducedMotion)
  const direction = useMemo(
    () => new Vector3(...(effect.direction ?? [0, 0, -1])).normalize(),
    [effect.direction],
  )
  const rotationY = yawFromNegativeZForward(direction)
  const requestedDuration = Math.max(80, effect.durationMs ?? 320) / 1000
  const duration = reducedMotion
    ? Math.min(0.14, requestedDuration)
    : requestedDuration

  useFrame((_, frameDelta) => {
    age.current += frameDelta
    const progress = Math.min(1, age.current / duration)
    if (groupRef.current) {
      const eased = 1 - Math.pow(1 - progress, 3)
      const scale =
        effect.kind === 'death' || effect.kind === 'burst'
          ? 0.35 + eased * 2.6
          : effect.kind === 'hurt'
            ? 0.82 + Math.sin(progress * Math.PI) * 0.72
            : effect.kind === 'dash'
              ? 1 + eased * 0.55
              : 0.7 + eased * 0.85
      groupRef.current.scale.setScalar(scale)
      groupRef.current.position.y +=
        frameDelta *
        (effect.kind === 'death' || effect.kind === 'burst' ? 0.5 : 0.08)
      groupRef.current.traverse((child) => {
        const material =
          child instanceof Mesh || child instanceof Sprite
            ? child.material
            : undefined
        if (
          material &&
          !Array.isArray(material) &&
          'opacity' in material &&
          typeof material.opacity === 'number'
        ) {
          material.opacity = Math.max(0, (1 - progress) * 0.9)
        }
      })
    }
    if (progress >= 1) onRetire(effect.id)
  })

  return (
    <group
      ref={groupRef}
      position={effect.position}
      rotation={[0, rotationY, 0]}
      name={`effect-${effect.kind}`}
    >
      {effect.label ? (
        <Html center position={[0, 0.72, 0]} transform={false}>
          <span className="boda-world-score-popup">{effect.label}</span>
        </Html>
      ) : null}
      {effect.kind === 'slash' ? (
        <group position={[0, 0, -Math.max(0.8, (effect.length ?? 2.2) * 0.43)]}>
          {textures.slash ? (
            <mesh
              position={[0, 0.035, 0]}
              rotation={[-Math.PI / 2, 0, SLASH_ART_ROTATION_Z]}
            >
              <planeGeometry args={[2.35, 2.35]} />
              <meshBasicMaterial
                map={textures.slash}
                color={effect.color}
                transparent
                opacity={0.96}
                alphaTest={0.015}
                depthWrite={false}
                blending={AdditiveBlending}
                toneMapped={false}
                side={DoubleSide}
              />
            </mesh>
          ) : (
            <mesh rotation={[-Math.PI / 2, 0, SLASH_ART_ROTATION_Z]}>
              <ringGeometry
                args={[0.72, 0.98, 32, 1, Math.PI * 0.11, Math.PI * 0.78]}
              />
              <meshBasicMaterial
                color={effect.color}
                transparent
                opacity={0.92}
                depthWrite={false}
                blending={AdditiveBlending}
                toneMapped={false}
                side={DoubleSide}
              />
            </mesh>
          )}
        </group>
      ) : effect.kind === 'dash' ? (
        <group position={[0, 0, 0.45]}>
          {[0, 0.33, 0.66].map((offset) => (
            <mesh
              key={offset}
              position={[0, 0, offset]}
              rotation={[-Math.PI / 2, 0, 0]}
            >
              <circleGeometry args={[0.34 - offset * 0.18, 12]} />
              <meshBasicMaterial
                color={effect.color}
                transparent
                opacity={0.36 - offset * 0.18}
                depthWrite={false}
                blending={AdditiveBlending}
                toneMapped={false}
              />
            </mesh>
          ))}
        </group>
      ) : effect.kind === 'hit' ? (
        textures.spark ? (
          <sprite scale={[0.9, 0.9, 1]}>
            <spriteMaterial
              map={textures.spark}
              color={effect.color}
              transparent
              opacity={0.94}
              depthWrite={false}
              blending={AdditiveBlending}
              toneMapped={false}
            />
          </sprite>
        ) : (
          <SparkBurst color={effect.color} />
        )
      ) : effect.kind === 'hurt' ? (
        <group>
          <mesh position={[0, -0.76, 0]} rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[0.48, 0.62, 32]} />
            <meshBasicMaterial
              color="#d81f4d"
              transparent
              opacity={0.88}
              depthWrite={false}
              blending={AdditiveBlending}
              toneMapped={false}
              side={DoubleSide}
            />
          </mesh>
          <mesh position={[0, -0.69, -0.94]} rotation={[-Math.PI / 2, 0, 0]}>
            <coneGeometry args={[0.22, 0.58, 3]} />
            <meshBasicMaterial
              color="#ffd0a3"
              transparent
              opacity={0.98}
              depthWrite={false}
              blending={AdditiveBlending}
              toneMapped={false}
            />
          </mesh>
          {textures.spark ? (
            <sprite position={[0, 0.04, 0]} scale={[1.35, 1.35, 1]}>
              <spriteMaterial
                map={textures.spark}
                color="#ffffff"
                transparent
                opacity={0.98}
                depthWrite={false}
                blending={AdditiveBlending}
                toneMapped={false}
              />
            </sprite>
          ) : (
            <group position={[0, 0.04, 0]} scale={1.35}>
              <SparkBurst color="#ffffff" />
            </group>
          )}
        </group>
      ) : effect.kind === 'seal' ? (
        // The moment the gaze takes hold. A ring closing on the target plus a
        // rising column, so the freeze reads as something arriving rather than
        // as the enemy simply changing colour.
        <group>
          <mesh position={[0, 0.03, 0]} rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[0.52, 0.7, 40]} />
            <meshBasicMaterial
              color={effect.color}
              transparent
              opacity={0.95}
              depthWrite={false}
              blending={AdditiveBlending}
              toneMapped={false}
              side={DoubleSide}
            />
          </mesh>
          <mesh position={[0, 0.62, 0]}>
            <cylinderGeometry args={[0.34, 0.46, 1.25, 18, 1, true]} />
            <meshBasicMaterial
              color={effect.color}
              transparent
              opacity={0.34}
              depthWrite={false}
              blending={AdditiveBlending}
              toneMapped={false}
              side={DoubleSide}
            />
          </mesh>
        </group>
      ) : effect.kind === 'shatter' ? (
        // The veil tears. A white core with shards thrown outward — the payoff
        // for holding a break-after enemy in view long enough.
        <group>
          <mesh position={[0, 0.5, 0]}>
            <sphereGeometry args={[0.3, 12, 8]} />
            <meshBasicMaterial
              color="#ffffff"
              transparent
              opacity={0.9}
              depthWrite={false}
              blending={AdditiveBlending}
              toneMapped={false}
            />
          </mesh>
          {SHATTER_SHARDS.map((shard) => (
            <mesh
              key={shard.angle}
              position={[
                Math.cos(shard.angle) * 0.62,
                0.5 + shard.rise,
                Math.sin(shard.angle) * 0.62,
              ]}
              rotation={[0, -shard.angle, shard.tilt]}
            >
              <planeGeometry args={[shard.length, 0.06]} />
              <meshBasicMaterial
                color={effect.color}
                transparent
                opacity={0.95}
                depthWrite={false}
                blending={AdditiveBlending}
                toneMapped={false}
                side={DoubleSide}
              />
            </mesh>
          ))}
        </group>
      ) : effect.kind === 'trail' ? (
        textures.trail ? (
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <planeGeometry args={[0.48, 1.5]} />
            <meshBasicMaterial
              map={textures.trail}
              color={effect.color}
              transparent
              opacity={0.78}
              alphaTest={0.01}
              blending={AdditiveBlending}
              toneMapped={false}
              depthWrite={false}
              side={DoubleSide}
            />
          </mesh>
        ) : (
          <mesh>
            <octahedronGeometry args={[0.18, 0]} />
            <meshBasicMaterial
              color={effect.color}
              transparent
              opacity={0.72}
              blending={AdditiveBlending}
              toneMapped={false}
              depthWrite={false}
            />
          </mesh>
        )
      ) : (
        <group>
          {effect.kind === 'death' && textures.smoke ? (
            <sprite position={[0, 0.35, 0]} scale={[1.45, 1.45, 1]}>
              <spriteMaterial
                map={textures.smoke}
                color={effect.color}
                transparent
                opacity={0.68}
                depthWrite={false}
              />
            </sprite>
          ) : effect.kind === 'drain' ? (
            <GazeDrain color={effect.color} length={effect.length ?? 1.8} />
          ) : effect.kind === 'burst' && textures.flare ? (
            <sprite scale={[1.2, 1.2, 1]}>
              <spriteMaterial
                map={textures.flare}
                color={effect.color}
                transparent
                opacity={0.82}
                depthWrite={false}
                blending={AdditiveBlending}
                toneMapped={false}
              />
            </sprite>
          ) : effect.kind === 'telegraph' && textures.magic ? (
            <mesh position={[0, 0.025, 0]} rotation={[-Math.PI / 2, 0, 0]}>
              <planeGeometry
                args={[effect.width ?? 1.35, effect.length ?? 1.35]}
              />
              <meshBasicMaterial
                map={textures.magic}
                color={effect.color}
                transparent
                opacity={0.55}
                alphaTest={0.01}
                depthWrite={false}
                blending={AdditiveBlending}
                toneMapped={false}
                side={DoubleSide}
              />
            </mesh>
          ) : null}
          <mesh rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[0.2, 0.34, 28]} />
            <meshBasicMaterial
              color={effect.color}
              transparent
              opacity={0.82}
              depthWrite={false}
              blending={AdditiveBlending}
              toneMapped={false}
              side={DoubleSide}
            />
          </mesh>
        </group>
      )}
    </group>
  )
}

/**
 * Owns live effects locally instead of reading them from the store.
 *
 * Previously each effect lived in zustand for its whole lifetime and removed
 * itself with a store write from inside useFrame — so every expiring spark
 * re-rendered every store subscriber, including the component that renders the
 * Canvas. Now spawns arrive through the imperative queue and expiry only
 * re-renders this subtree.
 */
export function Effects() {
  const [effects, setEffects] = useState<EffectSpawn[]>([])

  useFrame(() => {
    const spawned = drainVfx()
    if (spawned.length > 0) setEffects((current) => [...current, ...spawned])
  })

  const retire = useCallback((id: string) => {
    setEffects((current) => current.filter((item) => item.id !== id))
  }, [])

  const textures: EffectTextures = {
    slash: useOptionalTexture('signature-slash.png'),
    spark: useOptionalTexture('particle-spark.png'),
    flare: useOptionalTexture('particle-flare.png'),
    magic: useOptionalTexture('particle-magic.png'),
    smoke: useOptionalTexture('particle-smoke.png'),
    trail: useOptionalTexture('particle-trail.png'),
  }
  return effects.map((effect) => (
    <Effect
      key={effect.id}
      effect={effect}
      textures={textures}
      onRetire={retire}
    />
  ))
}
