export type PlayerLocomotion =
  'idle' | 'run-forward' | 'strafe-left' | 'strafe-right' | 'backpedal'

export function resolvePlayerLocomotion(
  moveX: number,
  moveZ: number,
  facingX: number,
  facingZ: number,
): PlayerLocomotion {
  const moveLength = Math.hypot(moveX, moveZ)
  const facingLength = Math.hypot(facingX, facingZ)
  if (moveLength <= 0.001) return 'idle'
  if (facingLength <= 0.001) return 'run-forward'

  const normalizedMoveX = moveX / moveLength
  const normalizedMoveZ = moveZ / moveLength
  const normalizedFacingX = facingX / facingLength
  const normalizedFacingZ = facingZ / facingLength
  const forward =
    normalizedMoveX * normalizedFacingX + normalizedMoveZ * normalizedFacingZ
  const right =
    normalizedMoveX * -normalizedFacingZ + normalizedMoveZ * normalizedFacingX

  if (Math.abs(forward) >= Math.abs(right)) {
    return forward >= 0 ? 'run-forward' : 'backpedal'
  }
  return right >= 0 ? 'strafe-right' : 'strafe-left'
}
