export interface DamageResult {
  readonly damage: number
  readonly health: number
  readonly defeated: boolean
}

/**
 * Decay rate for velocity an enemy did not produce itself — knockback and
 * other outside impulses.
 *
 * Observing an enemy pauses *enemy-owned* time, not the world's, so this decay
 * keeps running while the enemy is frozen. Enemy.tsx applies it per frame
 * against a Rapier body, which owns integration; this module owns the rate.
 */
export const EXTERNAL_VELOCITY_DECAY_PER_SECOND = 5.5

/** Fraction of external velocity surviving `deltaSeconds`, in [0, 1]. */
export function externalVelocityRetention(deltaSeconds: number): number {
  if (!Number.isFinite(deltaSeconds) || deltaSeconds < 0) {
    throw new RangeError('deltaSeconds must be a non-negative finite number')
  }
  return Math.exp(-deltaSeconds * EXTERNAL_VELOCITY_DECAY_PER_SECOND)
}

export function calculateDamage(rawDamage: number, armor: number): number {
  if (!Number.isFinite(rawDamage) || !Number.isFinite(armor)) {
    throw new RangeError('Damage and armor must be finite')
  }
  if (rawDamage <= 0) {
    return 0
  }
  return Math.max(1, rawDamage - Math.max(0, armor))
}

export function applyDamage(
  currentHealth: number,
  rawDamage: number,
  armor = 0,
): DamageResult {
  if (!Number.isFinite(currentHealth)) {
    throw new RangeError('Health must be finite')
  }
  const damage = calculateDamage(rawDamage, armor)
  const health = Math.max(0, currentHealth - damage)
  return { damage, health, defeated: health === 0 }
}
