export interface SceneLoadProgress {
  stage: string
  progress: number
  message?: string
}

export type EncounterPresentationNextStep =
  'runes' | 'shrine' | 'route' | 'next-room' | 'victory'

export interface EncounterPresentationEvent {
  id: string
  kind: 'start' | 'clear'
  chamber: number
  roomId: string
  roomName: string
  boss: boolean
  risk: RouteRisk
  mutationId: RoomMutationId | null
  eliteCount: number
  nextStep: EncounterPresentationNextStep
}

export interface GameSceneProps {
  onLoadProgress?: (update: SceneLoadProgress) => void
  onReady?: () => void
  onFatalError?: (error: Error) => void
  preparationKey?: string | null
  onPreparationReady?: (key: string) => void
  onEncounterEvent?: (event: EncounterPresentationEvent) => void
  onAdvanceRoom?: () => void
  warmup?: boolean
}

type SceneRoom = GeneratedRoom | GeneratedRunNode

function toError(cause: unknown, fallback: string): Error {
  return cause instanceof Error ? cause : new Error(fallback)
}

class SceneErrorBoundary extends Component<
  { children: ReactNode; onError?: (error: Error) => void },
  { failed: boolean }
> {
  state = { failed: false }

  static getDerivedStateFromError() {
    return { failed: true }
  }

  componentDidCatch(error: Error, _info: ErrorInfo) {
    void _info
    this.props.onError?.(error)
  }

  render() {
    return this.state.failed ? null : this.props.children
  }
}

function ContentReadySignal({ onReady }: { onReady: () => void }) {
  useEffect(() => onReady(), [onReady])
  return null
}

function nextFrame(): Promise<void> {
  return new Promise((resolve) => requestAnimationFrame(() => resolve()))
}

const SCENE_COMPILATION_TIMEOUT_MS = 30_000
const reportedContextLossEvents = new WeakSet<Event>()

function reportContextLoss(
  event: Event,
  onFatalError?: (error: Error) => void,
): void {
  event.preventDefault()
  if (reportedContextLossEvents.has(event)) return
  reportedContextLossEvents.add(event)
  onFatalError?.(new Error('WebGL context was lost while loading BODA.'))
}

function SceneWarmup({
  contentReady,
  postProcessingReady,
  enabled,
  onLoadProgress,
  onReady,
  onFatalError,
}: {
  contentReady: boolean
  postProcessingReady: boolean
  enabled: boolean
  onLoadProgress?: (update: SceneLoadProgress) => void
  onReady?: () => void
  onFatalError?: (error: Error) => void
}) {
  const gl = useThree((state) => state.gl)
  const scene = useThree((state) => state.scene)
  const camera = useThree((state) => state.camera)
  const completed = useRef(false)
  const activeAttempt = useRef<object | null>(null)
  const compilationRef = useRef<SceneMaterialCompilationTask | null>(null)
  const contextLost = useRef(false)

  useEffect(() => {
    const canvas = gl.domElement
    const handleContextLost = (event: Event) => {
      contextLost.current = true
      compilationRef.current?.cancel()
      reportContextLoss(event, onFatalError)
    }
    canvas.addEventListener('webglcontextlost', handleContextLost)
    return () =>
      canvas.removeEventListener('webglcontextlost', handleContextLost)
  }, [gl, onFatalError])

  useEffect(() => {
    if (
      !contentReady ||
      !postProcessingReady ||
      completed.current ||
      activeAttempt.current
    ) {
      return
    }
    const attempt = {}
    activeAttempt.current = attempt
    let active = true
    let compilation: SceneMaterialCompilationTask | null = null

    const warm = async () => {
      try {
        onLoadProgress?.({
          stage: 'shader-compilation',
          progress: enabled ? 0.72 : 0.9,
          message: enabled ? '셰이더를 준비하는 중' : '렌더러 준비 완료',
        })
        if (enabled) {
          if (contextLost.current) return
          compilation = startSceneMaterialCompilation(
            () => gl.compile(scene, camera),
            { timeoutMs: SCENE_COMPILATION_TIMEOUT_MS },
          )
          compilationRef.current = compilation
          const outcome = await compilation.promise
          if (outcome === 'cancelled') return
        }
        if (!active) return
        onLoadProgress?.({
          stage: 'post-processing-warmup',
          progress: 0.91,
          message: '화면 효과를 예열하는 중',
        })
        // These frames are rendered by the persistent composer on this same
        // Canvas, so no throwaway WebGL context or duplicate shader cache exists.
        await nextFrame()
        await nextFrame()
        if (!active) return
        onLoadProgress?.({
          stage: 'ready',
          progress: 1,
          message: '원정 준비 완료',
        })
        onReady?.()
        completed.current = true
      } catch (cause) {
        if (active) {
          onFatalError?.(toError(cause, 'BODA renderer warmup failed.'))
        }
      } finally {
        if (compilationRef.current === compilation) {
          compilationRef.current = null
        }
        if (activeAttempt.current === attempt) {
          activeAttempt.current = null
        }
      }
    }

    void warm()
    return () => {
      active = false
      compilation?.cancel()
      if (compilationRef.current === compilation) {
        compilationRef.current = null
      }
      if (activeAttempt.current === attempt) {
        activeAttempt.current = null
      }
    }
  }, [
    camera,
    contentReady,
    enabled,
    gl,
    onFatalError,
    onLoadProgress,
    onReady,
    postProcessingReady,
    scene,
  ])

  return null
}

function ScenePreparation({
  preparationKey,
  onReady,
  onFatalError,
}: {
  preparationKey?: string | null
  onReady?: (key: string) => void
  onFatalError?: (error: Error) => void
}) {
  const gl = useThree((state) => state.gl)
  const scene = useThree((state) => state.scene)
  const camera = useThree((state) => state.camera)
  const completedKey = useRef<string | null>(null)

  useEffect(() => {
    if (!preparationKey || completedKey.current === preparationKey) return
    let active = true
    let contextLost = false
    let compilation: SceneMaterialCompilationTask | null = null
    const canvas = gl.domElement
    const handleContextLost = (event: Event) => {
      contextLost = true
      compilation?.cancel()
      reportContextLoss(event, onFatalError)
    }
    canvas.addEventListener('webglcontextlost', handleContextLost)

    const prepare = async () => {
      try {
        await nextFrame()
        if (!active || contextLost) return
        compilation = startSceneMaterialCompilation(
          () => gl.compile(scene, camera),
          { timeoutMs: SCENE_COMPILATION_TIMEOUT_MS },
        )
        const outcome = await compilation.promise
        if (outcome === 'cancelled') return
        await nextFrame()
        if (!active) return
        completedKey.current = preparationKey
        onReady?.(preparationKey)
      } catch (cause) {
        if (active) {
          onFatalError?.(toError(cause, 'BODA room shader preparation failed.'))
        }
      }
    }
    void prepare()
    return () => {
      active = false
      compilation?.cancel()
      canvas.removeEventListener('webglcontextlost', handleContextLost)
    }
  }, [camera, gl, onFatalError, onReady, preparationKey, scene])

  return null
}

function transformDirection(
  direction: CardinalDirection,
  variant: LayoutVariant,
): CardinalDirection {
  if (variant === 'original') return direction
  if (variant === 'mirror-x') {
    if (direction === 'east') return 'west'
    if (direction === 'west') return 'east'
    return direction
  }
  const opposite: Record<CardinalDirection, CardinalDirection> = {
    north: 'south',
    east: 'west',
    south: 'north',
    west: 'east',
  }
  return opposite[direction]
}

function transformRoomLayout(
  room: RoomTemplate,
  variant: LayoutVariant,
): RoomTemplate {
  if (variant === 'original') return room
  return {
    ...room,
    sockets: room.sockets.map((socket) => ({
      ...socket,
      position: applyLayoutVariant(socket.position, variant),
      direction: transformDirection(socket.direction, variant),
    })),
    spawns: room.spawns.map((spawn) => ({
      ...spawn,
      position: applyLayoutVariant(spawn.position, variant),
    })),
    occluders: room.occluders.map((occluder) => ({
      ...occluder,
      center: applyLayoutVariant(occluder.center, variant),
    })),
    waypoints: room.waypoints.map((waypoint) => ({
      ...waypoint,
      position: applyLayoutVariant(waypoint.position, variant),
    })),
  }
}

function getEncounterNextStep(
  room: SceneRoom,
  endless: boolean,
): EncounterPresentationNextStep {
  if (room.kind === 'boss') return endless ? 'next-room' : 'victory'
  if (room.rewardSpec.kind === 'shrine') return 'shrine'
  if (room.rewardSpec.kind === 'runes' || room.rewardChoices.length > 0) {
    return 'runes'
  }
  if ('nextNodeIds' in room) {
    if (room.nextNodeIds.length === 0) return 'victory'
    if (room.nextNodeIds.length > 1) return 'route'
  }
  return 'next-room'
}

function RoomEncounter({
  room,
  runId,
  onEncounterEvent,
  onAdvanceRoom,
}: {
  room: SceneRoom
  runId: number
  onEncounterEvent?: (event: EncounterPresentationEvent) => void
  onAdvanceRoom?: () => void
}) {
  const difficulty = useGameStore((state) => state.difficulty)
  const mode = useGameStore((state) => state.mode)
  const roomIndex = useGameStore((state) => state.roomIndex)
  const template = useMemo(
    () =>
      transformRoomLayout(getRoomTemplate(room.templateId), room.layoutVariant),
    [room.layoutVariant, room.templateId],
  )
  const aliveEnemies = useGameStore((state) => state.aliveEnemies)
  const phase = useGameStore((state) => state.phase)
  const setRoomPopulation = useGameStore((state) => state.setRoomPopulation)
  const showReward = useGameStore((state) => state.showReward)
  const advanceRoomStore = useGameStore((state) => state.advanceRoom)
  const advanceRoom = onAdvanceRoom ?? advanceRoomStore
  const spawnEffect = useGameStore((state) => state.spawnEffect)
  const awardScore = useGameStore((state) => state.awardScore)
  const healPlayer = useGameStore((state) => state.healPlayer)
  const [ready, setReady] = useState(false)
  const [bossReinforcements, setBossReinforcements] = useState<
    GeneratedEnemySpawn[]
  >([])
  const completionHandled = useRef(false)
  const startSignaled = useRef(false)
  const clearSignaled = useRef(false)
  const volatileRewardGranted = useRef(false)
  const encounterTier: AttackDirectorTier =
    room.kind === 'boss' ? 'boss' : room.chamberLevel
  const absoluteChamber = 'depth' in room ? room.depth : roomIndex + 1
  const scaling = useMemo(
    () => getCombatScaling(absoluteChamber, difficulty),
    [absoluteChamber, difficulty],
  )
  const attackDirector = useMemo(
    () => createAttackDirector(encounterTier, difficulty),
    [difficulty, encounterTier],
  )

  const playerSpawn = template.spawns.find((spawn) => spawn.role === 'player')
    ?.position ?? { x: 0, z: 5 }
  const roomId = 'id' in room ? room.id : `${room.index}:${room.templateId}`
  const encounterId = `${runId}:${roomId}`
  const roomBossId =
    room.kind === 'boss'
      ? (room.enemies.map((enemy) => enemy.archetypeId).find(isSceneBoss) ??
        null)
      : null
  const encounterPresentation = useMemo(
    () => ({
      chamber: absoluteChamber,
      roomId,
      roomName: template.name,
      boss: room.kind === 'boss',
      risk:
        'routeRisk' in room
          ? room.routeRisk
          : room.kind === 'boss'
            ? 'boss'
            : 'fixed',
      mutationId: 'mutationId' in room ? room.mutationId : null,
      eliteCount:
        'eliteCount' in room
          ? room.eliteCount
          : room.enemies.filter((enemy) => enemy.eliteAffixId != null).length,
      nextStep: getEncounterNextStep(room, mode === 'endless'),
    }),
    [absoluteChamber, mode, room, roomId, template.name],
  )

  useEffect(() => {
    completionHandled.current = false
    startSignaled.current = false
    clearSignaled.current = false
    setRoomPopulation(room.enemies.length)
    const timer = window.setTimeout(() => {
      setReady(true)
    }, 180)
    return () => {
      window.clearTimeout(timer)
      attackDirector.clear()
    }
  }, [attackDirector, encounterId, room.enemies.length, setRoomPopulation])

  useEffect(() => {
    if (room.kind !== 'boss' || roomBossId === null || !ready) return

    let active = true
    let waveIndex = 0
    let timer = 0
    const schedule = (delayMs: number) => {
      timer = window.setTimeout(summonWave, delayMs)
    }
    const summonWave = () => {
      if (!active) return
      if (useGameStore.getState().phase !== 'playing') {
        schedule(500)
        return
      }
      const bossAlive = [...runtime.enemies.values()].some((enemy) =>
        isSceneBoss(enemy.archetypeId),
      )
      if (!bossAlive) return

      const activeReinforcements = [...runtime.enemies.keys()].filter((id) =>
        id.includes('-boss-reinforcement-'),
      ).length
      const lanes = canSpawnBossReinforcementWave(activeReinforcements)
        ? getBossReinforcementWave(
            roomBossId,
            template.size.x / 2,
            template.size.z / 2,
            waveIndex,
          )
        : []
      const wave = lanes.map((lane, index): GeneratedEnemySpawn => ({
        spawnId: `boss-reinforcement-${waveIndex}-${lane.side}-${index}`,
        position: lane.position,
        archetypeId: lane.archetypeId,
        eliteAffixId: null,
      }))

      if (wave.length > 0) {
        waveIndex += 1
        setBossReinforcements((current) => [...current, ...wave])
        const state = useGameStore.getState()
        state.setRoomPopulation(state.aliveEnemies + wave.length)
        for (const spawn of wave) {
          spawnEffect({
            id: `${encounterId}:${spawn.spawnId}:arrival`,
            kind: 'seal',
            position: [spawn.position.x, 0.05, spawn.position.z],
            color: '#ffffff',
            durationMs: 900,
          })
        }
        audioEngine.play('warning-boss')
      }
      schedule(BOSS_REINFORCEMENT_INTERVAL_MS)
    }

    schedule(BOSS_REINFORCEMENT_FIRST_WAVE_MS)
    return () => {
      active = false
      window.clearTimeout(timer)
    }
  }, [
    encounterId,
    ready,
    roomBossId,
    room.kind,
    spawnEffect,
    template.size.x,
    template.size.z,
  ])

  const removeBossReinforcement = useCallback((spawnId: string) => {
    setBossReinforcements((current) =>
      current.filter((spawn) => spawn.spawnId !== spawnId),
    )
  }, [])

  useEffect(() => {
    if (
      !ready ||
      phase !== 'playing' ||
      room.enemies.length === 0 ||
      startSignaled.current
    ) {
      return
    }

    startSignaled.current = true
    const event: EncounterPresentationEvent = {
      id: `${encounterId}:start`,
      kind: 'start',
      ...encounterPresentation,
    }
    onEncounterEvent?.(event)
    spawnEffect({
      id: `${event.id}:sigil`,
      kind: 'burst',
      position: [playerSpawn.x, 0.08, playerSpawn.z],
      color: '#ff3038',
      durationMs: 620,
      variant: 'sigil',
    })
    audioEngine.play('room-start')
  }, [
    encounterId,
    encounterPresentation,
    onEncounterEvent,
    phase,
    playerSpawn.x,
    playerSpawn.z,
    ready,
    room,
    room.enemies.length,
    spawnEffect,
  ])

  useEffect(() => {
    if (
      !ready ||
      completionHandled.current ||
      phase !== 'playing' ||
      aliveEnemies !== 0
    ) {
      return
    }

    if (room.enemies.length > 0 && !clearSignaled.current) {
      clearSignaled.current = true
      const event: EncounterPresentationEvent = {
        id: `${encounterId}:clear`,
        kind: 'clear',
        ...encounterPresentation,
      }
      onEncounterEvent?.(event)
      spawnEffect({
        id: `${event.id}:sigil`,
        kind: 'burst',
        position: [0, 0.08, 0],
        color: '#ffffff',
        durationMs: 900,
        variant: 'sigil',
      })
      audioEngine.play('room-clear')
    }

    if (
      'routeRisk' in room &&
      room.routeRisk === 'volatile' &&
      !volatileRewardGranted.current
    ) {
      volatileRewardGranted.current = true
      healPlayer(useGameStore.getState().stats.maxHealth * 0.1)
      awardScore(300)
      spawnEffect({
        id: `${encounterId}:moon-teeth`,
        kind: 'burst',
        position: [playerSpawn.x, 0.28, playerSpawn.z],
        color: '#ffffff',
        durationMs: 720,
        variant: 'sigil',
        label: '문 티스 · +300',
      })
    }

    if (
      'chamberLevel' in room &&
      (room.chamberLevel === 2 || room.chamberLevel === 4)
    ) {
      healPlayer(useGameStore.getState().stats.maxHealth * 0.12)
      spawnEffect({
        id: `${encounterId}:breather`,
        kind: 'burst',
        position: [playerSpawn.x, 0.28, playerSpawn.z],
        color: '#ffffff',
        durationMs: 520,
        label: '숨 고르기 · 체력 +12%',
      })
    }

    const timer = window.setTimeout(
      () => {
        if (useGameStore.getState().phase !== 'playing') return
        completionHandled.current = true
        const rewardSpec = room.rewardSpec
        if (room.kind === 'boss') {
          advanceRoom()
        } else if (rewardSpec.kind === 'shrine') {
          useGameStore
            .getState()
            .showShrine([...rewardSpec.runeChoices], rewardSpec.healFraction)
        } else if (rewardSpec.kind === 'runes') {
          showReward([...rewardSpec.choices])
        } else if (room.rewardChoices.length > 0) {
          showReward([...room.rewardChoices])
        } else {
          advanceRoom()
        }
      },
      room.enemies.length === 0 ? 0 : 950,
    )
    return () => window.clearTimeout(timer)
  }, [
    advanceRoom,
    aliveEnemies,
    awardScore,
    encounterId,
    healPlayer,
    encounterPresentation,
    onEncounterEvent,
    phase,
    playerSpawn.x,
    playerSpawn.z,
    ready,
    room,
    room.enemies.length,
    room.kind,
    room.rewardSpec,
    room.rewardChoices,
    showReward,
    spawnEffect,
  ])

  return (
    <>
      <RoomEnvironment
        room={template}
        biomeId={'biomeId' in room ? room.biomeId : template.biomeId}
        risk={'routeRisk' in room ? room.routeRisk : undefined}
        mutationId={'mutationId' in room ? room.mutationId : undefined}
      />
      <Player spawn={playerSpawn} roomSize={template.size} />
      <VisionCone />
      {[...room.enemies, ...bossReinforcements].map((spawn) => (
        <Enemy
          key={spawn.spawnId}
          id={`${room.index}-${spawn.spawnId}`}
          archetypeId={spawn.archetypeId}
          position={spawn.position}
          waypoints={template.waypoints}
          attackDirector={attackDirector}
          encounterTier={encounterTier}
          difficultyRank={difficulty}
          absoluteChamber={absoluteChamber}
          healthMultiplier={
            spawn.archetypeId === 'blind-thrall'
              ? scaling.weakEnemyHealthMultiplier
              : scaling.healthMultiplier
          }
          eliteAffixId={spawn.eliteAffixId}
          mutationId={'mutationId' in room ? room.mutationId : null}
          onDefeated={
            spawn.spawnId.startsWith('boss-reinforcement-')
              ? () => removeBossReinforcement(spawn.spawnId)
              : undefined
          }
        />
      ))}
      <Projectiles />
      <Effects />
    </>
  )
}

function SceneContent({
  onEncounterEvent,
  onAdvanceRoom,
}: {
  onEncounterEvent?: (event: EncounterPresentationEvent) => void
  onAdvanceRoom?: () => void
}) {
  const seed = useGameStore((state) => state.seed)
  const difficulty = useGameStore((state) => state.difficulty)
  const roomIndex = useGameStore((state) => state.roomIndex)
  const runId = useGameStore((state) => state.runId)
  const phase = useGameStore((state) => state.phase)
  const generatedRun = useGameStore((state) => state.generatedRun)
  const currentNodeId = useGameStore((state) => state.currentNodeId)
  const fallbackRun = useMemo(
    () => createRun(seed || 'BODA', difficulty),
    [difficulty, seed],
  )
  const run = generatedRun ?? fallbackRun
  const requestedNodeId =
    currentNodeId ?? (generatedRun ? generatedRun.startNodeId : null)
  const room =
    (requestedNodeId
      ? run.rooms.find((candidate) => candidate.id === requestedNodeId)
      : undefined) ??
    run.rooms[roomIndex] ??
    run.rooms[0]

  if (!room) return null

  return (
    <Physics
      key={`${runId}-${room.id ?? room.index}`}
      gravity={[0, -20, 0]}
      timeStep={1 / 60}
      paused={phase !== 'playing'}
      interpolate
    >
      <RoomEncounter
        room={room}
        runId={runId}
        onEncounterEvent={onEncounterEvent}
        onAdvanceRoom={onAdvanceRoom}
      />
    </Physics>
  )
}

function GameSceneImpl({
  onLoadProgress,
  onReady,
  onFatalError,
  preparationKey,
  onPreparationReady,
  onEncounterEvent,
  onAdvanceRoom,
  warmup = true,
}: GameSceneProps = {}) {
  const [contentReady, setContentReady] = useState(false)
  const [postProcessingReady, setPostProcessingReady] = useState(false)
  const markContentReady = useCallback(() => setContentReady(true), [])
  const markPostProcessingReady = useCallback(
    () => setPostProcessingReady(true),
    [],
  )

  useEffect(() => {
    onLoadProgress?.({
      stage: 'scene-bootstrap',
      progress: 0.08,
      message: '게임 장면을 구성하는 중',
    })
  }, [onLoadProgress])

  return (
    <div className="boda-canvas" data-testid="game-canvas">
      <SceneErrorBoundary onError={onFatalError}>
        <Canvas
          shadows="basic"
          dpr={[1, 1.5]}
          camera={{ position: [0, 13.5, 9.5], fov: 47, near: 0.1, far: 90 }}
          gl={{
            antialias: true,
            powerPreference: 'high-performance',
            alpha: false,
          }}
          onCreated={({ gl }) => {
            try {
              gl.outputColorSpace = SRGBColorSpace
              // Neutral tone mapping keeps the authored cyan/gold/coral palette
              // aligned with the DOM UI instead of bleaching it through ACES.
              gl.toneMapping = NeutralToneMapping
              gl.toneMappingExposure = 1.06
              onLoadProgress?.({
                stage: 'webgl-context',
                progress: 0.28,
                message: '렌더링 장치 연결 완료',
              })
            } catch (cause) {
              onFatalError?.(toError(cause, 'WebGL initialization failed.'))
            }
          }}
        >
          <FrameBudgetProbe />
          {/*
            60fps defence. PerformanceMonitor watches the actual frame rate and
            AdaptiveDpr drops resolution rather than dropping frames, so a
            weaker GPU loses sharpness instead of responsiveness. The dpr floor
            stays at 1 so it never goes below native.
          */}
          <PerformanceMonitor
            onChange={({ factor }) => setPerformanceFactor(factor)}
          />
          <AdaptiveDpr pixelated={false} />
          <color attach="background" args={['#0e0e11']} />
          {/* Pushed back and lightened: the diorama blur now does the depth work, and dense fog would fight it. */}
          <fog attach="fog" args={['#3a3a41', 30, 62]} />
          {/*
            High-key diorama lighting, in the Echoes of Wisdom sense: the model
            is lit like an object on a table rather than a place you are inside.
            Ambient and hemisphere carry most of the exposure so nothing falls
            to black, and the key is softened to a shaping light rather than the
            source of the image. Shadows stay present but light — that family
            never crushes a shadow, which is most of why it reads as a toy.
          */}
          <ambientLight intensity={0.62} color="#d6d6de" />
          <hemisphereLight args={['#e8e8ee', '#26262c', 0.85]} />
          <directionalLight
            castShadow
            position={[-8, 15, 6]}
            intensity={1.35}
            color="#ffffff"
            shadow-mapSize={[1024, 1024]}
            shadow-camera-left={-16}
            shadow-camera-right={16}
            shadow-camera-top={16}
            shadow-camera-bottom={-16}
            shadow-bias={-0.00035}
            shadow-normalBias={0.025}
          />
          {/*
            Back-rim from the opposite side. Pushed up so SD silhouettes get a
            cool edge separating them from the ground — the single cheapest way
            to make a chibi model read as drawn rather than extruded.
          */}
          <directionalLight
            position={[9, 10, -11]}
            intensity={0.4}
            color="#9a9aa4"
          />
          <Suspense fallback={null}>
            <SceneContent
              onEncounterEvent={onEncounterEvent}
              onAdvanceRoom={onAdvanceRoom}
            />
            <ContentReadySignal onReady={markContentReady} />
            <ScenePreparation
              preparationKey={preparationKey}
              onReady={onPreparationReady}
              onFatalError={onFatalError}
            />
          </Suspense>
          <PostProcessing
            onReady={markPostProcessingReady}
            onFatalError={onFatalError}
          />
          <SceneWarmup
            contentReady={contentReady}
            postProcessingReady={postProcessingReady}
            enabled={warmup}
            onLoadProgress={onLoadProgress}
            onReady={onReady}
            onFatalError={onFatalError}
          />
        </Canvas>
      </SceneErrorBoundary>
    </div>
  )
}

/**
 * Memoized because App renders it alongside state that changes during combat.
 * Callback and scalar props are stable at the call site, so the
 * comparison actually bails out rather than re-pushing the whole scene graph.
 */
export const GameScene = memo(GameSceneImpl)
