import type { ObservationMode } from '../game/types'

export type GazeRuleMarkerKind = 'o' | 'x' | 'ox'

export interface EnemyFreezeState {
  readonly frozen: boolean
  readonly gazeObserved: boolean
}

/** Separates physical pause from the gaze-only state consumed by HUD/runes. */
export function resolveEnemyFreezeState(
  mode: ObservationMode,
  policyFrozen: boolean,
  dispelActive: boolean,
): EnemyFreezeState {
  const frozen = !dispelActive && policyFrozen
  return {
    frozen,
    gazeObserved: frozen && mode !== 'inverse-freeze',
  }
}

/** Returns the single circular marker rendered above an enemy health bar. */
export function resolveGazeRuleMarker(
  mode: ObservationMode,
  dispelActive: boolean,
  observationBroken: boolean,
): GazeRuleMarkerKind | null {
  if (mode === 'inverse-freeze') return dispelActive ? 'ox' : 'o'
  return mode === 'immune' || dispelActive || observationBroken ? 'x' : null
}
