import { useFrame, useThree } from '@react-three/fiber'
import { N8AOPostPass } from 'n8ao'
import {
  BloomEffect,
  EffectComposer,
  EffectPass,
  KernelSize,
  RenderPass,
  SMAAEffect,
  SMAAPreset,
  TiltShiftEffect,
} from 'postprocessing'
import { useCallback, useEffect, useRef } from 'react'

import { useGameStore } from '../runtime/gameStore'
import {
  ToonGradeEffect,
  TOON_GRADE_FULL,
  TOON_GRADE_REDUCED_MOTION,
} from './ToonGradeEffect'
import {
  isFlatDarkFrame,
  nextPostProcessingMode,
  type PostProcessingMode,
} from './postProcessingHealth'

const BLOOM_LUMINANCE_THRESHOLD = 0.92
const HEALTH_CHECK_START_FRAME = 45
const HEALTH_CHECK_INTERVAL = 15
const HEALTH_CHECK_FAILURE_LIMIT = 3
const HEALTH_SAMPLE_SIZE = 48
const MINIATURE_BLEND_OPACITY = 0.1

const MINIATURE_OPTIONS = {
  offset: 0.04,
  rotation: 0,
  focusArea: 0.58,
  feather: 0.3,
  kernelSize: KernelSize.MEDIUM,
  resolutionScale: 0.5,
} as const

export function PostProcessing({
  onReady,
}: {
  onReady?: () => void
  onFatalError?: (error: Error) => void
}) {
  const gl = useThree((state) => state.gl)
  const scene = useThree((state) => state.scene)
  const camera = useThree((state) => state.camera)
  const size = useThree((state) => state.size)
  const dpr = useThree((state) => state.viewport.dpr)
  const reducedMotion = useGameStore((state) => state.settings.reducedMotion)
  const composerRef = useRef<EffectComposer | null>(null)
  const gradeRef = useRef<ToonGradeEffect | null>(null)
  const bloomRef = useRef<BloomEffect | null>(null)
  const aoRef = useRef<N8AOPostPass | null>(null)
  const tiltShiftRef = useRef<TiltShiftEffect | null>(null)
  const onReadyRef = useRef(onReady)
  const renderModeRef = useRef<PostProcessingMode>('full')
  const createSafeComposerRef = useRef<(() => EffectComposer) | null>(null)
  const warnedModesRef = useRef(new Set<PostProcessingMode>())
  const healthFrameRef = useRef(0)
  const darkFrameCountRef = useRef(0)

  useEffect(() => {
    onReadyRef.current = onReady
  }, [onReady])

  const clearEffectRefs = useCallback(() => {
    gradeRef.current = null
    bloomRef.current = null
    aoRef.current = null
    tiltShiftRef.current = null
  }, [])

  const transitionAfterFailure = useCallback(
    (reason: string) => {
      const nextMode = nextPostProcessingMode(renderModeRef.current)
      composerRef.current?.dispose()
      composerRef.current = null
      clearEffectRefs()
      healthFrameRef.current = 0
      darkFrameCountRef.current = 0

      if (nextMode === 'miniature-safe') {
        try {
          const safeComposer = createSafeComposerRef.current?.()
          if (!safeComposer) throw new Error('safe composer unavailable')
          composerRef.current = safeComposer
          renderModeRef.current = nextMode
          if (!warnedModesRef.current.has(nextMode)) {
            warnedModesRef.current.add(nextMode)
            console.warn(
              `[BODA] Full post-processing disabled; keeping miniature mode: ${reason}`,
            )
          }
          return
        } catch (cause) {
          reason = cause instanceof Error ? cause.message : reason
        }
      }

      renderModeRef.current = 'raw'
      if (!warnedModesRef.current.has('raw')) {
        warnedModesRef.current.add('raw')
        console.warn(
          `[BODA] Post-processing disabled; using raw WebGL: ${reason}`,
        )
      }
    },
    [clearEffectRefs],
  )

  useEffect(() => {
    renderModeRef.current = 'full'
    healthFrameRef.current = 0
    darkFrameCountRef.current = 0

    const createTiltShift = () => {
      const tiltShift = new TiltShiftEffect(MINIATURE_OPTIONS)
      tiltShift.blendMode.opacity.value = MINIATURE_BLEND_OPACITY
      return tiltShift
    }
    createSafeComposerRef.current = () => {
      const composer = new EffectComposer(gl, { multisampling: 0 })
      try {
        composer.addPass(new RenderPass(scene, camera))
        const tiltShift = createTiltShift()
        tiltShiftRef.current = tiltShift
        composer.addPass(new EffectPass(camera, tiltShift))
        composer.setSize(size.width, size.height)
        return composer
      } catch (cause) {
        composer.dispose()
        throw cause
      }
    }

    const warnOptionalPass = (name: string, cause: unknown) => {
      console.warn(`[BODA] ${name} post-process pass unavailable`, cause)
    }

    try {
      const composer = new EffectComposer(gl, { multisampling: 0 })
      composerRef.current = composer
      composer.addPass(new RenderPass(scene, camera))

      try {
        const ao = new N8AOPostPass(scene, camera, size.width, size.height)
        ao.configuration.aoRadius = 0.34
        ao.configuration.distanceFalloff = 0.35
        ao.configuration.intensity = 2.4
        ao.configuration.color.set('#0a1020')
        ao.configuration.halfRes = false
        composer.addPass(ao)
        aoRef.current = ao
      } catch (cause) {
        warnOptionalPass('N8AO', cause)
      }

      try {
        const grade = new ToonGradeEffect(
          reducedMotion ? TOON_GRADE_REDUCED_MOTION : TOON_GRADE_FULL,
        )
        gradeRef.current = grade
        composer.addPass(new EffectPass(camera, grade))
      } catch (cause) {
        warnOptionalPass('toon grade', cause)
      }

      try {
        const tiltShift = createTiltShift()
        const bloom = new BloomEffect({
          luminanceThreshold: BLOOM_LUMINANCE_THRESHOLD,
          luminanceSmoothing: 0.12,
          intensity: 1.15,
          kernelSize: KernelSize.MEDIUM,
          mipmapBlur: true,
        })
        const smaa = new SMAAEffect({ preset: SMAAPreset.MEDIUM })
        tiltShiftRef.current = tiltShift
        bloomRef.current = bloom
        composer.addPass(new EffectPass(camera, tiltShift, bloom, smaa))
      } catch (cause) {
        warnOptionalPass('finishing', cause)
        try {
          const tiltShift = createTiltShift()
          tiltShiftRef.current = tiltShift
          composer.addPass(new EffectPass(camera, tiltShift))
        } catch (tiltCause) {
          warnOptionalPass('miniature', tiltCause)
        }
      }

      composer.setSize(size.width, size.height)
      onReadyRef.current?.()
    } catch (cause) {
      transitionAfterFailure(
        cause instanceof Error
          ? cause.message
          : 'post-processing initialization failed',
      )
      onReadyRef.current?.()
    }

    return () => {
      composerRef.current?.dispose()
      composerRef.current = null
      createSafeComposerRef.current = null
      clearEffectRefs()
    }
    // Reduced-motion values are pushed imperatively below to avoid rebuilding
    // and recompiling the shader chain in the middle of a run.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [camera, gl, scene, transitionAfterFailure])

  useEffect(() => {
    composerRef.current?.setSize(size.width, size.height)
    aoRef.current?.setSize(size.width, size.height)
  }, [size.height, size.width])

  useEffect(() => {
    gl.setPixelRatio(dpr)
  }, [dpr, gl])

  useEffect(() => {
    gradeRef.current?.applyValues(
      reducedMotion ? TOON_GRADE_REDUCED_MOTION : TOON_GRADE_FULL,
    )
    const bloom = bloomRef.current
    if (bloom) {
      bloom.intensity = reducedMotion ? 0.55 : 1.15
      bloom.luminanceMaterial.threshold = reducedMotion
        ? 1.1
        : BLOOM_LUMINANCE_THRESHOLD
    }
    const ao = aoRef.current
    if (ao) ao.configuration.intensity = reducedMotion ? 1.8 : 2.6
  }, [reducedMotion])

  useFrame((state, delta) => {
    const composer = composerRef.current
    if (!composer) {
      state.gl.render(state.scene, state.camera)
      return
    }

    try {
      composer.render(delta)
    } catch (cause) {
      transitionAfterFailure(
        cause instanceof Error ? cause.message : 'composer render failed',
      )
      if (!composerRef.current) state.gl.render(state.scene, state.camera)
      return
    }

    healthFrameRef.current += 1
    const healthFrame = healthFrameRef.current
    if (
      healthFrame < HEALTH_CHECK_START_FRAME ||
      healthFrame % HEALTH_CHECK_INTERVAL !== 0
    ) {
      return
    }

    let visibleMeshes = 0
    state.scene.traverse((object) => {
      if (
        object.visible &&
        (object as typeof object & { isMesh?: boolean }).isMesh
      ) {
        visibleMeshes += 1
      }
    })
    if (visibleMeshes < 3) return

    try {
      const context = state.gl.getContext()
      const width = Math.min(HEALTH_SAMPLE_SIZE, state.gl.domElement.width)
      const height = Math.min(HEALTH_SAMPLE_SIZE, state.gl.domElement.height)
      if (width <= 0 || height <= 0) return
      const pixels = new Uint8Array(width * height * 4)
      const x = Math.max(0, Math.floor((state.gl.domElement.width - width) / 2))
      const y = Math.max(
        0,
        Math.floor((state.gl.domElement.height - height) / 2),
      )
      context.readPixels(
        x,
        y,
        width,
        height,
        context.RGBA,
        context.UNSIGNED_BYTE,
        pixels,
      )
      darkFrameCountRef.current = isFlatDarkFrame(pixels)
        ? darkFrameCountRef.current + 1
        : 0
      if (darkFrameCountRef.current >= HEALTH_CHECK_FAILURE_LIMIT) {
        transitionAfterFailure('flat black output detected')
      }
    } catch {
      // Readback is diagnostic only; render exceptions still use the fallback.
      healthFrameRef.current = Number.NEGATIVE_INFINITY
    }
  }, 1)

  return null
}
