import { useFrame, useThree } from '@react-three/fiber'
import {
  CapsuleCollider,
  RigidBody,
  interactionGroups,
  type RapierRigidBody,
  useBeforePhysicsStep,
  useRapier,
} from '@react-three/rapier'
import { useCallback, useEffect, useMemo, useRef, type RefObject } from 'react'
import {
  BackSide,
  Group,
  MathUtils,
  Mesh,
  Plane,
  Quaternion,
  Raycaster,
  Vector2,
  Vector3,
} from 'three'

import {
  resolveAfterimageHit,
  resolveDodgeRuneRules,
  resolveRuneAttack,
} from '../game'
import { audioEngine } from '../runtime/audio'
import { makeRuntimeId, useGameStore } from '../runtime/gameStore'
import { useTouchInputMode } from '../runtime/inputMode'
import { runtime } from '../runtime/registry'
import {
  AnimatedCharacterModel,
  AssetBoundary,
  assetUrl,
  setCharacterMotion,
  type CharacterMotionState,
  type ModelAttachment,
} from './AssetModels'
import {
  clampCameraAnchorToRoom,
  getCameraFramingInsets,
} from './cameraFraming'
import { quaternionFromNegativeZForward } from './direction'
import { advanceGameplayElapsed, isActiveGameplayPhase } from './gameplayClock'
import { requestHitstop } from './hitstop'
import { resolvePlayerLocomotion } from './playerLocomotion'
import { shouldRepeatHeldAttack } from './playerAttackInput'
import { resolveTouchFacing } from './touchFacing'
import { TOON_PALETTE, toonGradientMap } from './toonMaterials'

const FIXED_STEP = 1 / 60
const UP = new Vector3(0, 1, 0)
const GROUND_PLANE = new Plane(UP, 0)
const ATTACK_ARC_HALF_DEG = 72
const PLAYER_ATTACK_ANIMATION_SECONDS = 0.28
const PLAYER_HIT_REACTION_SECONDS = 0.16
const PLAYER_HIT_STAGGER_SECONDS = 0.12
const DODGE_DURATION_SECONDS = 0.18
const DODGE_SPEED_MULTIPLIER = 2
const DODGE_INVULNERABILITY_EXTENSION_SECONDS = 0.05
/** How long a blocked attack or dodge press stays valid before it expires. */
const INPUT_BUFFER_SECONDS = 0.14
const PLAYER_ATTACHMENTS: readonly ModelAttachment[] = [
  { url: assetUrl('models/weapons/sword.glb') },
]
function ProceduralPlayerVisual({
  swordRef,
}: {
  swordRef: RefObject<Group | null>
}) {
  return (
    <group name="player-procedural-fallback">
      <group scale={1.055}>
        <mesh position={[0, 0.08, 0]}>
          <capsuleGeometry args={[0.38, 0.7, 5, 10]} />
          <meshBasicMaterial color={TOON_PALETTE.ink} side={BackSide} />
        </mesh>
        <mesh position={[0, 0.58, -0.02]}>
          <sphereGeometry args={[0.31, 12, 9]} />
          <meshBasicMaterial color={TOON_PALETTE.ink} side={BackSide} />
        </mesh>
      </group>
      <mesh castShadow position={[0, 0.08, 0]}>
        <capsuleGeometry args={[0.36, 0.68, 6, 10]} />
        <meshToonMaterial
          color={TOON_PALETTE.indigoLight}
          gradientMap={toonGradientMap}
        />
      </mesh>
      <mesh castShadow position={[0, 0.58, -0.02]}>
        <sphereGeometry args={[0.29, 12, 10]} />
        <meshToonMaterial
          color={TOON_PALETTE.white}
          gradientMap={toonGradientMap}
        />
      </mesh>
      <mesh castShadow position={[0, 0.12, 0.2]} rotation={[0.18, 0, 0]}>
        <coneGeometry args={[0.5, 1.08, 7, 1, true]} />
        <meshToonMaterial
          color={TOON_PALETTE.coral}
          gradientMap={toonGradientMap}
          side={2}
        />
      </mesh>
      <group ref={swordRef} position={[0.43, 0.16, -0.2]}>
        <mesh castShadow position={[0, 0, -0.38]}>
          <boxGeometry args={[0.09, 0.09, 1.18]} />
          <meshToonMaterial
            color={TOON_PALETTE.white}
            gradientMap={toonGradientMap}
          />
        </mesh>
        <mesh position={[0, 0, 0.14]}>
          <boxGeometry args={[0.34, 0.09, 0.09]} />
          <meshToonMaterial
            color={TOON_PALETTE.gold}
            gradientMap={toonGradientMap}
          />
        </mesh>
      </group>
      <mesh position={[0, 0.58, -0.28]}>
        <boxGeometry args={[0.28, 0.075, 0.045]} />
        <meshBasicMaterial color={TOON_PALETTE.cyanLight} toneMapped={false} />
      </mesh>
    </group>
  )
}

interface PlayerProps {
  readonly spawn: { x: number; z: number }
  readonly roomSize: { x: number; z: number }
}

export function Player({ spawn, roomSize }: PlayerProps) {
  const bodyRef = useRef<RapierRigidBody>(null)
  const hitReactionRef = useRef<Group>(null)
  const visualRef = useRef<Group>(null)
  const swordRef = useRef<Group>(null)
  const simulatedPosition = useRef(new Vector3(spawn.x, 0.8, spawn.z))
  // Buffered action state (attack/dodge requests) lives in the runtime
  // registry so touch buttons can file the same requests as keyboard/mouse.
  const dodgeDirection = useRef(new Vector3())
  const dodgeRemainingDistance = useRef(0)
  const dodgeSpeed = useRef(0)
  const dodgeReadyAt = useRef(0)
  const dodgeReadyCuePending = useRef(false)
  const dodgeCooldownRingRef = useRef<Mesh>(null)
  const attackReadyAt = useRef(0)
  const attackAnimationEndsAt = useRef(0)
  const successfulMeleeHitCount = useRef(0)
  const lastDodgeEndAt = useRef<number | null>(null)
  const afterimageResolved = useRef(true)
  const hitStaggerEndsAt = useRef(0)
  const hitReactionRemaining = useRef(0)
  const lastFootstepAt = useRef(0)
  const motionRef = useRef<CharacterMotionState>({
    motion: 'idle',
    revision: 0,
  })
  const phase = useGameStore((state) => state.phase)
  const touchMode = useTouchInputMode()
  const lastPlayerHit = useGameStore((state) => state.lastPlayerHit)
  const roomIndex = useGameStore((state) => state.roomIndex)
  const runId = useGameStore((state) => state.runId)
  const { camera, gl, size } = useThree()
  const { world, rapier } = useRapier()
  const raycaster = useMemo(() => new Raycaster(), [])
  const pointer = useMemo(() => new Vector2(), [])
  const aimPoint = useMemo(() => new Vector3(), [])
  const aimFacing = useMemo(() => new Vector3(), [])
  const desiredCamera = useMemo(() => new Vector3(), [])
  const desiredLookTarget = useMemo(() => new Vector3(), [])
  const smoothedLookTarget = useRef(new Vector3(spawn.x, 0, spawn.z - 0.7))
  const cameraAnchor = useMemo(() => new Vector3(), [])
  const cameraFramingInsets = useMemo(
    () => getCameraFramingInsets(size.width / Math.max(1, size.height)),
    [size.height, size.width],
  )
  const cameraFramingInsetsRef = useRef(cameraFramingInsets)
  const roomHalfX = roomSize.x / 2
  const roomHalfZ = roomSize.z / 2
  const targetRotation = useMemo(() => new Quaternion(), [])
  const physicsMove = useMemo(() => new Vector3(), [])
  const physicsVelocity = useMemo(() => new Vector3(), [])

  useEffect(() => {
    cameraFramingInsetsRef.current = cameraFramingInsets
  }, [cameraFramingInsets])

  useEffect(() => {
    simulatedPosition.current.set(spawn.x, 0.8, spawn.z)
    runtime.playerPosition.copy(simulatedPosition.current)
    bodyRef.current?.setTranslation(simulatedPosition.current, true)
    bodyRef.current?.setLinvel({ x: 0, y: 0, z: 0 }, true)
    dodgeRemainingDistance.current = 0
    dodgeReadyCuePending.current = false
    successfulMeleeHitCount.current = 0
    lastDodgeEndAt.current = null
    afterimageResolved.current = true
    const anchorX = clampCameraAnchorToRoom(
      spawn.x,
      -roomHalfX,
      roomHalfX,
      cameraFramingInsetsRef.current.x,
    )
    const anchorZ = clampCameraAnchorToRoom(
      spawn.z,
      -roomHalfZ,
      roomHalfZ,
      cameraFramingInsetsRef.current.z,
    )
    desiredCamera.set(anchorX, 13.5, anchorZ + 9.5)
    camera.position.copy(desiredCamera)
    smoothedLookTarget.current.set(anchorX, 0, anchorZ - 0.7)
    camera.lookAt(smoothedLookTarget.current)
  }, [
    camera,
    desiredCamera,
    roomHalfX,
    roomHalfZ,
    roomIndex,
    runId,
    spawn.x,
    spawn.z,
  ])

  const updateAimFromPointer = useCallback(() => {
    raycaster.setFromCamera(runtime.pointerNdc, camera)
    if (!raycaster.ray.intersectPlane(GROUND_PLANE, aimPoint)) return false
    const facing = aimFacing
      .copy(aimPoint)
      .sub(simulatedPosition.current)
      .setY(0)
    if (facing.lengthSq() <= 0.02) return false
    runtime.playerFacing.copy(facing.normalize())
    quaternionFromNegativeZForward(runtime.playerFacing, targetRotation)
    visualRef.current?.quaternion.copy(targetRotation)
    return true
  }, [aimFacing, aimPoint, camera, raycaster, targetRotation])

  const updatePointerNdc = useCallback(
    (event: PointerEvent) => {
      const bounds = gl.domElement.getBoundingClientRect()
      if (bounds.width <= 0 || bounds.height <= 0) return
      pointer.set(
        ((event.clientX - bounds.left) / bounds.width) * 2 - 1,
        -((event.clientY - bounds.top) / bounds.height) * 2 + 1,
      )
      runtime.pointerNdc.copy(pointer)
    },
    [gl.domElement, pointer],
  )

  const performAttack = useCallback(
    (bufferIfBlocked = true) => {
      const state = useGameStore.getState()
      if (!isActiveGameplayPhase(state.phase)) return
      if (
        runtime.elapsed < attackReadyAt.current ||
        runtime.elapsed < hitStaggerEndsAt.current
      ) {
        // Blocked press becomes a buffered request instead of vanishing.
        if (bufferIfBlocked) runtime.attackRequestedAt = runtime.elapsed
        return
      }
      runtime.attackRequestedAt = Number.NEGATIVE_INFINITY

      attackReadyAt.current =
        runtime.elapsed + state.stats.attackCooldownMs / 1_000
      attackAnimationEndsAt.current =
        runtime.elapsed + PLAYER_ATTACK_ANIMATION_SECONDS
      setCharacterMotion(motionRef, 'attack', true)
      audioEngine.unlock()
      audioEngine.play('attack')

      const origin = runtime.playerPosition
      const attackDirection = runtime.playerFacing.clone().setY(0).normalize()
      const minimumDot = Math.cos(MathUtils.degToRad(ATTACK_ARC_HALF_DEG))
      const runeIds = state.selectedRunes
      const priorSuccessfulHitCount = successfulMeleeHitCount.current
      const timeSinceDodgeEndMs =
        lastDodgeEndAt.current === null
          ? null
          : Math.max(0, (runtime.elapsed - lastDodgeEndAt.current) * 1_000)
      let connected = false
      let nextSuccessfulHitCount = priorSuccessfulHitCount
      let consumesCounterStep = false
      let strongestMultiplier = 1

      for (const enemy of runtime.enemies.values()) {
        const toEnemy = enemy.position.clone().sub(origin).setY(0)
        const distance = toEnemy.length()
        if (distance > state.stats.attackRange || distance < 0.001) continue
        if (toEnemy.normalize().dot(attackDirection) < minimumDot) continue

        const sightline = enemy.position.clone().sub(origin)
        sightline.y = 0
        sightline.normalize()
        const ray = new rapier.Ray(
          { x: origin.x, y: 0.72, z: origin.z },
          { x: sightline.x, y: 0, z: sightline.z },
        )
        const queryFlags =
          rapier.QueryFilterFlags.EXCLUDE_DYNAMIC |
          rapier.QueryFilterFlags.EXCLUDE_KINEMATIC
        if (world.castRay(ray, Math.max(0, distance - 0.2), true, queryFlags)) {
          continue
        }
        const resolution = resolveRuneAttack({
          baseDamage: state.stats.attackDamage,
          runeIds,
          targetHealthRatio: enemy.healthRatio,
          targetObserved: enemy.observed,
          continuousObservedMs: enemy.continuousObservedMs,
          timeSinceDodgeEndMs,
          successfulMeleeHitCount: priorSuccessfulHitCount,
        })
        enemy.takeHit(resolution.damage, attackDirection, 8)
        if (!connected) {
          nextSuccessfulHitCount = resolution.nextSuccessfulMeleeHitCount
          consumesCounterStep = resolution.consumesCounterStep
        }
        connected = true
        strongestMultiplier = Math.max(
          strongestMultiplier,
          resolution.multiplier,
        )
      }

      if (connected) {
        successfulMeleeHitCount.current = nextSuccessfulHitCount
        if (consumesCounterStep) lastDodgeEndAt.current = null
        // A rune-boosted swing holds longer than a plain one, so the extra
        // damage is something the player feels rather than only reads.
        requestHitstop(strongestMultiplier > 1 ? 0.075 : 0.045)
        if (strongestMultiplier > 1) {
          state.spawnEffect({
            id: makeRuntimeId('rune-strike'),
            kind: 'burst',
            position: [origin.x, 0.34, origin.z],
            direction: [attackDirection.x, 0, attackDirection.z],
            color: TOON_PALETTE.goldLight,
            durationMs: 260,
            variant: 'rune',
          })
        }
      }

      runtime.cameraTrauma = Math.max(runtime.cameraTrauma, 0.16)
      state.spawnEffect({
        id: makeRuntimeId('slash'),
        kind: 'slash',
        position: [origin.x, 0.32, origin.z],
        direction: [attackDirection.x, 0, attackDirection.z],
        color: '#ffffff',
        durationMs: 220,
        length: state.stats.attackRange,
        width: 1.45,
        variant: 'arc',
      })
      runtime.slashRevision += 1
      runtime.lastSlashDirection.copy(attackDirection)
    },
    [rapier, world],
  )

  useEffect(() => {
    if (!lastPlayerHit) return
    requestHitstop(0.06)
    hitReactionRemaining.current = PLAYER_HIT_REACTION_SECONDS
    hitStaggerEndsAt.current = runtime.elapsed + PLAYER_HIT_STAGGER_SECONDS
    attackAnimationEndsAt.current = 0
    const state = useGameStore.getState()
    if (state.phase !== 'defeat' && !state.settings.reducedMotion) {
      setCharacterMotion(motionRef, 'hit', true)
    }
  }, [lastPlayerHit])

  useEffect(() => {
    if (phase === 'defeat') setCharacterMotion(motionRef, 'death', true)
  }, [phase])

  useEffect(() => {
    const canvas = gl.domElement

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.code === 'Escape' && !event.repeat) {
        event.preventDefault()
        useGameStore.getState().togglePause()
        return
      }

      const target = event.target
      const isInteractive =
        target instanceof Element &&
        target.closest(
          'button, input, select, textarea, a[href], [contenteditable="true"]',
        ) !== null
      if (
        !isActiveGameplayPhase(useGameStore.getState().phase) ||
        isInteractive
      )
        return

      if (['KeyW', 'KeyA', 'KeyS', 'KeyD'].includes(event.code)) {
        runtime.pressedKeys.add(event.code)
      }
      if (event.code === 'Space' && !event.repeat) {
        event.preventDefault()
        runtime.dodgeRequestedAt = runtime.elapsed
      }
    }
    const handleKeyUp = (event: KeyboardEvent) =>
      runtime.pressedKeys.delete(event.code)
    // In touch mode gameplay touches flow only through the TouchControls
    // layer; a stray canvas touch must neither swing the sword nor drag the
    // gaze, and lifting a stick finger must not release the attack button.
    const handlePointerMove = (event: PointerEvent) => {
      if (touchMode && event.pointerType === 'touch') return
      updatePointerNdc(event)
    }
    const handlePointerDown = (event: PointerEvent) => {
      if (touchMode && event.pointerType === 'touch') return
      if (event.button !== 0) return
      if (!isActiveGameplayPhase(useGameStore.getState().phase)) return
      runtime.attackHeld = true
      updatePointerNdc(event)
      updateAimFromPointer()
      performAttack()
    }
    const handlePointerUp = (event: PointerEvent) => {
      if (touchMode && event.pointerType === 'touch') return
      if (event.button === 0) runtime.attackHeld = false
    }
    const handlePointerCancel = () => {
      runtime.attackHeld = false
    }
    const handleContextMenu = (event: Event) => event.preventDefault()
    const handleBlur = () => {
      runtime.pressedKeys.clear()
      runtime.attackHeld = false
      if (isActiveGameplayPhase(useGameStore.getState().phase))
        useGameStore.getState().togglePause()
    }

    window.addEventListener('keydown', handleKeyDown)
    window.addEventListener('keyup', handleKeyUp)
    window.addEventListener('blur', handleBlur)
    window.addEventListener('pointerup', handlePointerUp)
    window.addEventListener('pointercancel', handlePointerCancel)
    canvas.addEventListener('pointermove', handlePointerMove)
    canvas.addEventListener('pointerdown', handlePointerDown)
    canvas.addEventListener('contextmenu', handleContextMenu)
    runtime.playerInputReady = true
    return () => {
      runtime.playerInputReady = false
      window.removeEventListener('keydown', handleKeyDown)
      window.removeEventListener('keyup', handleKeyUp)
      window.removeEventListener('blur', handleBlur)
      window.removeEventListener('pointerup', handlePointerUp)
      window.removeEventListener('pointercancel', handlePointerCancel)
      canvas.removeEventListener('pointermove', handlePointerMove)
      canvas.removeEventListener('pointerdown', handlePointerDown)
      canvas.removeEventListener('contextmenu', handleContextMenu)
    }
  }, [
    gl.domElement,
    performAttack,
    touchMode,
    updateAimFromPointer,
    updatePointerNdc,
  ])

  useBeforePhysicsStep(() => {
    const body = bodyRef.current
    if (!body) return

    const state = useGameStore.getState()
    if (!isActiveGameplayPhase(state.phase)) {
      runtime.attackHeld = false
      body.setLinvel({ x: 0, y: 0, z: 0 }, true)
      return
    }

    const translation = body.translation()
    simulatedPosition.current.set(translation.x, 0.8, translation.z)
    runtime.playerPosition.copy(simulatedPosition.current)

    physicsMove.set(
      (runtime.pressedKeys.has('KeyD') ? 1 : 0) -
        (runtime.pressedKeys.has('KeyA') ? 1 : 0) +
        runtime.moveInput.x,
      0,
      (runtime.pressedKeys.has('KeyS') ? 1 : 0) -
        (runtime.pressedKeys.has('KeyW') ? 1 : 0) +
        runtime.moveInput.y,
    )
    if (physicsMove.lengthSq() > 1) physicsMove.normalize()
    if (
      physicsMove.lengthSq() > 0.01 &&
      dodgeRemainingDistance.current <= Number.EPSILON &&
      runtime.elapsed - lastFootstepAt.current >= 0.34
    ) {
      lastFootstepAt.current = runtime.elapsed
      audioEngine.play('footstep')
    }

    // A held button repeats exactly when both the cooldown and hit stagger
    // clear. A released click still keeps the short input-buffer behavior.
    if (
      shouldRepeatHeldAttack(
        runtime.attackHeld,
        runtime.elapsed,
        attackReadyAt.current,
        hitStaggerEndsAt.current,
      )
    ) {
      performAttack(false)
    } else if (
      runtime.elapsed - runtime.attackRequestedAt <=
      INPUT_BUFFER_SECONDS
    ) {
      performAttack(false)
    }

    const isStaggered = runtime.elapsed < hitStaggerEndsAt.current
    if (
      dodgeReadyCuePending.current &&
      runtime.elapsed >= dodgeReadyAt.current
    ) {
      dodgeReadyCuePending.current = false
      audioEngine.play('dash-ready')
    }
    if (
      !isStaggered &&
      runtime.elapsed - runtime.dodgeRequestedAt <= INPUT_BUFFER_SECONDS &&
      runtime.elapsed >= dodgeReadyAt.current
    ) {
      runtime.dodgeRequestedAt = Number.NEGATIVE_INFINITY
      const direction =
        physicsMove.lengthSq() > 0 ? physicsMove : runtime.playerFacing
      dodgeDirection.current.copy(direction).setY(0).normalize()
      dodgeSpeed.current = state.stats.moveSpeed * DODGE_SPEED_MULTIPLIER
      dodgeRemainingDistance.current =
        dodgeSpeed.current * DODGE_DURATION_SECONDS
      afterimageResolved.current = false
      dodgeReadyAt.current =
        runtime.elapsed + state.stats.dodgeCooldownMs / 1_000
      dodgeReadyCuePending.current = true
      const dodgeRuneRules = resolveDodgeRuneRules(
        state.selectedRunes,
        state.stats.attackDamage,
      )
      runtime.playerInvulnerableUntil =
        runtime.elapsed +
        DODGE_DURATION_SECONDS +
        DODGE_INVULNERABILITY_EXTENSION_SECONDS +
        dodgeRuneRules.invulnerabilityDurationMs / 1_000
      audioEngine.play('dash')
      state.spawnEffect({
        id: makeRuntimeId('dash'),
        kind: 'dash',
        position: [
          simulatedPosition.current.x,
          0.34,
          simulatedPosition.current.z,
        ],
        direction: [dodgeDirection.current.x, 0, dodgeDirection.current.z],
        color: '#ffffff',
        durationMs: 260,
      })
    }
    const isDodging =
      !isStaggered && dodgeRemainingDistance.current > Number.EPSILON
    let direction = physicsMove
    let speed = state.stats.moveSpeed
    if (isStaggered) {
      direction = physicsVelocity.set(0, 0, 0)
      speed = 0
    } else if (isDodging) {
      direction = dodgeDirection.current
      const stepDistance = Math.min(
        dodgeRemainingDistance.current,
        dodgeSpeed.current * FIXED_STEP,
      )
      speed = stepDistance / FIXED_STEP
      dodgeRemainingDistance.current = Math.max(
        0,
        dodgeRemainingDistance.current - stepDistance,
      )
      if (
        dodgeRemainingDistance.current <= Number.EPSILON &&
        !afterimageResolved.current
      ) {
        afterimageResolved.current = true
        lastDodgeEndAt.current = runtime.elapsed
        const runeIds = state.selectedRunes
        let afterimageHit = false
        for (const enemy of runtime.enemies.values()) {
          const offset = enemy.position
            .clone()
            .sub(simulatedPosition.current)
            .setY(0)
          const damage = resolveAfterimageHit(
            runeIds,
            offset.length(),
            false,
            state.stats.attackDamage,
          )
          if (damage <= 0) continue
          const direction =
            offset.lengthSq() > 0.001
              ? offset.normalize()
              : dodgeDirection.current.clone().multiplyScalar(-1)
          enemy.takeHit(damage, direction, 5)
          afterimageHit = true
        }
        if (afterimageHit) {
          requestHitstop(0.05)
          state.spawnEffect({
            id: makeRuntimeId('afterimage-burst'),
            kind: 'burst',
            position: [
              simulatedPosition.current.x,
              0.28,
              simulatedPosition.current.z,
            ],
            direction: [
              -dodgeDirection.current.x,
              0,
              -dodgeDirection.current.z,
            ],
            color: TOON_PALETTE.cyanLight,
            durationMs: 340,
            width: 1.8,
            variant: 'sigil',
          })
        }
      }
    }

    physicsVelocity.copy(direction).multiplyScalar(speed)
    body.setLinvel({ x: physicsVelocity.x, y: 0, z: physicsVelocity.z }, true)
    if (!isStaggered && runtime.elapsed >= attackAnimationEndsAt.current) {
      setCharacterMotion(
        motionRef,
        resolvePlayerLocomotion(
          direction.x,
          direction.z,
          runtime.playerFacing.x,
          runtime.playerFacing.z,
        ),
      )
    }
  })

  useFrame((_, frameDelta) => {
    const state = useGameStore.getState()
    const delta = Math.min(frameDelta, 0.1)
    const body = bodyRef.current
    if (body) {
      const translation = body.translation()
      simulatedPosition.current.set(translation.x, 0.8, translation.z)
      runtime.playerPosition.copy(simulatedPosition.current)
    }
    const cameraTarget = simulatedPosition.current
    cameraAnchor.set(
      clampCameraAnchorToRoom(
        cameraTarget.x,
        -roomHalfX,
        roomHalfX,
        cameraFramingInsetsRef.current.x,
      ),
      0,
      clampCameraAnchorToRoom(
        cameraTarget.z,
        -roomHalfZ,
        roomHalfZ,
        cameraFramingInsetsRef.current.z,
      ),
    )
    const trauma = state.settings.reducedMotion ? 0 : runtime.cameraTrauma
    const cameraKick = state.settings.reducedMotion ? 0 : runtime.cameraKick
    const shakeX = Math.sin(runtime.elapsed * 79) * trauma * trauma * 0.16
    const shakeZ = Math.cos(runtime.elapsed * 91) * trauma * trauma * 0.12
    desiredCamera.set(
      cameraAnchor.x +
        shakeX -
        runtime.playerHitDirection.x * cameraKick * 0.38,
      13.5,
      cameraAnchor.z +
        9.5 +
        shakeZ -
        runtime.playerHitDirection.z * cameraKick * 0.3,
    )
    camera.position.lerp(desiredCamera, 1 - Math.exp(-delta * 6))
    desiredLookTarget.set(cameraAnchor.x, 0, cameraAnchor.z - 0.7)
    smoothedLookTarget.current.lerp(
      desiredLookTarget,
      1 - Math.exp(-delta * 10),
    )
    camera.lookAt(smoothedLookTarget.current)
    runtime.cameraTrauma = Math.max(0, runtime.cameraTrauma - delta * 2.8)
    runtime.cameraKick = Math.max(0, runtime.cameraKick - delta * 7.5)

    const reactionRemaining = hitReactionRemaining.current
    if (hitReactionRef.current) {
      if (reactionRemaining > 0 && !state.settings.reducedMotion) {
        const progress = 1 - reactionRemaining / PLAYER_HIT_REACTION_SECONDS
        const impulse = Math.sin(Math.min(1, progress) * Math.PI)
        hitReactionRef.current.position.set(
          -runtime.playerHitDirection.x * impulse * 0.2,
          impulse * 0.065,
          -runtime.playerHitDirection.z * impulse * 0.2,
        )
        hitReactionRef.current.scale.set(
          1 + impulse * 0.08,
          1 - impulse * 0.12,
          1 + impulse * 0.08,
        )
        hitReactionRef.current.rotation.z =
          runtime.playerHitDirection.x * impulse * 0.1
      } else {
        hitReactionRef.current.position.set(0, 0, 0)
        hitReactionRef.current.scale.set(1, 1, 1)
        hitReactionRef.current.rotation.z = 0
      }
    }
    hitReactionRemaining.current = Math.max(0, reactionRemaining - delta)

    if (touchMode) {
      const keyMoveX =
        (runtime.pressedKeys.has('KeyD') ? 1 : 0) -
        (runtime.pressedKeys.has('KeyA') ? 1 : 0)
      const keyMoveZ =
        (runtime.pressedKeys.has('KeyS') ? 1 : 0) -
        (runtime.pressedKeys.has('KeyW') ? 1 : 0)
      const touchFacing = resolveTouchFacing(
        runtime.aimInput.x,
        runtime.aimInput.y,
        runtime.moveInput.x + keyMoveX,
        runtime.moveInput.y + keyMoveZ,
      )
      if (touchFacing) runtime.playerFacing.set(touchFacing.x, 0, touchFacing.z)
    } else {
      updateAimFromPointer()
    }
    quaternionFromNegativeZForward(runtime.playerFacing, targetRotation)
    visualRef.current?.quaternion.slerp(
      targetRotation,
      1 - Math.exp(-delta * 24),
    )

    if (swordRef.current) {
      const remaining = Math.max(
        0,
        attackAnimationEndsAt.current - runtime.elapsed,
      )
      const progress =
        1 - Math.min(1, remaining / PLAYER_ATTACK_ANIMATION_SECONDS)
      swordRef.current.rotation.y =
        remaining > 0 ? -0.95 + Math.sin(progress * Math.PI) * 1.9 : 0
    }

    if (dodgeCooldownRingRef.current) {
      const cooldownSeconds = Math.max(
        0.001,
        state.stats.dodgeCooldownMs / 1_000,
      )
      const remaining = Math.max(0, dodgeReadyAt.current - runtime.elapsed)
      const progress = 1 - Math.min(1, remaining / cooldownSeconds)
      dodgeCooldownRingRef.current.visible = remaining > 0
      dodgeCooldownRingRef.current.scale.setScalar(0.72 + progress * 0.28)
    }

    if (!isActiveGameplayPhase(state.phase)) {
      runtime.pressedKeys.clear()
      runtime.moveInput.set(0, 0)
      runtime.aimInput.set(0, 0)
      runtime.attackHeld = false
      runtime.dodgeRequestedAt = Number.NEGATIVE_INFINITY
      runtime.attackRequestedAt = Number.NEGATIVE_INFINITY
      bodyRef.current?.setLinvel({ x: 0, y: 0, z: 0 }, true)
      return
    }
    runtime.elapsed = advanceGameplayElapsed(
      state.phase,
      runtime.elapsed,
      delta,
    )
  })

  return (
    <RigidBody
      ref={bodyRef}
      type="dynamic"
      colliders={false}
      position={[spawn.x, 0.8, spawn.z]}
      enabledRotations={[false, false, false]}
      enabledTranslations={[true, false, true]}
      gravityScale={0}
      linearDamping={8}
      dominanceGroup={10}
      name="player"
    >
      <CapsuleCollider
        args={[0.42, 0.34]}
        collisionGroups={interactionGroups(1, [0, 2, 3])}
      />
      <mesh
        ref={dodgeCooldownRingRef}
        position={[0, -0.77, 0]}
        rotation={[-Math.PI / 2, 0, 0]}
        visible={false}
        name="dodge-cooldown-ring"
      >
        <torusGeometry args={[0.48, 0.025, 6, 32]} />
        <meshBasicMaterial
          color={TOON_PALETTE.white}
          transparent
          opacity={0.72}
        />
      </mesh>
      <group ref={hitReactionRef} name="player-hit-reaction">
        <group ref={visualRef} name="player-visual">
          <AssetBoundary
            fallback={<ProceduralPlayerVisual swordRef={swordRef} />}
            resetKey="hero"
          >
            <AnimatedCharacterModel
              name="player-gltf"
              url={assetUrl('models/hero.glb')}
              motionRef={motionRef}
              paused={!isActiveGameplayPhase(phase) && phase !== 'defeat'}
              position={[0, -0.78, 0]}
              rotation={[0, Math.PI, 0]}
              scale={0.52}
              tint={TOON_PALETTE.indigoLight}
              tintStrength={0.3}
              attachments={PLAYER_ATTACHMENTS}
              attackPlaybackRate={5}
              hitFlashRevision={lastPlayerHit?.id}
            />
          </AssetBoundary>
        </group>
      </group>
    </RigidBody>
  )
}
