const AIM_ACTIVE_THRESHOLD_SQ = 1e-6
const MOVE_ACTIVE_THRESHOLD_SQ = 0.0025

/**
 * Facing priority for touch play: the aim stick wins, otherwise the
 * character looks where it walks, otherwise `null` keeps the last facing —
 * releasing both sticks must not drop an ongoing stare (backing away while
 * freezing an enemy is the core tactic).
 */
export function resolveTouchFacing(
  aimX: number,
  aimY: number,
  moveX: number,
  moveY: number,
): { x: number; z: number } | null {
  const aimLengthSq = aimX * aimX + aimY * aimY
  if (aimLengthSq > AIM_ACTIVE_THRESHOLD_SQ) {
    const length = Math.sqrt(aimLengthSq)
    return { x: aimX / length, z: aimY / length }
  }
  const moveLengthSq = moveX * moveX + moveY * moveY
  if (moveLengthSq > MOVE_ACTIVE_THRESHOLD_SQ) {
    const length = Math.sqrt(moveLengthSq)
    return { x: moveX / length, z: moveY / length }
  }
  return null
}
