// Fallback only; rooms pass floorColors from sceneMetadata. Kept in sync with
// the crypt palette so a room without presentation data does not go warm.
const FLOOR_TILE_COLORS = [
  '#55555e',
  '#4e4e57',
  '#5d5d66',
  '#48484f',
  '#63636c',
] as const

const modelCache = new Map<string, Promise<Group | null>>()
const interactiveOutlineMaterial = createOutlineMaterial(
  TOON_OUTLINE_COLOR,
  0.022,
)

/**
 * Architecture is tinted toward the UI's indigo rather than the old olive, and
 * lifted rather than darkened. Walls facing away from the key light used to
 * collapse to near-black, which cost the room its silhouette and left a dead
 * quarter of the frame; keeping a floor under their value preserves the read.
 */
function createEnvironmentToonMaterial(url: string, source: Material) {
  const isWall = url === MODEL.wall
  const isColumn = url === MODEL.column
  const material = createToonMaterial(
    source,
    isWall ? 1.02 : isColumn ? 1.04 : 1.08,
    environmentGradientMap,
  )
  if (isWall) material.color.lerp(new Color('#3f3f47'), 0.46)
  if (isColumn) material.color.lerp(new Color('#46464e'), 0.4)
  return material
}

function BeveledTileFloor({
  width,
  depth,
  colors = FLOOR_TILE_COLORS,
  baseColor = '#2c2c33',
}: {
  width: number
  depth: number
  colors?: readonly string[]
  baseColor?: string
}) {
  const meshRef = useRef<InstancedMesh>(null)
  const tileColumns = Math.ceil(width / 2)
  const tileRows = Math.ceil(depth / 2)
  const tileCount = tileColumns * tileRows
  const transform = useMemo(() => new Object3D(), [])
  const tileColor = useMemo(() => new Color(), [])
  const geometry = useMemo(
    () => new RoundedBoxGeometry(1.94, 0.14, 1.94, 1, 0.045),
    [],
  )

  useEffect(() => () => geometry.dispose(), [geometry])
  useLayoutEffect(() => {
    const mesh = meshRef.current
    if (!mesh) return
    let index = 0
    for (let row = 0; row < tileRows; row += 1) {
      for (let column = 0; column < tileColumns; column += 1) {
        transform.position.set(
          -width / 2 + 1 + column * 2,
          -0.08,
          -depth / 2 + 1 + row * 2,
        )
        transform.rotation.set(0, 0, 0)
        transform.scale.set(1, 1, 1)
        transform.updateMatrix()
        mesh.setMatrixAt(index, transform.matrix)
        const paletteIndex =
          (row * 7 + column * 11 + Math.floor((row + column) / 3)) %
          colors.length
        tileColor.set(colors[paletteIndex] ?? '#55555e')
        mesh.setColorAt(index, tileColor)
        index += 1
      }
    }
    mesh.instanceMatrix.needsUpdate = true
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
    mesh.computeBoundingSphere()
  }, [colors, depth, tileColor, tileColumns, tileRows, transform, width])

  return (
    <group name="beveled-floor-tiles-2x2">
      <mesh receiveShadow position={[0, -0.13, 0]}>
        <boxGeometry args={[width, 0.12, depth]} />
        <meshToonMaterial
          color={baseColor}
          gradientMap={environmentGradientMap}
        />
      </mesh>
      <instancedMesh
        ref={meshRef}
        args={[geometry, undefined, tileCount]}
        receiveShadow
      >
        <meshToonMaterial
          color="#ffffff"
          gradientMap={environmentGradientMap}
        />
      </instancedMesh>
    </group>
  )
}

type GroundShadowDescriptor = readonly [
  x: number,
  z: number,
  width: number,
  depth: number,
  rotation?: number,
]

function StaticGroundShadows({
  shadows,
  fadeOpacityRef,
}: {
  shadows: readonly GroundShadowDescriptor[]
  fadeOpacityRef?: RefObject<number>
}) {
  const meshRef = useRef<InstancedMesh>(null)
  const materialRef = useRef<MeshBasicMaterial>(null)
  const transform = useMemo(() => new Object3D(), [])

  useLayoutEffect(() => {
    const mesh = meshRef.current
    if (!mesh) return
    shadows.forEach(([x, z, width, depth, rotation = 0], index) => {
      transform.position.set(x, 0.034, z)
      transform.rotation.set(-Math.PI / 2, 0, rotation)
      transform.scale.set(width, depth, 1)
      transform.updateMatrix()
      mesh.setMatrixAt(index, transform.matrix)
    })
    mesh.instanceMatrix.needsUpdate = true
    mesh.computeBoundingSphere()
  }, [shadows, transform])

  useFrame(() => {
    if (!fadeOpacityRef || !materialRef.current) return
    materialRef.current.opacity = 0.4 * (fadeOpacityRef.current ?? 1)
  })

  return (
    <instancedMesh
      ref={meshRef}
      args={[undefined, undefined, shadows.length]}
      renderOrder={1}
    >
      <planeGeometry args={[1, 1]} />
      <meshBasicMaterial
        ref={materialRef}
        alphaMap={softShadowTexture}
        color="#0c1429"
        depthWrite={false}
        opacity={0.4}
        polygonOffset
        polygonOffsetFactor={-2}
        toneMapped={false}
        transparent
      />
    </instancedMesh>
  )
}

function loadToonModel(url: string): Promise<Group | null> {
  const cached = modelCache.get(url)
  if (cached) return cached

  const promise = new GLTFLoader()
    .loadAsync(url)
    .then(({ scene }) => {
      const materials = new Map<Material, Material>()
      scene.traverse((object) => {
        if (!(object instanceof Mesh)) return
        object.castShadow = true
        object.receiveShadow = true
        const convert = (material: Material) => {
          const converted =
            materials.get(material) ??
            createEnvironmentToonMaterial(url, material)
          materials.set(material, converted)
          return converted
        }
        object.material = Array.isArray(object.material)
          ? object.material.map(convert)
          : convert(object.material)
      })
      return scene
    })
    .catch(() => null)
  modelCache.set(url, promise)
  return promise
}

function useOptionalModel(url: string): Group | null | undefined {
  const [scene, setScene] = useState<Group | null>()
  useEffect(() => {
    let active = true
    void loadToonModel(url).then((loaded) => {
      if (active) setScene(loaded)
    })
    return () => {
      active = false
    }
  }, [url])
  return scene
}

interface AssetPropProps {
  url: string
  position?: [number, number, number]
  rotation?: [number, number, number]
  scale?: number | [number, number, number]
  castShadow?: boolean
  receiveShadow?: boolean
  outline?: boolean
  outlineDistance?: number
  fadeOpacityRef?: RefObject<number>
  fallback?: ReactNode
  name?: string
}

function AssetProp({
  url,
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  scale = 1,
  castShadow = false,
  receiveShadow = true,
  outline = false,
  outlineDistance = 18,
  fadeOpacityRef,
  fallback = null,
  name,
}: AssetPropProps) {
  const source = useOptionalModel(url)
  const outlineWorldPosition = useMemo(() => new Vector3(), [])
  const outlineRefresh = useRef(0.2)
  const instance = useMemo(() => {
    const clone = source?.clone(true)
    const meshes: Mesh[] = []
    clone?.traverse((object) => {
      if (!(object instanceof Mesh)) return
      object.castShadow = castShadow
      object.receiveShadow = receiveShadow
      meshes.push(object)
    })
    const fadeController =
      clone && fadeOpacityRef ? isolateForegroundMaterials(clone) : null
    const outlines: Mesh[] = []
    if (outline && clone) {
      for (const mesh of meshes) {
        if (!mesh.parent) continue
        const shell = new Mesh(mesh.geometry, interactiveOutlineMaterial)
        shell.position.copy(mesh.position)
        shell.quaternion.copy(mesh.quaternion)
        shell.scale.copy(mesh.scale)
        shell.name = `${mesh.name || 'prop'}-outline`
        shell.castShadow = false
        shell.receiveShadow = false
        shell.renderOrder = -2
        mesh.parent.add(shell)
        outlines.push(shell)
      }
    }
    return clone ? { root: clone, outlines, fadeController } : null
  }, [castShadow, fadeOpacityRef, outline, receiveShadow, source])
  const instanceRef = useRef(instance)

  useEffect(() => {
    instanceRef.current = instance
    return () => {
      instance?.fadeController?.dispose()
      if (instanceRef.current === instance) instanceRef.current = null
    }
  }, [instance])

  useFrame(({ camera }, delta) => {
    const outlinedInstance = instanceRef.current
    outlinedInstance?.fadeController?.setOpacity(fadeOpacityRef?.current ?? 1)
    if (!outlinedInstance || outlinedInstance.outlines.length === 0) return
    outlineRefresh.current += delta
    if (outlineRefresh.current < 0.2) return
    outlineRefresh.current = 0
    outlinedInstance.root.getWorldPosition(outlineWorldPosition)
    const visible =
      !Number.isFinite(outlineDistance) ||
      camera.position.distanceToSquared(outlineWorldPosition) <=
        outlineDistance * outlineDistance
    for (const shell of outlinedInstance.outlines) {
      // R3F scene objects are intentionally updated through stable model refs.
      // eslint-disable-next-line react-hooks/immutability
      shell.visible = visible
    }
  })

  if (!instance) return fallback
  return (
    <primitive
      object={instance.root}
      position={position}
      rotation={rotation}
      scale={scale}
      name={name}
    />
  )
}

interface WallProps {
  center: [number, number, number]
  halfExtents: [number, number, number]
  assetScale: [number, number, number]
  assetRotation?: [number, number, number]
  color?: string
  fadeOpacityRef?: RefObject<number>
}

function ProceduralWall({
  halfExtents,
  color,
  fadeOpacityRef,
}: Pick<WallProps, 'halfExtents' | 'color' | 'fadeOpacityRef'>) {
  const visualRef = useRef<Group>(null)
  const fadeControllerRef = useRef<ForegroundMaterialController | null>(null)

  useLayoutEffect(() => {
    if (!fadeOpacityRef || !visualRef.current) return
    const controller = isolateForegroundMaterials(visualRef.current)
    controller.setOpacity(fadeOpacityRef.current ?? 1)
    fadeControllerRef.current = controller
    return () => {
      controller.dispose()
      if (fadeControllerRef.current === controller) {
        fadeControllerRef.current = null
      }
    }
  }, [fadeOpacityRef])

  useFrame(() => {
    fadeControllerRef.current?.setOpacity(fadeOpacityRef?.current ?? 1)
  })

  return (
    <group ref={visualRef}>
      <mesh castShadow receiveShadow>
        <boxGeometry
          args={
            halfExtents.map((value) => value * 2) as [number, number, number]
          }
        />
        <meshToonMaterial color={color} gradientMap={environmentGradientMap} />
      </mesh>
      <mesh position={[0, halfExtents[1] + 0.08, 0]}>
        <boxGeometry
          args={[halfExtents[0] * 1.8, 0.08, halfExtents[2] * 1.8]}
        />
        <meshToonMaterial
          color="#a28d5f"
          emissive="#30251b"
          gradientMap={environmentGradientMap}
        />
      </mesh>
    </group>
  )
}

function Wall({
  center,
  halfExtents,
  assetScale,
  assetRotation = [0, 0, 0],
  color = '#3f3f47',
  fadeOpacityRef,
}: WallProps) {
  return (
    <RigidBody type="fixed" colliders={false} position={center}>
      <CuboidCollider
        args={halfExtents}
        collisionGroups={interactionGroups(0, [1, 2, 3])}
      />
      <AssetProp
        url={MODEL.wall}
        position={[0, -halfExtents[1], 0]}
        rotation={assetRotation}
        scale={assetScale}
        castShadow
        fadeOpacityRef={fadeOpacityRef}
        fallback={
          <ProceduralWall
            halfExtents={halfExtents}
            color={color}
            fadeOpacityRef={fadeOpacityRef}
          />
        }
        name="dungeon-wall"
      />
    </RigidBody>
  )
}

