function MoonGardenSigil() {
  const sourceTexture = useLoader(TextureLoader, MOON_GARDEN_SIGIL)
  const texture = useMemo(() => {
    const textureClone = sourceTexture.clone()
    textureClone.colorSpace = SRGBColorSpace
    textureClone.needsUpdate = true
    return textureClone
  }, [sourceTexture])
  useEffect(() => () => texture.dispose(), [texture])

  return (
    <mesh
      position={[0, 0.026, 0]}
      rotation={[-Math.PI / 2, 0, 0]}
      renderOrder={1}
      name="moon-garden-sigil"
    >
      <planeGeometry args={[5.2, 5.2]} />
      <meshBasicMaterial
        map={texture}
        transparent
        opacity={0.7}
        depthWrite={false}
        toneMapped={false}
      />
    </mesh>
  )
}

function MoonGardenDressing({
  halfX,
  halfZ,
  volatile,
}: {
  halfX: number
  halfZ: number
  volatile: boolean
}) {
  const petals = useMemo(
    () =>
      [
        [-halfX + 2.1, -halfZ + 2.4, 0.2],
        [halfX - 2.2, -halfZ + 3.1, -0.5],
        [-halfX + 1.8, halfZ - 3.2, 0.8],
        [halfX - 2.4, halfZ - 2.1, -0.15],
        [-halfX * 0.45, halfZ * 0.62, 0.55],
        [halfX * 0.48, -halfZ * 0.55, -0.8],
      ] as const,
    [halfX, halfZ],
  )
  const accent = volatile ? TOON_PALETTE.coral : TOON_PALETTE.cyanLight

  return (
    <group name={volatile ? 'moon-garden-volatile' : 'moon-garden-stable'}>
      <MoonGardenSigil />
      {petals.map(([x, z, rotation], clusterIndex) => (
        <group
          key={`${x}:${z}`}
          position={[x, 0.07, z]}
          rotation={[0, rotation, 0]}
          name="moon-petal-cluster"
        >
          {[-1, 0, 1].map((offset) => (
            <mesh
              key={offset}
              position={[
                offset * 0.22,
                Math.abs(offset) * 0.035,
                offset * 0.09,
              ]}
              rotation={[0, offset * 0.45, -0.4 + offset * 0.18]}
              castShadow
            >
              <sphereGeometry
                args={[0.17 + (clusterIndex % 2) * 0.025, 7, 4]}
              />
              <meshToonMaterial
                color={accent}
                gradientMap={environmentGradientMap}
              />
            </mesh>
          ))}
          <mesh position={[0, 0.22, 0]} castShadow>
            <coneGeometry args={[0.11, 0.48, 5]} />
            <meshToonMaterial
              color="#355d58"
              gradientMap={environmentGradientMap}
            />
          </mesh>
        </group>
      ))}
      <AssetProp
        url={MODEL.altar}
        position={[halfX - 2.4, 0.02, halfZ - 2.6]}
        rotation={[0, -0.6, 0]}
        scale={1.75}
        name="moon-garden-shrine"
      />
      <AssetProp
        url={MODEL.rocks}
        position={[-halfX + 2.25, 0, -halfZ + 2.3]}
        rotation={[0, 1.1, 0]}
        scale={1.35}
        name="moon-garden-rocks"
      />
      {volatile ? (
        <group name="volatile-brambles">
          {[-1, 1].map((side) => (
            <group
              key={side}
              position={[side * (halfX - 1.55), 0.35, 0]}
              rotation={[0, 0, side * 0.25]}
            >
              {[0, 1, 2].map((index) => (
                <mesh
                  key={index}
                  position={[0, index * 0.34, (index - 1) * 0.24]}
                  rotation={[Math.PI / 2, index * 0.6, 0]}
                  castShadow
                >
                  <coneGeometry args={[0.12, 0.7, 4]} />
                  <meshToonMaterial
                    color={TOON_PALETTE.coral}
                    gradientMap={environmentGradientMap}
                  />
                </mesh>
              ))}
            </group>
          ))}
        </group>
      ) : null}
    </group>
  )
}

function RouteRiskCue({ risk }: { risk: SceneNodeRisk }) {
  const volatile = risk === 'volatile'
  const accent = volatile ? TOON_PALETTE.coral : TOON_PALETTE.cyanLight
  return (
    <group
      position={[0, 0.04, 6.3]}
      rotation={[-Math.PI / 2, 0, 0]}
      name={`route-risk-${risk}`}
    >
      {volatile ? (
        <group name="route-risk-shape-three-spikes">
          {[0, 1, 2].map((index) => (
            <mesh
              key={index}
              position={[
                Math.cos((index / 3) * Math.PI * 2) * 0.47,
                Math.sin((index / 3) * Math.PI * 2) * 0.47,
                0,
              ]}
              rotation={[0, 0, (index / 3) * Math.PI * 2]}
            >
              <circleGeometry args={[0.3, 3]} />
              <meshBasicMaterial color={accent} transparent opacity={0.7} />
            </mesh>
          ))}
        </group>
      ) : (
        <group name="route-risk-shape-double-diamond">
          {[0.4, 0.67].map((radius) => (
            <mesh key={radius} rotation={[0, 0, Math.PI / 4]}>
              <ringGeometry args={[radius - 0.035, radius, 4]} />
              <meshBasicMaterial color={accent} transparent opacity={0.7} />
            </mesh>
          ))}
        </group>
      )}
    </group>
  )
}

function MutationCue({ mutationId }: { mutationId: SceneMutationId | null }) {
  if (!mutationId) return null
  if (mutationId === 'double-omen') {
    return (
      <group name="mutation-cue-double-omen">
        <MutationCue mutationId="restless-swarm" />
        <MutationCue mutationId="elite-oath" />
      </group>
    )
  }
  if (mutationId === 'open-ground') {
    return (
      <group position={[0, 0.045, 0]} name="mutation-cue-open-ground">
        {[-4.2, 4.2].map((x) => (
          <mesh key={x} position={[x, 0, 0]} rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry args={[2.4, 2.47, 40, 1, -0.72, 1.44]} />
            <meshBasicMaterial
              color={TOON_PALETTE.cyanLight}
              transparent
              opacity={0.35}
              depthWrite={false}
            />
          </mesh>
        ))}
      </group>
    )
  }
  if (mutationId === 'restless-swarm') {
    return (
      <group position={[0, 0.05, 0]} name="mutation-cue-restless-swarm">
        {Array.from({ length: 8 }, (_, index) => {
          const angle = (index / 8) * Math.PI * 2
          return (
            <mesh
              key={index}
              position={[Math.cos(angle) * 4.8, 0, Math.sin(angle) * 4.8]}
              rotation={[-Math.PI / 2, 0, angle]}
            >
              <circleGeometry args={[0.26, 3]} />
              <meshBasicMaterial
                color={TOON_PALETTE.coralLight}
                transparent
                opacity={0.48}
                depthWrite={false}
              />
            </mesh>
          )
        })}
      </group>
    )
  }
  return (
    <group position={[0, 0.05, 0]} name="mutation-cue-elite-oath">
      {[2.25, 2.68].map((radius) => (
        <mesh key={radius} rotation={[-Math.PI / 2, 0, Math.PI / 4]}>
          <ringGeometry args={[radius - 0.065, radius, 4]} />
          <meshBasicMaterial
            color={TOON_PALETTE.goldLight}
            transparent
            opacity={0.5}
            depthWrite={false}
          />
        </mesh>
      ))}
    </group>
  )
}

export interface RoomEnvironmentProps {
  room: RoomTemplate
  biomeId?: unknown
  risk?: unknown
  mutationId?: unknown
}

export function RoomEnvironment({
  room,
  biomeId,
  risk,
  mutationId,
}: RoomEnvironmentProps) {
  const reducedMotion = useGameStore((state) => state.settings.reducedMotion)
  const presentation = useMemo(
    () =>
      getSceneRoomPresentation({
        id: room.id,
        biomeId: biomeId ?? room.biomeId,
        risk,
        mutationId,
      }),
    [biomeId, mutationId, risk, room.biomeId, room.id],
  )
  const halfX = room.size.x / 2
  const halfZ = room.size.z / 2
  const foregroundOpacityRef = useRef(1)

  useFrame((_, delta) => {
    const targetOpacity = getForegroundFadeOpacity(
      halfZ - runtime.playerPosition.z,
    )
    foregroundOpacityRef.current = dampForegroundFadeOpacity(
      foregroundOpacityRef.current,
      targetOpacity,
      delta,
      reducedMotion,
    )
  })
  const activeOccluders = useMemo(
    () => getEncounterOccluders(room.occluders, presentation.mutationId),
    [presentation.mutationId, room.occluders],
  )
  const torches = useMemo<[number, number, number][]>(
    () => [
      [-halfX + 1.3, 1.1, -halfZ + 1.3],
      [halfX - 1.3, 1.1, -halfZ + 1.3],
      [-halfX + 1.3, 1.1, halfZ - 1.3],
      [halfX - 1.3, 1.1, halfZ - 1.3],
    ],
    [halfX, halfZ],
  )
  const columns = useMemo<[number, number, number][]>(
    () => [
      [-halfX + 0.75, 0, -halfZ + 0.75],
      [halfX - 0.75, 0, -halfZ + 0.75],
      [-halfX + 0.75, 0, halfZ - 0.75],
      [halfX - 0.75, 0, halfZ - 0.75],
    ],
    [halfX, halfZ],
  )
  const foregroundContactShadows = useMemo<GroundShadowDescriptor[]>(
    () => [
      [0, halfZ - 0.16, room.size.x - 0.4, 1.2],
      ...columns
        .filter(([, , z]) => z > 0)
        .map(([x, , z]) => [x, z, 1.35, 1.35] as GroundShadowDescriptor),
    ],
    [columns, halfZ, room.size.x],
  )
  const contactShadows = useMemo<GroundShadowDescriptor[]>(() => {
    const shadows: GroundShadowDescriptor[] = [
      [0, -halfZ + 0.16, room.size.x - 0.4, 1.2],
      [-halfX + 0.16, 0, 1.2, room.size.z - 0.4],
      [halfX - 0.16, 0, 1.2, room.size.z - 0.4],
      [halfX - 2.1, -halfZ + 2.2, 1.15, 0.92, 0.35],
      [-halfX + 2.2, halfZ - 2.1, 1.08, 0.88, -0.55],
    ]

    for (const occluder of activeOccluders) {
      shadows.push([
        occluder.center.x,
        occluder.center.z,
        occluder.halfExtents.x * 2 + 0.85,
        occluder.halfExtents.z * 2 + 0.85,
      ])
    }
    for (const [x, , z] of columns) {
      if (z <= 0) shadows.push([x, z, 1.35, 1.35])
    }

    shadows.push(
      [-halfX + 1.15, -halfZ + 3, 0.92, 0.68, 0.15],
      [halfX - 1.2, halfZ - 3.2, 0.92, 0.68, -0.22],
      [halfX - 1.1, -halfZ + 4.5, 0.92, 0.68, 0.18],
      [-halfX + 2.2, -halfZ + 1.1, 1.45, 1.05],
      [halfX - 2.5, halfZ - 1.15, 1.45, 1.05, 1.7],
    )

    if (room.kind === 'combat') {
      shadows.push(
        [-halfX + 2.2, -halfZ + 3.8, 2.35, 1.2, 0.22],
        [halfX - 2.1, halfZ - 3.5, 1.35, 1.35],
      )
    } else if (room.kind === 'reward') {
      shadows.push([1, 0, 3, 2.1], [-3.1, -2.7, 1.35, 1.35])
    } else if (room.kind === 'boss') {
      shadows.push(
        [0, -8, 5.8, 3.5],
        [-3.2, -8.2, 2.7, 1.4, -0.3],
        [3.2, -8.2, 2.7, 1.4, 0.3],
        [-4.4, -7.1, 1.35, 1.35],
        [4.4, -7.1, 1.35, 1.35],
      )
    }

    return shadows
  }, [
    columns,
    halfX,
    halfZ,
    room.kind,
    activeOccluders,
    room.size.x,
    room.size.z,
  ])

  return (
    <group>
      <RigidBody type="fixed" colliders={false}>
        <CuboidCollider
          args={[halfX, 0.1, halfZ]}
          position={[0, -0.1, 0]}
          collisionGroups={interactionGroups(0, [1, 2, 3])}
        />
        <BeveledTileFloor
          width={room.size.x}
          depth={room.size.z}
          colors={presentation.floorColors}
          baseColor={presentation.floorBase}
        />
      </RigidBody>

      <StaticGroundShadows shadows={contactShadows} />
      <StaticGroundShadows
        shadows={foregroundContactShadows}
        fadeOpacityRef={foregroundOpacityRef}
      />
      <RouteRiskCue risk={presentation.risk} />
      <MutationCue mutationId={presentation.mutationId} />

      <Wall
        center={[0, 1.35, -halfZ]}
        halfExtents={[halfX, 1.35, 0.25]}
        assetScale={[halfX / 2, 0.675, 0.5]}
        color={presentation.wallColor}
      />
      <Wall
        center={[0, 1.35, halfZ]}
        halfExtents={[halfX, 1.35, 0.25]}
        assetScale={[halfX / 2, 0.675, 0.5]}
        color={presentation.wallColor}
        fadeOpacityRef={foregroundOpacityRef}
      />
      <Wall
        center={[-halfX, 1.35, 0]}
        halfExtents={[0.25, 1.35, halfZ]}
        assetScale={[halfZ / 2, 0.675, 0.5]}
        assetRotation={[0, Math.PI / 2, 0]}
        color={presentation.wallColor}
      />
      <Wall
        center={[halfX, 1.35, 0]}
        halfExtents={[0.25, 1.35, halfZ]}
        assetScale={[halfZ / 2, 0.675, 0.5]}
        assetRotation={[0, Math.PI / 2, 0]}
        color={presentation.wallColor}
      />

      {activeOccluders.map((occluder) => {
        const rotate = occluder.halfExtents.z > occluder.halfExtents.x
        return (
          <Wall
            key={occluder.id}
            center={[occluder.center.x, occluder.height / 2, occluder.center.z]}
            halfExtents={[
              occluder.halfExtents.x,
              occluder.height / 2,
              occluder.halfExtents.z,
            ]}
            assetScale={
              rotate
                ? [
                    occluder.halfExtents.z / 2,
                    occluder.height / 4,
                    occluder.halfExtents.x * 2,
                  ]
                : [
                    occluder.halfExtents.x / 2,
                    occluder.height / 4,
                    occluder.halfExtents.z * 2,
                  ]
            }
            assetRotation={rotate ? [0, Math.PI / 2, 0] : undefined}
            color={presentation.wallColor}
          />
        )
      })}

      {columns.map((position) => (
        <AssetProp
          key={`column-${position.join(':')}`}
          url={MODEL.column}
          position={position}
          scale={[1.35, 1.9, 1.35]}
          castShadow
          fadeOpacityRef={position[2] > 0 ? foregroundOpacityRef : undefined}
          name="dungeon-column"
        />
      ))}

      {torches.map((position, index) =>
        presentation.biomeId === 'moon-garden' ? (
          <MoonLantern key={position.join(':')} position={position} />
        ) : (
          <Torch
            key={position.join(':')}
            position={position}
            lit={index === 0 || index === 3}
          />
        ),
      )}

      {presentation.biomeId === 'moon-garden' ? (
        <MoonGardenDressing
          halfX={halfX}
          halfZ={halfZ}
          volatile={presentation.risk === 'volatile'}
        />
      ) : null}

      {presentation.biomeId === 'crypt' ? (
        <>
          <AssetProp
            url={MODEL.barrel}
            position={[halfX - 2.1, 0, -halfZ + 2.2]}
            rotation={[0, 0.35, 0]}
            scale={0.5}
            name="dungeon-barrel"
          />
          <AssetProp
            url={MODEL.barrel}
            position={[-halfX + 2.2, 0, halfZ - 2.1]}
            rotation={[0, -0.55, 0]}
            scale={0.46}
            name="dungeon-barrel"
          />
          {[
            [-halfX + 1.15, 0, -halfZ + 3, 0.15],
            [halfX - 1.2, 0, halfZ - 3.2, -0.22],
            [halfX - 1.1, 0, -halfZ + 4.5, 0.18],
          ].map(([x, y, z, rotation], index) => (
            <AssetProp
              key={`gravestone-${index}`}
              url={MODEL.gravestone}
              position={[x, y, z]}
              rotation={[0, rotation, 0]}
              scale={1.28}
              name="gravestone"
            />
          ))}
        </>
      ) : null}

      {[
        [-halfX + 2.2, 0, -halfZ + 1.1],
        [halfX - 2.5, 0, halfZ - 1.15],
      ].map(([x, y, z], index) => (
        <AssetProp
          key={`rocks-${index}`}
          url={MODEL.rocks}
          position={[x, y, z]}
          rotation={[0, index * 1.7, 0]}
          scale={1.22}
          name="graveyard-rocks"
        />
      ))}

      {[
        [-halfX * 0.42, 0, -halfZ * 0.12, 0.48, 0.4],
        [halfX * 0.34, 0, halfZ * 0.2, 0.42, 2.1],
        [-halfX * 0.16, 0, halfZ * 0.52, 0.36, 1.2],
        [halfX * 0.55, 0, -halfZ * 0.38, 0.32, 2.8],
      ].map(([x, y, z, scale, rotation], index) => (
        <AssetProp
          key={`floor-rubble-${index}`}
          url={MODEL.rocks}
          position={[x, y, z]}
          rotation={[0, rotation, 0]}
          scale={scale}
          receiveShadow
          name="floor-rubble"
        />
      ))}

      {room.kind === 'combat' && presentation.biomeId === 'crypt' && (
        <>
          <AssetProp
            url={MODEL.coffin}
            position={[-halfX + 2.2, 0, -halfZ + 3.8]}
            rotation={[0, 0.22, 0]}
            scale={1.85}
            name="coffin"
          />
          <FireBasket position={[halfX - 2.1, 0, halfZ - 3.5]} />
        </>
      )}

      {room.kind === 'reward' && (
        <group>
          <AssetProp
            url={MODEL.altar}
            position={[1, 0.03, 0]}
            scale={2.4}
            outline
            outlineDistance={18}
            name="reward-altar"
          />
          <FireBasket position={[-3.1, 0, -2.7]} />
          <group position={[1, 1.35, 0]}>
            <mesh>
              <dodecahedronGeometry args={[0.42, 0]} />
              <meshToonMaterial
                color={TOON_PALETTE.cyanLight}
                emissive={TOON_PALETTE.cyan}
                emissiveIntensity={1.8}
                gradientMap={environmentGradientMap}
              />
            </mesh>
            <pointLight
              color={TOON_PALETTE.cyan}
              intensity={2.2}
              distance={5}
            />
          </group>
        </group>
      )}

      {room.kind === 'boss' && presentation.biomeId === 'crypt' && (
        <group>
          <AssetProp
            url={MODEL.altar}
            position={[0, 0.02, -8]}
            scale={[4.6, 3.2, 4.2]}
            name="boss-altar"
          />
          <AssetProp
            url={MODEL.coffin}
            position={[-3.2, 0, -8.2]}
            rotation={[0, -0.3, 0]}
            scale={2.25}
            name="boss-coffin"
          />
          <AssetProp
            url={MODEL.coffin}
            position={[3.2, 0, -8.2]}
            rotation={[0, 0.3, 0]}
            scale={2.25}
            name="boss-coffin"
          />
          <FireBasket position={[-4.4, 0, -7.1]} />
          <FireBasket position={[4.4, 0, -7.1]} />
        </group>
      )}
      {room.kind === 'boss' && presentation.biomeId === 'moon-garden' && (
        <group name="briar-sanctum-dressing">
          <AssetProp
            url={MODEL.altar}
            position={[0, 0.02, -8]}
            scale={[4.2, 3, 3.8]}
            name="moonbriar-altar"
          />
          {[-1, 1].map((side) => (
            <group
              key={side}
              position={[side * 4.2, 0.45, -7.1]}
              rotation={[0, 0, side * 0.16]}
              name="moonbriar-thorn-pillar"
            >
              {[0, 1, 2, 3].map((index) => (
                <mesh
                  key={index}
                  position={[0, index * 0.4, (index % 2) * 0.18]}
                  rotation={[0, index * 0.75, 0.12]}
                  castShadow
                >
                  <coneGeometry args={[0.16, 0.85, 5]} />
                  <meshToonMaterial
                    color={
                      presentation.risk === 'volatile'
                        ? TOON_PALETTE.coral
                        : TOON_PALETTE.cyan
                    }
                    gradientMap={environmentGradientMap}
                  />
                </mesh>
              ))}
            </group>
          ))}
          <MoonLantern position={[-5.8, 0, -8.7]} />
          <MoonLantern position={[5.8, 0, -8.7]} />
          <group position={[0, 1.72, -8]}>
            <mesh>
              <icosahedronGeometry args={[0.44, 1]} />
              <meshToonMaterial
                color={TOON_PALETTE.cyanLight}
                emissive={TOON_PALETTE.cyan}
                emissiveIntensity={1.7}
                gradientMap={environmentGradientMap}
              />
            </mesh>
            <pointLight
              color={TOON_PALETTE.cyanLight}
              intensity={2}
              distance={6}
            />
          </group>
        </group>
      )}
    </group>
  )
}
