import type { RoomWaypoint, Vec2 } from './types'

export type SegmentBlocked = (from: Vec2, to: Vec2) => boolean

export interface NavigationPath {
  /** Ordered graph nodes used between the current position and the goal. */
  readonly waypointIds: readonly string[]
  /** Points to follow, including the exact goal as the final point. */
  readonly points: readonly Vec2[]
  readonly cost: number
}

const DISTANCE_EPSILON = 1e-9

function distance(a: Vec2, b: Vec2): number {
  return Math.hypot(b.x - a.x, b.z - a.z)
}

function compareIds(a: string, b: string): number {
  return a.localeCompare(b, 'en')
}

function isClear(from: Vec2, to: Vec2, blocked: SegmentBlocked): boolean {
  return distance(from, to) <= DISTANCE_EPSILON || !blocked(from, to)
}

function clonePoint(point: Vec2): Vec2 {
  return { x: point.x, z: point.z }
}

function assertUniqueWaypointIds(waypoints: readonly RoomWaypoint[]): void {
  const ids = new Set<string>()
  for (const waypoint of waypoints) {
    if (ids.has(waypoint.id)) {
      throw new RangeError(`Duplicate waypoint id: ${waypoint.id}`)
    }
    ids.add(waypoint.id)
  }
}

/**
 * Finds a deterministic path from arbitrary world positions through an authored
 * waypoint graph. It is intentionally stateless so callers can cheaply refresh
 * the path on a fixed AI interval.
 *
 * Start and goal anchors, as well as graph edges, are accepted only when the
 * injected segment test reports a clear ray. Missing neighbor ids are ignored so
 * a partially-authored graph fails closed instead of crashing combat.
 */
export function findNavigationPath(
  waypoints: readonly RoomWaypoint[],
  start: Vec2,
  goal: Vec2,
  blocked: SegmentBlocked,
): NavigationPath | null {
  if (isClear(start, goal, blocked)) {
    return {
      waypointIds: [],
      points: [clonePoint(goal)],
      cost: distance(start, goal),
    }
  }

  assertUniqueWaypointIds(waypoints)

  const waypointById = new Map(
    waypoints.map((waypoint) => [waypoint.id, waypoint] as const),
  )
  const startCandidates = waypoints
    .filter((waypoint) => isClear(start, waypoint.position, blocked))
    .sort((a, b) => compareIds(a.id, b.id))
  const goalCandidateIds = new Set(
    waypoints
      .filter((waypoint) => isClear(waypoint.position, goal, blocked))
      .map((waypoint) => waypoint.id),
  )

  if (startCandidates.length === 0 || goalCandidateIds.size === 0) {
    return null
  }

  const openIds = new Set<string>()
  const closedIds = new Set<string>()
  const costFromStart = new Map<string, number>()
  const previousId = new Map<string, string>()

  for (const candidate of startCandidates) {
    const candidateCost = distance(start, candidate.position)
    const knownCost = costFromStart.get(candidate.id)
    if (knownCost === undefined || candidateCost < knownCost) {
      costFromStart.set(candidate.id, candidateCost)
      openIds.add(candidate.id)
    }
  }

  const pickNextId = (): string | null => {
    let bestId: string | null = null
    let bestScore = Number.POSITIVE_INFINITY
    let bestHeuristic = Number.POSITIVE_INFINITY

    for (const id of openIds) {
      const waypoint = waypointById.get(id)
      const pathCost = costFromStart.get(id)
      if (waypoint === undefined || pathCost === undefined) {
        continue
      }
      const heuristic = distance(waypoint.position, goal)
      const score = pathCost + heuristic
      const scoreIsBetter = score < bestScore - DISTANCE_EPSILON
      const scoreIsTied = Math.abs(score - bestScore) <= DISTANCE_EPSILON
      const heuristicIsBetter = heuristic < bestHeuristic - DISTANCE_EPSILON
      const heuristicIsTied =
        Math.abs(heuristic - bestHeuristic) <= DISTANCE_EPSILON

      if (
        scoreIsBetter ||
        (scoreIsTied && heuristicIsBetter) ||
        (scoreIsTied &&
          heuristicIsTied &&
          (bestId === null || compareIds(id, bestId) < 0))
      ) {
        bestId = id
        bestScore = score
        bestHeuristic = heuristic
      }
    }

    return bestId
  }

  let reachedGoalId: string | null = null

  while (openIds.size > 0) {
    const currentId = pickNextId()
    if (currentId === null) {
      break
    }

    openIds.delete(currentId)
    if (goalCandidateIds.has(currentId)) {
      reachedGoalId = currentId
      break
    }
    closedIds.add(currentId)

    const current = waypointById.get(currentId)
    const currentCost = costFromStart.get(currentId)
    if (current === undefined || currentCost === undefined) {
      continue
    }

    const neighbors = [...new Set(current.neighbors)].sort(compareIds)
    for (const neighborId of neighbors) {
      if (closedIds.has(neighborId)) {
        continue
      }
      const neighbor = waypointById.get(neighborId)
      if (
        neighbor === undefined ||
        !isClear(current.position, neighbor.position, blocked)
      ) {
        continue
      }

      const candidateCost =
        currentCost + distance(current.position, neighbor.position)
      const knownCost = costFromStart.get(neighborId)
      const knownPreviousId = previousId.get(neighborId)
      const strictlyBetter =
        knownCost === undefined || candidateCost < knownCost - DISTANCE_EPSILON
      const equallyGoodWithBetterPredecessor =
        knownCost !== undefined &&
        Math.abs(candidateCost - knownCost) <= DISTANCE_EPSILON &&
        (knownPreviousId === undefined ||
          compareIds(currentId, knownPreviousId) < 0)

      if (!strictlyBetter && !equallyGoodWithBetterPredecessor) {
        continue
      }

      costFromStart.set(neighborId, candidateCost)
      previousId.set(neighborId, currentId)
      openIds.add(neighborId)
    }
  }

  if (reachedGoalId === null) {
    return null
  }

  const waypointIds: string[] = []
  let pathId: string | undefined = reachedGoalId
  while (pathId !== undefined) {
    waypointIds.push(pathId)
    pathId = previousId.get(pathId)
  }
  waypointIds.reverse()

  const points = waypointIds.map((id) =>
    clonePoint(waypointById.get(id)!.position),
  )
  const finalWaypoint = waypointById.get(reachedGoalId)!
  if (distance(finalWaypoint.position, goal) > DISTANCE_EPSILON) {
    points.push(clonePoint(goal))
  }

  return {
    waypointIds,
    points,
    cost:
      costFromStart.get(reachedGoalId)! +
      distance(finalWaypoint.position, goal),
  }
}
