const TELEGRAPH_ROOT = `${import.meta.env.BASE_URL}assets/vfx/`
const telegraphTextureCache = new Map<string, Promise<Texture | null>>()
function useOptionalTelegraphTexture(
  filename: string | null,
): Texture | null | undefined {
  const [texture, setTexture] = useState<Texture | null>()
  useEffect(() => {
    if (!filename) return
    let active = true
    const url = `${TELEGRAPH_ROOT}${filename}`
    const cached = telegraphTextureCache.get(url)
    const request =
      cached ??
      new Promise<Texture | null>((resolve) => {
        new TextureLoader().load(
          url,
          (loaded) => {
            loaded.colorSpace = SRGBColorSpace
            loaded.needsUpdate = true
            resolve(loaded)
          },
          undefined,
          () => resolve(null),
        )
      })
    telegraphTextureCache.set(url, request)
    void request.then((loaded) => {
      if (active) setTexture(loaded)
    })
    return () => {
      active = false
    }
  }, [filename])
  return texture
}

function stableHash(value: string): number {
  let hash = 2166136261
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index)
    hash = Math.imul(hash, 16777619)
  }
  return hash >>> 0
}

function isActiveCombatPhase(phase: unknown): boolean {
  return phase === 'playing'
}

function getDefinition(id: CombatantArchetypeId) {
  if (isSceneBoss(id)) return getBossArchetype(id)
  const definition = ENEMY_ARCHETYPES.find((enemy) => enemy.id === id)
  if (!definition) throw new Error(`Unknown enemy archetype: ${id}`)
  return definition
}

function attackColor(
  archetypeId: CombatantArchetypeId,
  observed = false,
): string {
  return resolveBossAttackVisualColor(
    archetypeId,
    observed ? '#ffffff' : TOON_PALETTE.coralLight,
  )
}

function attackMotionFor(
  archetypeId: CombatantArchetypeId,
  kind: AttackKind,
): CharacterMotion {
  if (kind !== 'ranged') return 'attack'
  return isSceneBoss(archetypeId) ? 'magic' : 'ranged'
}

function AttackTelegraph({
  archetypeId,
  attackRef,
  positionRef,
  observedRef,
  boneArcherSpreads,
  healthRatio,
}: {
  archetypeId: CombatantArchetypeId
  attackRef: MutableRefObject<AttackCycle>
  positionRef: MutableRefObject<Vector3>
  observedRef: MutableRefObject<boolean>
  boneArcherSpreads: readonly number[]
  healthRatio: number
}) {
  const directionalRef = useRef<Group>(null)
  const spreadGuidesRef = useRef<Group>(null)
  const targetRef = useRef<Group>(null)
  const queenRootRef = useRef<Group>(null)
  const materials = useRef<MeshBasicMaterial[]>([])
  const quaternion = useMemo(() => new Quaternion(), [])
  const runeTexture = useOptionalTelegraphTexture(
    isSceneBoss(archetypeId)
      ? 'signature-boss-sigil.png'
      : archetypeId === 'bone-archer'
        ? 'signature-warning-rune.png'
        : null,
  )

  useFrame(() => {
    const attack = attackRef.current
    const active =
      attack.phase === 'windup' && (attack.tokenHeld || observedRef.current)
    const directional = directionalRef.current
    const spreadGuides = spreadGuidesRef.current
    const target = targetRef.current
    const queenRoot = queenRootRef.current
    if (!directional || !spreadGuides || !target || !queenRoot) return

    const isTargetRune =
      archetypeId === 'bone-archer' ||
      (archetypeId === 'grave-warden' && attack.kind === 'ranged')
    directional.visible = active && !isTargetRune
    spreadGuides.visible =
      active && archetypeId === 'bone-archer' && boneArcherSpreads.length > 1
    target.visible = active && isTargetRune
    queenRoot.visible = active && isMoonbriarQueen(archetypeId)
    if (!active) return

    const progress = 1 - attack.remaining / Math.max(0.001, attack.duration)
    const pulse = observedRef.current
      ? 0.42
      : 0.55 + Math.max(0, progress) * 0.38
    for (const material of materials.current) {
      material.opacity = pulse
      material.color.set(attackColor(archetypeId, observedRef.current))
    }

    quaternionFromNegativeZForward(attack.direction, quaternion)
    directional.quaternion.copy(quaternion)
    spreadGuides.quaternion.copy(quaternion)
    directional.scale.setScalar(0.92 + Math.max(0, progress) * 0.08)
    target.position.set(
      attack.target.x - positionRef.current.x,
      -0.69,
      attack.target.z - positionRef.current.z,
    )
    target.scale.setScalar(0.72 + Math.max(0, progress) * 0.4)
    queenRoot.position.set(
      attack.target.x - positionRef.current.x,
      -0.68,
      attack.target.z - positionRef.current.z,
    )
    queenRoot.scale.setScalar(0.9 + Math.max(0, progress) * 0.12)
  })

  const registerMaterial = (material: MeshBasicMaterial | null) => {
    if (material && !materials.current.includes(material)) {
      materials.current.push(material)
    }
  }

  return (
    <>
      <group ref={directionalRef} position={[0, -0.69, 0]} visible={false}>
        {isMoonbriarQueen(archetypeId) ? (
          <group name="moonbriar-telegraph-thorn-fan">
            {(
              getBossProjectilePattern(archetypeId, healthRatio)?.spreads ?? []
            ).map((spread) => (
              <group key={spread} rotation={[0, spread, 0]}>
                <mesh
                  position={[0, 0.009, -4.2]}
                  rotation={[-Math.PI / 2, 0, 0]}
                >
                  <planeGeometry args={[0.075, 8.4]} />
                  <meshBasicMaterial
                    ref={registerMaterial}
                    color={attackColor(archetypeId)}
                    transparent
                    opacity={0.5}
                    depthWrite={false}
                    blending={AdditiveBlending}
                    side={DoubleSide}
                  />
                </mesh>
              </group>
            ))}
            <mesh rotation={[-Math.PI / 2, 0, Math.PI / 8]}>
              <ringGeometry args={[0.68, 0.82, 8]} />
              <meshBasicMaterial
                ref={registerMaterial}
                color={attackColor(archetypeId)}
                transparent
                opacity={0.48}
                depthWrite={false}
                blending={AdditiveBlending}
                side={DoubleSide}
              />
            </mesh>
          </group>
        ) : archetypeId === 'crypt-brute' ? (
          <mesh position={[0, 0.006, -3]} rotation={[-Math.PI / 2, 0, 0]}>
            <planeGeometry args={[1.1, 6]} />
            <meshBasicMaterial
              ref={registerMaterial}
              color={attackColor(archetypeId)}
              transparent
              opacity={0.5}
              depthWrite={false}
              blending={AdditiveBlending}
              side={DoubleSide}
            />
          </mesh>
        ) : archetypeId === 'grave-warden' ? (
          <group>
            {runeTexture ? (
              <mesh position={[0, 0.012, 0]} rotation={[-Math.PI / 2, 0, 0]}>
                <planeGeometry args={[4.9, 4.9]} />
                <meshBasicMaterial
                  ref={registerMaterial}
                  map={runeTexture}
                  color={attackColor(archetypeId)}
                  transparent
                  opacity={0.5}
                  alphaTest={0.01}
                  depthWrite={false}
                  blending={AdditiveBlending}
                  side={DoubleSide}
                />
              </mesh>
            ) : null}
            <mesh rotation={[-Math.PI / 2, 0, 0]}>
              <ringGeometry args={[0.55, 2.75, 42]} />
              <meshBasicMaterial
                ref={registerMaterial}
                color={attackColor(archetypeId)}
                transparent
                opacity={0.5}
                depthWrite={false}
                blending={AdditiveBlending}
                side={DoubleSide}
              />
            </mesh>
            <mesh rotation={[-Math.PI / 2, 0, Math.PI / 4]}>
              <ringGeometry args={[1.35, 1.46, 4]} />
              <meshBasicMaterial
                ref={registerMaterial}
                color={attackColor(archetypeId)}
                transparent
                opacity={0.5}
                depthWrite={false}
                blending={AdditiveBlending}
              />
            </mesh>
          </group>
        ) : (
          <mesh position={[0, 0.006, -0.72]} rotation={[-Math.PI / 2, 0, 0]}>
            <ringGeometry
              args={[0.28, 1.55, 28, 1, Math.PI * 0.1, Math.PI * 0.8]}
            />
            <meshBasicMaterial
              ref={registerMaterial}
              color={attackColor(archetypeId)}
              transparent
              opacity={0.5}
              depthWrite={false}
              blending={AdditiveBlending}
              side={DoubleSide}
            />
          </mesh>
        )}
      </group>
      <group ref={spreadGuidesRef} position={[0, -0.68, 0]} visible={false}>
        {boneArcherSpreads.length > 1
          ? boneArcherSpreads.map((spread) => (
              <group key={spread} rotation={[0, spread, 0]}>
                <mesh
                  position={[0, 0.008, -4.5]}
                  rotation={[-Math.PI / 2, 0, 0]}
                >
                  <planeGeometry args={[0.055, 9]} />
                  <meshBasicMaterial
                    ref={registerMaterial}
                    color={attackColor(archetypeId)}
                    transparent
                    opacity={0.5}
                    depthWrite={false}
                    blending={AdditiveBlending}
                    side={DoubleSide}
                  />
                </mesh>
              </group>
            ))
          : null}
      </group>
      <group
        ref={queenRootRef}
        visible={false}
        name="moonbriar-root-cross-telegraph"
      >
        {[0, Math.PI / 2].map((rotation) => (
          <mesh
            key={rotation}
            position={[0, 0.008, 0]}
            rotation={[-Math.PI / 2, 0, rotation]}
          >
            <planeGeometry args={[0.82, 8.4]} />
            <meshBasicMaterial
              ref={registerMaterial}
              color={TOON_PALETTE.coralLight}
              transparent
              opacity={0.5}
              depthWrite={false}
              blending={AdditiveBlending}
              side={DoubleSide}
            />
          </mesh>
        ))}
        <mesh rotation={[-Math.PI / 2, 0, Math.PI / 4]}>
          <ringGeometry args={[0.48, 0.62, 4]} />
          <meshBasicMaterial
            ref={registerMaterial}
            color={TOON_PALETTE.coralLight}
            transparent
            opacity={0.55}
            depthWrite={false}
            blending={AdditiveBlending}
          />
        </mesh>
      </group>
      <group ref={targetRef} visible={false}>
        {runeTexture ? (
          <mesh position={[0, 0.012, 0]} rotation={[-Math.PI / 2, 0, 0]}>
            <planeGeometry
              args={[
                archetypeId === 'grave-warden' ? 2.7 : 1.55,
                archetypeId === 'grave-warden' ? 2.7 : 1.55,
              ]}
            />
            <meshBasicMaterial
              ref={registerMaterial}
              map={runeTexture}
              color={attackColor(archetypeId)}
              transparent
              opacity={0.5}
              alphaTest={0.01}
              depthWrite={false}
              blending={AdditiveBlending}
              side={DoubleSide}
            />
          </mesh>
        ) : null}
        <mesh rotation={[-Math.PI / 2, 0, 0]}>
          <ringGeometry
            args={[
              archetypeId === 'grave-warden' ? 0.42 : 0.24,
              archetypeId === 'grave-warden' ? 1.18 : 0.68,
              32,
            ]}
          />
          <meshBasicMaterial
            ref={registerMaterial}
            color={attackColor(archetypeId)}
            transparent
            opacity={0.5}
            depthWrite={false}
            blending={AdditiveBlending}
            side={DoubleSide}
          />
        </mesh>
        <mesh rotation={[-Math.PI / 2, 0, Math.PI / 4]}>
          <ringGeometry args={[0.52, 0.62, 4]} />
          <meshBasicMaterial
            ref={registerMaterial}
            color={attackColor(archetypeId)}
            transparent
            opacity={0.5}
            depthWrite={false}
            blending={AdditiveBlending}
          />
        </mesh>
      </group>
    </>
  )
}

function EnemyHealthBar({
  archetypeId,
  ratio,
}: {
  archetypeId: CombatantArchetypeId
  ratio: number
}) {
  const billboardRef = useRef<Group>(null)
  const isBoss = isSceneBoss(archetypeId)
  const isBrute = archetypeId === 'crypt-brute'
  const width = isBoss ? 1.6 : isBrute ? 1.1 : 0.9
  const { healthBarHeight: height } = getEnemyStatusLayout(archetypeId)
  const healthRatio = Math.max(0, Math.min(1, ratio))

  useFrame(({ camera }) => {
    billboardRef.current?.quaternion.copy(camera.quaternion)
  })

  return (
    <group
      ref={billboardRef}
      position={[0, height, 0]}
      name={`enemy-health-billboard-${archetypeId}`}
    >
      {/*
        These are HUD elements that happen to live in the world, so they opt out
        of tone mapping. The DOM HUD paints TOON_PALETTE.gold directly, while
        the same hex pushed through NeutralToneMapping at 0.92 exposure came
        back a muted brown — which is why the bars read as unrelated to the
        interface even though they were already using its palette.
      */}
      <mesh renderOrder={29}>
        <planeGeometry args={[width + 0.14, 0.185]} />
        <meshBasicMaterial
          color={TOON_PALETTE.ink}
          transparent
          opacity={0.92}
          depthTest
          depthWrite={false}
          side={DoubleSide}
          toneMapped={false}
        />
      </mesh>
      <mesh position={[0, 0, 0.003]} renderOrder={30}>
        <planeGeometry args={[width + 0.08, 0.13]} />
        <meshBasicMaterial
          color={TOON_PALETTE.navy}
          transparent
          opacity={0.95}
          depthTest
          depthWrite={false}
          side={DoubleSide}
          toneMapped={false}
        />
      </mesh>
      <mesh
        position={[(healthRatio - 1) * width * 0.48, 0, 0.006]}
        scale={[Math.max(0.001, healthRatio), 1, 1]}
        renderOrder={31}
      >
        <planeGeometry args={[width * 0.96, 0.075]} />
        {/*
          `transparent` is load-bearing, not cosmetic: three.js draws the whole
          opaque list before the transparent one, so an opaque fill was being
          painted over by its own translucent track. What looked like a muted
          brown bar was the gold bleeding through at the track's 12% gap.
        */}
        <meshBasicMaterial
          color={TOON_PALETTE.white}
          depthTest
          depthWrite={false}
          side={DoubleSide}
          toneMapped={false}
          transparent
        />
      </mesh>
    </group>
  )
}

function GazeRuleMarker({
  archetypeId,
  kind,
  pulseUntil,
  urgent = false,
}: {
  archetypeId: CombatantArchetypeId
  kind: GazeRuleMarkerKind
  pulseUntil?: MutableRefObject<number>
  urgent?: boolean
}) {
  const billboardRef = useRef<Group>(null)
  const haloMaterialRef = useRef<MeshBasicMaterial>(null)
  const worldPosition = useRef(new Vector3())
  const { markerHeight: height, markerRadius: radius } =
    getEnemyStatusLayout(archetypeId)
  const showO = kind === 'o' || kind === 'ox'
  const showX = kind === 'x' || kind === 'ox'

  useFrame(({ camera, clock }) => {
    const marker = billboardRef.current
    if (!marker) return
    marker.quaternion.copy(camera.quaternion)
    marker.getWorldPosition(worldPosition.current)
    const distanceScale = Math.max(
      0.95,
      Math.min(1.15, camera.position.distanceTo(worldPosition.current) / 16),
    )
    marker.scale.setScalar(distanceScale)
    const casting = pulseUntil ? runtime.elapsed < pulseUntil.current : false
    const emphasized = casting || urgent
    const wave =
      Math.sin(clock.elapsedTime * (emphasized ? 17 : 4.5)) * 0.5 + 0.5
    if (haloMaterialRef.current) {
      haloMaterialRef.current.opacity = emphasized
        ? 0.28 + wave * 0.42
        : 0.16 + wave * 0.12
    }
  })

  return (
    <group
      ref={billboardRef}
      position={[0, height, 0]}
      name={`gaze-rule-marker-${kind}`}
    >
      <mesh position={[0, 0, -0.004]} renderOrder={40}>
        <ringGeometry args={[radius * 0.94, radius, 32]} />
        <meshBasicMaterial
          ref={haloMaterialRef}
          color="#f12b55"
          transparent
          opacity={0.22}
          depthTest={false}
          depthWrite={false}
          blending={AdditiveBlending}
          side={DoubleSide}
          toneMapped={false}
          fog={false}
        />
      </mesh>
      <mesh position={[0, 0, -0.003]} renderOrder={41}>
        <circleGeometry args={[radius * 0.84, 32]} />
        <meshBasicMaterial
          color={TOON_PALETTE.ink}
          transparent
          opacity={0.97}
          depthTest={false}
          depthWrite={false}
          side={DoubleSide}
          toneMapped={false}
          fog={false}
        />
      </mesh>
      <mesh position={[0, 0, -0.002]} renderOrder={42}>
        <ringGeometry args={[radius * 0.84, radius * 0.94, 32]} />
        <meshBasicMaterial
          color="#fff3f6"
          transparent
          depthTest={false}
          depthWrite={false}
          side={DoubleSide}
          toneMapped={false}
          fog={false}
        />
      </mesh>
      {showO ? (
        <>
          <mesh position={[0, 0, -0.001]} renderOrder={43}>
            <ringGeometry args={[radius * 0.4, radius * 0.64, 32]} />
            <meshBasicMaterial
              color="#fff3f6"
              transparent
              depthTest={false}
              depthWrite={false}
              side={DoubleSide}
              toneMapped={false}
              fog={false}
            />
          </mesh>
          <mesh position={[0, 0, 0]} renderOrder={44}>
            <ringGeometry args={[radius * 0.45, radius * 0.59, 32]} />
            <meshBasicMaterial
              color="#ff183f"
              transparent
              depthTest={false}
              depthWrite={false}
              side={DoubleSide}
              toneMapped={false}
              fog={false}
            />
          </mesh>
        </>
      ) : null}
      {showX
        ? [Math.PI / 4, -Math.PI / 4].map((rotation, index) => (
            <group key={rotation} rotation={[0, 0, rotation]}>
              <mesh position={[0, 0, 0.001 + index * 0.001]} renderOrder={45}>
                <planeGeometry args={[radius * 1.44, radius * 0.34]} />
                <meshBasicMaterial
                  color="#fff3f6"
                  transparent
                  depthTest={false}
                  depthWrite={false}
                  side={DoubleSide}
                  toneMapped={false}
                  fog={false}
                />
              </mesh>
              <mesh position={[0, 0, 0.003 + index * 0.001]} renderOrder={46}>
                <planeGeometry args={[radius * 1.44, radius * 0.24]} />
                <meshBasicMaterial
                  color="#ff183f"
                  transparent
                  depthTest={false}
                  depthWrite={false}
                  side={DoubleSide}
                  toneMapped={false}
                  fog={false}
                />
              </mesh>
            </group>
          ))
        : null}
    </group>
  )
}

function ProceduralEnemyVisual({
  archetypeId,
  observed,
}: {
  archetypeId: CombatantArchetypeId
  observed: boolean
}) {
  const isBoss = isSceneBoss(archetypeId)
  const isArcher = archetypeId === 'bone-archer'
  const isBrute = archetypeId === 'crypt-brute'
  const isBreaker = archetypeId === 'veil-breaker'
  const isThrall = archetypeId === 'blind-thrall'
  const bodyColor = observed ? TOON_PALETTE.white : TOON_PALETTE.coral
  const boneColor = observed ? TOON_PALETTE.white : TOON_PALETTE.coral
  const scale = isBoss ? 1.55 : isBrute ? 1.22 : isThrall ? 0.82 : 1

  return (
    <group scale={scale} name={`enemy-model-${archetypeId}`}>
      <group scale={1.06}>
        <mesh position={[0, 0.05, 0]}>
          <capsuleGeometry args={[0.35, 0.62, 5, 9]} />
          <meshBasicMaterial color={TOON_PALETTE.ink} side={BackSide} />
        </mesh>
        <mesh position={[0, 0.52, 0]}>
          <dodecahedronGeometry args={[0.3, 0]} />
          <meshBasicMaterial color={TOON_PALETTE.ink} side={BackSide} />
        </mesh>
      </group>
      <mesh castShadow position={[0, 0.05, 0]}>
        <capsuleGeometry args={[0.34, 0.62, 5, 9]} />
        <meshToonMaterial color={bodyColor} gradientMap={toonGradientMap} />
      </mesh>
      <mesh castShadow position={[0, 0.52, 0]}>
        <dodecahedronGeometry args={[0.29, 0]} />
        <meshToonMaterial color={boneColor} gradientMap={toonGradientMap} />
      </mesh>
      <mesh position={[-0.1, 0.55, -0.25]}>
        <sphereGeometry args={[0.05, 8, 6]} />
        <meshBasicMaterial
          color={observed ? TOON_PALETTE.white : TOON_PALETTE.coral}
          toneMapped={false}
        />
      </mesh>
      <mesh position={[0.1, 0.55, -0.25]}>
        <sphereGeometry args={[0.05, 8, 6]} />
        <meshBasicMaterial
          color={observed ? TOON_PALETTE.white : TOON_PALETTE.coral}
          toneMapped={false}
        />
      </mesh>
      {isThrall && (
        <group position={[0, 0.55, -0.305]} name="blind-thrall-eye-mark">
          <mesh position={[-0.1, 0, 0]} rotation={[0, 0, Math.PI / 4]}>
            <boxGeometry args={[0.16, 0.025, 0.02]} />
            <meshBasicMaterial color={TOON_PALETTE.ink} toneMapped={false} />
          </mesh>
          <mesh position={[0.1, 0, 0]} rotation={[0, 0, -Math.PI / 4]}>
            <boxGeometry args={[0.16, 0.025, 0.02]} />
            <meshBasicMaterial color={TOON_PALETTE.ink} toneMapped={false} />
          </mesh>
        </group>
      )}
      {isBreaker && (
        <group position={[0, 0.78, 0]} name="veil-breaker-crown">
          {[-1, 0, 1].map((offset) => (
            <mesh
              key={offset}
              position={[offset * 0.14, Math.abs(offset) * -0.04, 0]}
              rotation={[0, 0, offset * -0.2]}
            >
              <coneGeometry args={[0.07, 0.3, 4]} />
              <meshToonMaterial
                color={TOON_PALETTE.coralLight}
                gradientMap={toonGradientMap}
              />
            </mesh>
          ))}
        </group>
      )}
      {isArcher && (
        <group position={[0.35, 0.08, -0.12]}>
          <mesh rotation={[0, 0, Math.PI / 2]}>
            <torusGeometry args={[0.4, 0.04, 6, 16, Math.PI]} />
            <meshToonMaterial
              color={TOON_PALETTE.gold}
              gradientMap={toonGradientMap}
            />
          </mesh>
          <mesh position={[0, 0, -0.32]}>
            <boxGeometry args={[0.06, 0.06, 0.74]} />
            <meshToonMaterial
              color={TOON_PALETTE.indigo}
              gradientMap={toonGradientMap}
            />
          </mesh>
        </group>
      )}
      {isBrute && (
        <group position={[0.48, 0.15, -0.12]} rotation={[0, 0, -0.22]}>
          <mesh position={[0, 0, -0.28]}>
            <boxGeometry args={[0.08, 0.08, 0.9]} />
            <meshToonMaterial color="#8c4d2e" gradientMap={toonGradientMap} />
          </mesh>
          <mesh position={[0, 0, -0.72]}>
            <boxGeometry args={[0.5, 0.08, 0.25]} />
            <meshToonMaterial
              color={TOON_PALETTE.goldLight}
              gradientMap={toonGradientMap}
            />
          </mesh>
        </group>
      )}
      {isBoss && (
        <group position={[0, 0.93, 0]}>
          {[0, 1, 2, 3, 4].map((index) => (
            <mesh
              key={index}
              position={[
                Math.cos((index / 5) * Math.PI * 2) * 0.26,
                index % 2 === 0 ? 0.08 : 0,
                Math.sin((index / 5) * Math.PI * 2) * 0.26,
              ]}
            >
              <coneGeometry args={[0.08, 0.36, 4]} />
              <meshToonMaterial
                color={TOON_PALETTE.gold}
                gradientMap={toonGradientMap}
              />
            </mesh>
          ))}
        </group>
      )}
    </group>
  )
}

function EnemyVisual({
  archetypeId,
  observed,
  motionRef,
  paused,
}: {
  archetypeId: CombatantArchetypeId
  observed: boolean
  motionRef: CharacterMotionRef
  paused: boolean
}) {
  const isBoss = isSceneBoss(archetypeId)
  const bossVisualSpec = isBoss ? BOSS_VISUAL_SPECS[archetypeId] : null
  const isBrute = archetypeId === 'crypt-brute'
  const isThrall = archetypeId === 'blind-thrall'
  const tint = TOON_PALETTE.coral
  const tintStrength = 1

  return (
    <AssetBoundary
      fallback={
        <ProceduralEnemyVisual archetypeId={archetypeId} observed={observed} />
      }
      resetKey={archetypeId}
    >
      <AnimatedCharacterModel
        name={`enemy-model-${archetypeId}`}
        url={ENEMY_MODEL_URLS[archetypeId] ?? ENEMY_MODEL_URLS['grave-husk']!}
        motionRef={motionRef}
        skeleton
        rangedStyle={isBoss ? 'magic' : 'bow'}
        paused={paused || observed}
        frozen={observed}
        tint={tint}
        tintStrength={tintStrength}
        position={[0, -0.7, 0]}
        rotation={[0, Math.PI, 0]}
        scale={
          bossVisualSpec?.modelScale ??
          (isBrute ? 0.62 : isThrall ? 0.44 : 0.52)
        }
        attachments={ENEMY_ATTACHMENTS[archetypeId] ?? []}
      />
    </AssetBoundary>
  )
}

export function Enemy({
  id,
  archetypeId,
  position,
  waypoints,
  attackDirector,
  encounterTier,
  difficultyRank = 1,
  absoluteChamber,
  healthMultiplier = 1,
  eliteAffixId = null,
  mutationId = null,
  onDefeated,
}: EnemyProps) {
  const definition = useMemo(() => getDefinition(archetypeId), [archetypeId])
  const combatStats = useMemo(
    () => applyEncounterModifiers(definition.stats, eliteAffixId, mutationId),
    [definition.stats, eliteAffixId, mutationId],
  )
  const selectedRunes = useGameStore((state) => state.selectedRunes)
  const visionRuneRules = useMemo(
    () =>
      resolveVisionRuneRules(selectedRunes, DEFAULT_VISION_CONFIG.exitGraceMs),
    [selectedRunes],
  )
  const undyingEyeEnabled = useMemo(
    () => getActiveSynergy(selectedRunes) === 'undying-eye',
    [selectedRunes],
  )
  const observationProfile = useMemo(() => {
    const base = getArchetypeObservationProfile(archetypeId, difficultyRank)
    if (base.mode !== 'break-after' || base.breakAfterMs === undefined)
      return base
    return {
      ...base,
      breakAfterMs: base.breakAfterMs * visionRuneRules.breakAfterMultiplier,
    }
  }, [archetypeId, difficultyRank, visionRuneRules.breakAfterMultiplier])
  const maxHealth = useMemo(
    () =>
      Math.max(
        1,
        Math.round(
          combatStats.maxHealth *
            (Number.isFinite(healthMultiplier) && healthMultiplier > 0
              ? healthMultiplier
              : 1),
        ),
      ),
    [combatStats.maxHealth, healthMultiplier],
  )
  const pressureProfile = useMemo(
    () =>
      getEncounterPressureProfile(
        encounterTier,
        difficultyRank,
        absoluteChamber,
      ),
    [absoluteChamber, difficultyRank, encounterTier],
  )
  const bodyRef = useRef<RapierRigidBody>(null)
  const visualRef = useRef<Group>(null)
  const healthRef = useRef<number>(maxHealth)
  const externalVelocity = useRef(new Vector3())
  const observation = useRef<ObservationPolicyState>(
    INITIAL_OBSERVATION_POLICY_STATE,
  )
  // `observedRef` is the physical pause flag used by animation and AI.
  // Inverse-gaze enemies can be frozen while hidden, so HUD/rune gaze state
  // is tracked separately instead of treating every pause as observation.
  const observedRef = useRef(false)
  const gazeObservedRef = useRef(false)
  const gazeDispelUntil = useRef(0)
  const liberationPulseUntil = useRef(0)
  const nextLiberationAt = useRef(
    runtime.elapsed + 3.2 + (stableHash(id) % 900) / 1_000,
  )
  const breakProgressRef = useRef(0)
  const undyingEyeState = useRef<UndyingEyeState>(INITIAL_UNDYING_EYE_STATE)
  const deadRef = useRef(false)
  const deathRemaining = useRef(0)
  const hitAnimationEndsAt = useRef(0)
  const motionRef = useRef<CharacterMotionState>({
    motion: 'idle',
    revision: 0,
  })
  const positionRef = useRef(new Vector3(position.x, 0.72, position.z))
  const navigationRefresh = useRef((stableHash(id) % 200) / 1_000)
  const navigationPoints = useRef<readonly { x: number; z: number }[]>([])
  const animationTime = useRef((stableHash(id) % 17) / 5.5)
  const rangedCastIndex = useRef(0)
  const threatPublished = useRef(false)
  const attackRef = useRef<AttackCycle>({
    phase: 'recover',
    kind: 'melee',
    remaining: 0.9 + (stableHash(id) % 350) / 1000,
    duration: 0,
    tokenHeld: false,
    direction: new Vector3(0, 0, -1),
    target: new Vector3(position.x, 0, position.z),
  })
  const queuedMoonbriarDash = useRef<{
    remaining: number
    nextAt: number
    direction: Vector3
    impulse: number
  } | null>(null)
  const [health, setHealth] = useState<number>(maxHealth)
  const [observed, setObserved] = useState(false)
  const [observationBroken, setObservationBroken] = useState(false)
  const [gazeDispelled, setGazeDispelled] = useState(false)
  const [dying, setDying] = useState(false)
  const [dead, setDead] = useState(false)
  const phase = useGameStore((state) => state.phase)
  const { world, rapier } = useRapier()
  const tmpDirection = useMemo(() => new Vector3(), [])
  const targetQuaternion = useMemo(() => new Quaternion(), [])
  // Scratch vectors for the movement tick. Every one of these was a fresh
  // allocation per enemy per frame; the separation loop allocated per
  // neighbour on top of that.
  const tmpAiDirection = useMemo(() => new Vector3(), [])
  const tmpStrafe = useMemo(() => new Vector3(), [])
  const tmpSeparation = useMemo(() => new Vector3(), [])
  const tmpAway = useMemo(() => new Vector3(), [])
  const tmpVelocity = useMemo(() => new Vector3(), [])

  // Reused across every cast, mirroring VisionCone's pattern. This runs two to
  // three times per enemy per frame, so allocating a Ray and a Vector3 each
  // time was the single largest source of per-frame garbage in the scene.
  const staticRay = useRef(
    new rapier.Ray({ x: 0, y: 0, z: 0 }, { x: 1, y: 0, z: 0 }),
  )
  const visionConfig = useRef({ ...DEFAULT_VISION_CONFIG })

  /** Scalar form, so callers need no temporary Vector3 for an eye position. */
  const castStaticSegment = useCallback(
    (
      fromX: number,
      fromY: number,
      fromZ: number,
      toX: number,
      toY: number,
      toZ: number,
      trim = 0.32,
    ) => {
      const dx = toX - fromX
      const dy = toY - fromY
      const dz = toZ - fromZ
      const distance = Math.sqrt(dx * dx + dy * dy + dz * dz)
      if (distance <= trim) return false
      const ray = staticRay.current
      ray.origin.x = fromX
      ray.origin.y = fromY
      ray.origin.z = fromZ
      ray.dir.x = dx / distance
      ray.dir.y = dy / distance
      ray.dir.z = dz / distance
      const flags =
        rapier.QueryFilterFlags.EXCLUDE_DYNAMIC |
        rapier.QueryFilterFlags.EXCLUDE_KINEMATIC
      return world.castRay(ray, distance - trim, true, flags) !== null
    },
    [rapier, world],
  )

  const clearThreat = useCallback(() => {
    if (!threatPublished.current) return
    useGameStore.getState().clearThreat(id)
    threatPublished.current = false
  }, [id])

  const publishThreat = useCallback(() => {
    const toEnemy = positionRef.current.clone().sub(runtime.playerPosition)
    const angleDeg = (Math.atan2(toEnemy.x, -toEnemy.z) * 180) / Math.PI
    useGameStore.getState().setThreat({
      id,
      angleDeg,
      kind: isSceneBoss(archetypeId)
        ? 'boss'
        : attackRef.current.kind === 'ranged'
          ? 'ranged'
          : 'melee',
      durationMs: Math.round(attackRef.current.remaining * 1000),
    })
    audioEngine.playDirectional(
      isSceneBoss(archetypeId)
        ? 'warning-boss'
        : attackRef.current.kind === 'ranged'
          ? 'warning-ranged'
          : 'warning-melee',
      Math.max(-1, Math.min(1, toEnemy.x / 8)),
    )
    threatPublished.current = true
  }, [archetypeId, id])

  const releaseAttackToken = useCallback(() => {
    if (attackRef.current.tokenHeld) attackDirector.release(id)
    attackRef.current.tokenHeld = false
    clearThreat()
  }, [attackDirector, clearThreat, id])

  const dispelObservation = useCallback(
    (durationMs: number) => {
      gazeDispelUntil.current = Math.max(
        gazeDispelUntil.current,
        runtime.elapsed + Math.max(0, durationMs) / 1_000,
      )
      observation.current = INITIAL_OBSERVATION_POLICY_STATE
      breakProgressRef.current = 0
      setObservationBroken(false)
      setGazeDispelled(true)
      if (observedRef.current) {
        observedRef.current = false
        setObserved(false)
        const liveHandle = runtime.enemies.get(id)
        if (liveHandle) liveHandle.frozen = false
      }
      if (gazeObservedRef.current) {
        gazeObservedRef.current = false
        const liveHandle = runtime.enemies.get(id)
        if (liveHandle) liveHandle.observed = false
        useGameStore.getState().adjustObservedEnemies(-1)
      }
      releaseAttackToken()
    },
    [id, releaseAttackToken],
  )

  const takeHit = useCallback(
    (rawDamage: number, direction: Vector3, knockback: number) => {
      if (deadRef.current) return
      const defensiveStats = resolveEliteStateStats(
        combatStats,
        eliteAffixId,
        healthRef.current / maxHealth,
        observedRef.current,
      )
      const result = applyDamage(
        healthRef.current,
        rawDamage,
        defensiveStats.armor,
      )
      healthRef.current = result.health
      setHealth(result.health)
      const runtimeHandle = runtime.enemies.get(id)
      if (runtimeHandle) runtimeHandle.healthRatio = result.health / maxHealth
      externalVelocity.current.addScaledVector(direction, knockback)
      runtime.cameraTrauma = Math.max(runtime.cameraTrauma, 0.28)
      audioEngine.play('hit')
      useGameStore.getState().spawnEffect({
        id: makeRuntimeId('hit'),
        kind: 'hit',
        position: [positionRef.current.x, 0.58, positionRef.current.z],
        direction: [direction.x, 0, direction.z],
        color: observedRef.current ? TOON_PALETTE.white : TOON_PALETTE.coral,
        durationMs: 260,
      })

      if (result.defeated) {
        deadRef.current = true
        setDying(true)
        deathRemaining.current = isSceneBoss(archetypeId) ? 0.66 : 0.6
        setCharacterMotion(motionRef, 'death', true)
        releaseAttackToken()
        bodyRef.current?.setEnabled(false)
        if (observedRef.current) {
          observedRef.current = false
          setObserved(false)
        }
        if (gazeObservedRef.current) {
          gazeObservedRef.current = false
          useGameStore.getState().adjustObservedEnemies(-1)
        }
        runtime.enemies.delete(id)
        const awardedScore = calculateCombatantScore(
          archetypeId,
          eliteAffixId,
          mutationId,
        )
        useGameStore.getState().defeatEnemy(awardedScore)
        useGameStore.getState().spawnEffect({
          id: makeRuntimeId('death'),
          kind: 'death',
          position: [positionRef.current.x, 0.52, positionRef.current.z],
          color: TOON_PALETTE.coral,
          durationMs: isSceneBoss(archetypeId) ? 720 : 480,
          label: `+${awardedScore.toLocaleString('ko-KR')}`,
        })
        audioEngine.play('death')
      } else {
        hitAnimationEndsAt.current = runtime.elapsed + 0.16
        setCharacterMotion(motionRef, 'hit', true)
      }
    },
    [
      archetypeId,
      combatStats,
      eliteAffixId,
      id,
      maxHealth,
      mutationId,
      releaseAttackToken,
    ],
  )

  useEffect(() => {
    const handle = {
      id,
      archetypeId,
      position: positionRef.current,
      observed: gazeObservedRef.current,
      frozen: observedRef.current,
      observationMode: observationProfile.mode,
      observationProgress: breakProgressRef.current,
      observationBroken: observation.current.broken,
      healthRatio: healthRef.current / maxHealth,
      undyingEyeMarked: undyingEyeState.current.marked,
      continuousObservedMs: undyingEyeState.current.observedMs,
      dispelObservation,
      takeHit,
    }
    runtime.enemies.set(id, handle)
    return () => {
      releaseAttackToken()
      if (gazeObservedRef.current) {
        gazeObservedRef.current = false
        useGameStore.getState().adjustObservedEnemies(-1)
      }
      runtime.enemies.delete(id)
    }
  }, [
    archetypeId,
    combatStats,
    id,
    maxHealth,
    observationProfile.mode,
    dispelObservation,
    releaseAttackToken,
    takeHit,
  ])

  useEffect(() => {
    if (dead) onDefeated?.()
  }, [dead, onDefeated])

  const triggerMoonbriarDash = useCallback(
    (direction: Vector3, impulse: number) => {
      externalVelocity.current.addScaledVector(direction, impulse)
      useGameStore.getState().spawnEffect({
        id: makeRuntimeId('moonbriar-dash'),
        kind: 'trail',
        position: [positionRef.current.x, 0.28, positionRef.current.z],
        direction: [direction.x, 0, direction.z],
        color: TOON_PALETTE.cyanLight,
        durationMs: 600,
        length: 5.2,
        width: 1.1,
        variant: 'lane',
      })
    },
    [],
  )

  const resolveAttack = useCallback(() => {
    const attack = attackRef.current
    const enemyPosition = positionRef.current
    const playerPosition = runtime.playerPosition
    const liveStats = resolveEliteStateStats(
      combatStats,
      eliteAffixId,
      healthRef.current / maxHealth,
      observedRef.current,
    )
    const blocked = castStaticSegment(
      enemyPosition.x,
      0.72,
      enemyPosition.z,
      playerPosition.x,
      0.72,
      playerPosition.z,
    )

    if (attack.kind === 'ranged') {
      if (!blocked) {
        const bossPattern = getBossProjectilePattern(
          archetypeId,
          healthRef.current / maxHealth,
          rangedCastIndex.current,
        )
        const spreads =
          bossPattern?.spreads ?? pressureProfile.boneArcherSpreads
        for (const spread of spreads) {
          const direction = attack.direction
            .clone()
            .applyAxisAngle(new Vector3(0, 1, 0), spread)
          useGameStore.getState().spawnProjectile({
            id: makeRuntimeId(bossPattern?.idPrefix ?? 'enemy-shot'),
            position: [enemyPosition.x, 0.76, enemyPosition.z],
            direction: [direction.x, 0, direction.z],
            speed:
              combatStats.projectileSpeed *
              pressureProfile.projectileSpeedMultiplier,
            damage:
              (bossPattern?.damage ?? liveStats.attackDamage) *
              pressureProfile.damageMultiplier,
            color: bossPattern?.color ?? TOON_PALETTE.coralLight,
            radius: bossPattern?.radius ?? 0.13,
            kind: bossPattern ? 'magic' : 'arrow',
          })
        }
        if (bossPattern) rangedCastIndex.current += 1
        audioEngine.play('shot')
      }
      if (isMoonbriarQueen(archetypeId)) {
        const queenPattern = getMoonbriarCombatPattern(
          healthRef.current / maxHealth,
        )
        useGameStore.getState().spawnEffect({
          id: makeRuntimeId('moonbriar-root-cross'),
          kind: 'burst',
          position: [attack.target.x, 0.12, attack.target.z],
          direction: [1, 0, 0],
          color: BOSS_PROJECTILE_COLOR,
          durationMs: 320,
          length: 8.4,
          width: 1.05,
          variant: 'sigil',
        })
        const rootOffset = playerPosition.clone().sub(attack.target).setY(0)
        const inRootCross =
          (Math.abs(rootOffset.x) <= 0.52 && Math.abs(rootOffset.z) <= 4.2) ||
          (Math.abs(rootOffset.z) <= 0.52 && Math.abs(rootOffset.x) <= 4.2)
        if (inRootCross) {
          useGameStore
            .getState()
            .damagePlayer(
              queenPattern.rootCrossDamage * pressureProfile.damageMultiplier,
              [enemyPosition.x, enemyPosition.y, enemyPosition.z],
            )
        }
        triggerMoonbriarDash(attack.direction, queenPattern.dashImpulse)
        queuedMoonbriarDash.current =
          queenPattern.dashCount > 1
            ? {
                remaining: queenPattern.dashCount - 1,
                nextAt: runtime.elapsed + queenPattern.dashWindupMs / 1_000,
                direction: attack.direction.clone(),
                impulse: queenPattern.dashImpulse,
              }
            : null
      }
    } else if (archetypeId === 'crypt-brute') {
      const toPlayer = playerPosition.clone().sub(enemyPosition).setY(0)
      const projection = toPlayer.dot(attack.direction)
      const perpendicular = toPlayer
        .clone()
        .addScaledVector(attack.direction, -projection)
        .length()
      useGameStore.getState().spawnEffect({
        id: makeRuntimeId('brute-charge'),
        kind: 'trail',
        position: [enemyPosition.x, 0.16, enemyPosition.z],
        direction: [attack.direction.x, 0, attack.direction.z],
        color: TOON_PALETTE.gold,
        durationMs: 220,
      })
      externalVelocity.current.addScaledVector(
        attack.direction,
        pressureProfile.bruteChargeImpulse,
      )
      if (
        !blocked &&
        projection >= 0 &&
        projection <= 6 &&
        perpendicular <= 0.72
      ) {
        useGameStore
          .getState()
          .damagePlayer(
            liveStats.attackDamage * pressureProfile.damageMultiplier,
            [enemyPosition.x, enemyPosition.y, enemyPosition.z],
          )
      }
    } else {
      const toPlayer = playerPosition.clone().sub(enemyPosition).setY(0)
      const distance = toPlayer.length()
      const inArc =
        distance < 0.001 ||
        toPlayer.normalize().dot(attack.direction) >=
          Math.cos((72 * Math.PI) / 180)
      const range =
        archetypeId === 'grave-warden' ? 2.75 : combatStats.attackRange + 0.25
      if (!blocked && distance <= range && inArc) {
        useGameStore
          .getState()
          .damagePlayer(
            liveStats.attackDamage * pressureProfile.damageMultiplier,
            [enemyPosition.x, enemyPosition.y, enemyPosition.z],
          )
      }
    }

    releaseAttackToken()
    attack.phase = 'recover'
    const recoveryMs = isMoonbriarQueen(archetypeId)
      ? getMoonbriarCombatPattern(healthRef.current / maxHealth).recoveryMs
      : liveStats.attackCooldownMs
    attack.remaining = (recoveryMs / 1000) * pressureProfile.recoveryMultiplier
    attack.duration = attack.remaining
    setCharacterMotion(motionRef, 'idle')
  }, [
    archetypeId,
    castStaticSegment,
    combatStats,
    eliteAffixId,
    maxHealth,
    pressureProfile,
    releaseAttackToken,
    triggerMoonbriarDash,
  ])

  const startAttack = useCallback(
    (kind: AttackKind, toPlayer: Vector3) => {
      if (!attackDirector.acquire(id, kind)) return false
      const attack = attackRef.current
      attack.phase = 'windup'
      attack.kind = kind
      const queenPattern = isMoonbriarQueen(archetypeId)
        ? getMoonbriarCombatPattern(healthRef.current / maxHealth)
        : null
      attack.duration =
        (queenPattern
          ? queenPattern.rootCrossWindupMs / 1_000
          : archetypeId === 'grave-warden' && kind === 'melee'
            ? 0.7
            : combatStats.windupMs / 1000) * pressureProfile.windupMultiplier
      attack.remaining = attack.duration
      attack.tokenHeld = true
      attack.direction.copy(toPlayer).setY(0).normalize()
      attack.target.copy(runtime.playerPosition).setY(0)
      setCharacterMotion(motionRef, attackMotionFor(archetypeId, kind), true)
      publishThreat()
      return true
    },
    [
      archetypeId,
      attackDirector,
      combatStats.windupMs,
      id,
      maxHealth,
      pressureProfile.windupMultiplier,
      publishThreat,
    ],
  )

  useFrame((_, frameDelta) => {
    if (deadRef.current) {
      deathRemaining.current -= Math.min(frameDelta, 0.08)
      if (deathRemaining.current <= 0) setDead(true)
      return
    }
    const state = useGameStore.getState()
    const body = bodyRef.current
    const handle = runtime.enemies.get(id)
    if (!body || !handle) return
    const translation = body.translation()
    positionRef.current.set(translation.x, translation.y, translation.z)
    handle.position.copy(positionRef.current)
    if (!isActiveCombatPhase(state.phase)) {
      body.setLinvel({ x: 0, y: 0, z: 0 }, true)
      return
    }

    // Hit stop scales only what the scene integrates; the seeded run logic
    // never sees it, so impact weight cannot change what a seed produces.
    const delta = applyHitstop(Math.min(frameDelta, 0.08))
    const player = runtime.playerPosition
    // Mutated in place rather than rebuilt: this is read twice per enemy per
    // frame and never escapes the tick.
    const config = visionConfig.current
    config.range = state.stats.visionRange
    config.fovDeg = state.stats.visionFovDeg
    config.exitGraceMs = visionRuneRules.exitGraceMs
    const candidate = isVisionCandidate(
      { x: player.x, z: player.z },
      { x: runtime.playerFacing.x, z: runtime.playerFacing.z },
      { x: positionRef.current.x, z: positionRef.current.z },
      config,
    )
    const directlyVisible =
      candidate &&
      !castStaticSegment(
        player.x,
        0.78,
        player.z,
        positionRef.current.x,
        0.76,
        positionRef.current.z,
      )
    const dispelActive = runtime.elapsed < gazeDispelUntil.current
    if (gazeDispelled && !dispelActive) {
      setGazeDispelled(false)
    }
    const observationResult = updateObservationPolicy(
      observation.current,
      directlyVisible,
      runtime.elapsed * 1000,
      dispelActive ? DISPELLED_OBSERVATION_PROFILE : observationProfile,
      config,
    )
    const { frozen: isFrozen, gazeObserved: isGazeObserved } =
      resolveEnemyFreezeState(
        observationProfile.mode,
        observationResult.frozen,
        dispelActive,
      )
    if (isFrozen !== observedRef.current) {
      observedRef.current = isFrozen
      setObserved(isFrozen)
      handle.frozen = isFrozen
      if (isFrozen) {
        audioEngine.play('freeze')
        useGameStore.getState().spawnEffect({
          id: makeRuntimeId('gaze-drain'),
          kind: 'drain',
          position: [positionRef.current.x, 0.58, positionRef.current.z],
          direction: [
            runtime.playerPosition.x - positionRef.current.x,
            0,
            runtime.playerPosition.z - positionRef.current.z,
          ],
          color: TOON_PALETTE.coralLight,
          durationMs: 180,
          length: 1.8,
        })
        // The freeze used to be a colour swap and a sound. This gives the
        // game's signature beat a moment of its own.
        useGameStore.getState().spawnEffect({
          id: makeRuntimeId('gaze-seal'),
          kind: 'seal',
          position: [positionRef.current.x, 0.04, positionRef.current.z],
          color: TOON_PALETTE.cyanLight,
          durationMs: 280,
        })
      }
    }
    if (isGazeObserved !== gazeObservedRef.current) {
      gazeObservedRef.current = isGazeObserved
      handle.observed = isGazeObserved
      useGameStore.getState().adjustObservedEnemies(isGazeObserved ? 1 : -1)
    }
    const displayProgress =
      Math.round(observationResult.breakProgress * 20) / 20
    if (displayProgress !== breakProgressRef.current) {
      breakProgressRef.current = displayProgress
    }
    if (observationResult.state.broken !== observation.current.broken) {
      setObservationBroken(observationResult.state.broken)
    }
    handle.observationMode = observationProfile.mode
    handle.observationProgress = observationResult.breakProgress
    handle.observationBroken = observationResult.state.broken
    const nextUndyingEyeState = undyingEyeEnabled
      ? updateUndyingEyeState(
          undyingEyeState.current,
          isGazeObserved,
          delta * 1_000,
        )
      : INITIAL_UNDYING_EYE_STATE
    undyingEyeState.current = nextUndyingEyeState
    handle.undyingEyeMarked = nextUndyingEyeState.marked
    handle.continuousObservedMs = nextUndyingEyeState.observedMs
    handle.healthRatio = healthRef.current / maxHealth
    observation.current = observationResult.state

    if (
      archetypeId === 'veil-breaker' &&
      !isFrozen &&
      runtime.elapsed >= nextLiberationAt.current
    ) {
      const allies = [...runtime.enemies.values()].filter(
        (enemy) =>
          enemy.id !== id &&
          enemy.frozen &&
          enemy.position.distanceToSquared(positionRef.current) <= 49 &&
          !castStaticSegment(
            positionRef.current.x,
            0.74,
            positionRef.current.z,
            enemy.position.x,
            0.74,
            enemy.position.z,
          ),
      )
      if (allies.length > 0) {
        nextLiberationAt.current = runtime.elapsed + 5.5
        liberationPulseUntil.current = runtime.elapsed + 0.72
        useGameStore.getState().spawnEffect({
          id: makeRuntimeId('liberation-wave'),
          kind: 'seal',
          position: [positionRef.current.x, 0.06, positionRef.current.z],
          color: TOON_PALETTE.coralLight,
          durationMs: 250,
        })
        for (const ally of allies) {
          const direction = ally.position
            .clone()
            .sub(positionRef.current)
            .setY(0)
          if (direction.lengthSq() > 0.001) direction.normalize()
          useGameStore.getState().spawnProjectile({
            id: makeRuntimeId('liberation-bolt'),
            position: [positionRef.current.x, 0.74, positionRef.current.z],
            direction: [direction.x, 0, direction.z],
            speed: 7.5,
            damage: 0,
            color: TOON_PALETTE.coralLight,
            radius: 0.18,
            kind: 'liberation',
            targetEnemyId: ally.id,
            activationDelayMs: 250,
          })
        }
        runtime.cameraTrauma = Math.max(runtime.cameraTrauma, 0.14)
        audioEngine.play('warning')
      } else {
        nextLiberationAt.current = runtime.elapsed + 0.35
      }
    }

    if (observationResult.justBroke) {
      releaseAttackToken()
      // Escaping a completed gaze is the enemy's best moment, so it gets a
      // dedicated shatter rather than the generic burst it used to share with
      // deaths and pickups.
      useGameStore.getState().spawnEffect({
        id: makeRuntimeId('veil-break'),
        kind: 'shatter',
        position: [positionRef.current.x, 0.32, positionRef.current.z],
        color: TOON_PALETTE.coralLight,
        durationMs: 420,
      })
      runtime.cameraTrauma = Math.max(runtime.cameraTrauma, 0.2)
      audioEngine.play('warning')
    }

    const queuedDash = queuedMoonbriarDash.current
    if (queuedDash && runtime.elapsed >= queuedDash.nextAt) {
      triggerMoonbriarDash(queuedDash.direction, queuedDash.impulse)
      queuedDash.remaining -= 1
      if (queuedDash.remaining <= 0) queuedMoonbriarDash.current = null
      else queuedDash.nextAt = runtime.elapsed + 0.6
    }

    const toPlayer = tmpDirection.copy(player).sub(positionRef.current).setY(0)
    const playerDistance = toPlayer.length()
    if (playerDistance > 0.001) toPlayer.normalize()

    if (isFrozen) {
      releaseAttackToken()
      externalVelocity.current.multiplyScalar(externalVelocityRetention(delta))
      body.setLinvel(
        {
          x: externalVelocity.current.x,
          y: 0,
          z: externalVelocity.current.z,
        },
        true,
      )
      return
    }

    const attack = attackRef.current
    if (attack.phase === 'windup' && !attack.tokenHeld) {
      if (
        castStaticSegment(
          positionRef.current.x,
          0.76,
          positionRef.current.z,
          player.x,
          0.78,
          player.z,
        )
      ) {
        releaseAttackToken()
        attack.phase = 'approach'
        attack.remaining = 0
      } else if (attackDirector.acquire(id, attack.kind)) {
        attack.tokenHeld = true
        setCharacterMotion(
          motionRef,
          attackMotionFor(archetypeId, attack.kind),
          true,
        )
        publishThreat()
      }
      if (attack.phase === 'windup' && !attack.tokenHeld) {
        externalVelocity.current.multiplyScalar(
          externalVelocityRetention(delta),
        )
        body.setLinvel(
          {
            x: externalVelocity.current.x,
            y: 0,
            z: externalVelocity.current.z,
          },
          true,
        )
        return
      }
    }
    animationTime.current += delta
    if (attack.phase === 'windup' && attack.tokenHeld) {
      attack.remaining -= delta
      externalVelocity.current.multiplyScalar(externalVelocityRetention(delta))
      body.setLinvel(
        {
          x: externalVelocity.current.x,
          y: 0,
          z: externalVelocity.current.z,
        },
        true,
      )
      quaternionFromNegativeZForward(attack.direction, targetQuaternion)
      visualRef.current?.quaternion.slerp(
        targetQuaternion,
        1 - Math.exp(-delta * 30),
      )
      if (attack.remaining <= 0) resolveAttack()
      return
    }
    if (attack.phase === 'recover') {
      attack.remaining -= delta
      if (attack.remaining <= 0) attack.phase = 'approach'
    }

    const hasDirectLos = !castStaticSegment(
      positionRef.current.x,
      0.72,
      positionRef.current.z,
      player.x,
      0.72,
      player.z,
    )
    const triggerRange =
      archetypeId === 'crypt-brute'
        ? 6
        : isSceneBoss(archetypeId)
          ? 9.5
          : combatStats.attackRange
    if (
      attack.phase === 'approach' &&
      playerDistance <= triggerRange &&
      hasDirectLos
    ) {
      const kind: AttackKind =
        archetypeId === 'bone-archer' ||
        isMoonbriarQueen(archetypeId) ||
        (archetypeId === 'grave-warden' &&
          playerDistance > combatStats.attackRange)
          ? 'ranged'
          : 'melee'
      if (startAttack(kind, toPlayer)) {
        body.setLinvel({ x: 0, y: 0, z: 0 }, true)
        return
      }
    }

    navigationRefresh.current -= delta
    if (navigationRefresh.current <= 0) {
      navigationRefresh.current = 0.2
      const path = findNavigationPath(
        waypoints,
        { x: positionRef.current.x, z: positionRef.current.z },
        { x: player.x, z: player.z },
        (from, to) => castStaticSegment(from.x, 0.7, from.z, to.x, 0.7, to.z),
      )
      navigationPoints.current = path?.points ?? []
    }

    const firstPoint = navigationPoints.current[0]
    const secondPoint = navigationPoints.current[1]
    let navigationPoint = firstPoint
    if (
      firstPoint &&
      secondPoint &&
      Math.hypot(
        firstPoint.x - positionRef.current.x,
        firstPoint.z - positionRef.current.z,
      ) < 0.75
    ) {
      navigationPoint = secondPoint
    }
    const aiDirection = navigationPoint
      ? tmpAiDirection.set(
          navigationPoint.x - positionRef.current.x,
          0,
          navigationPoint.z - positionRef.current.z,
        )
      : tmpAiDirection.copy(toPlayer)
    if (aiDirection.lengthSq() > 0.001) aiDirection.normalize()

    let aiSpeed = getPressureAdjustedMoveSpeed(
      combatStats.moveSpeed,
      pressureProfile,
    )
    if (
      definition.behavior === 'keep-distance' ||
      definition.behavior === 'blink-caster'
    ) {
      const preferred = combatStats.preferredRange
      if (playerDistance < preferred - 1) {
        aiDirection.copy(toPlayer).multiplyScalar(-1)
      } else if (playerDistance <= preferred + 1) {
        const side = stableHash(id) % 2 === 0 ? 1 : -1
        aiDirection.set(-toPlayer.z * side, 0, toPlayer.x * side)
        aiSpeed = getPressureAdjustedMoveSpeed(1.4, pressureProfile)
      }
    } else {
      const side = stableHash(id) % 2 === 0 ? 1 : -1
      aiDirection
        .add(
          tmpStrafe
            .set(-toPlayer.z * side, 0, toPlayer.x * side)
            .multiplyScalar(0.38),
        )
        .normalize()
    }
    if (
      definition.behavior === 'charge' &&
      (archetypeId === 'gaze-stalker' || playerDistance < 6)
    ) {
      aiSpeed *= archetypeId === 'gaze-stalker' ? 1.35 : 1.3
    }

    const separation = tmpSeparation.set(0, 0, 0)
    for (const other of runtime.enemies.values()) {
      if (other.id === id) continue
      const away = tmpAway.copy(positionRef.current).sub(other.position).setY(0)
      const distance = away.length()
      if (distance > 0.001 && distance < 1.25) {
        separation.addScaledVector(
          away.normalize(),
          (1 - distance / 1.25) * 0.85,
        )
      }
    }
    aiDirection.add(separation).normalize()

    externalVelocity.current.multiplyScalar(externalVelocityRetention(delta))
    const velocity = tmpVelocity
      .copy(externalVelocity.current)
      .addScaledVector(aiDirection, aiSpeed)
    body.setLinvel({ x: velocity.x, y: 0, z: velocity.z }, true)
    if (runtime.elapsed >= hitAnimationEndsAt.current) {
      setCharacterMotion(motionRef, velocity.lengthSq() > 0.01 ? 'run' : 'idle')
    }

    const facing = toPlayer.lengthSq() > 0.001 ? toPlayer : aiDirection
    quaternionFromNegativeZForward(facing, targetQuaternion)
    visualRef.current?.quaternion.slerp(
      targetQuaternion,
      1 - Math.exp(-delta * 18),
    )
    if (visualRef.current) {
      visualRef.current.position.y =
        Math.sin(animationTime.current * 5.5) * 0.035
    }
  })

  if (dead) return null
  const gazeRuleMarkerKind = resolveGazeRuleMarker(
    observationProfile.mode,
    gazeDispelled,
    observationBroken,
  )
  const colliderScale = isSceneBoss(archetypeId)
    ? 1.25
    : archetypeId === 'crypt-brute'
      ? 1.08
      : archetypeId === 'blind-thrall'
        ? 0.7
        : 0.85
  return (
    <RigidBody
      ref={bodyRef}
      type="dynamic"
      colliders={false}
      position={[position.x, 0.72, position.z]}
      enabledRotations={[false, false, false]}
      enabledTranslations={[true, false, true]}
      linearDamping={3.2}
      name={`enemy-${id}`}
    >
      {archetypeId === 'crypt-brute' || isSceneBoss(archetypeId) ? (
        <CuboidCollider
          args={[
            0.42 * colliderScale,
            0.55 * colliderScale,
            0.42 * colliderScale,
          ]}
          collisionGroups={interactionGroups(2, [0, 1, 2])}
        />
      ) : (
        <BallCollider
          args={[0.46 * colliderScale]}
          collisionGroups={interactionGroups(2, [0, 1, 2])}
        />
      )}
      <mesh position={[0, -0.69, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <circleGeometry
          args={[
            isSceneBoss(archetypeId)
              ? 0.82
              : archetypeId === 'crypt-brute'
                ? 0.62
                : 0.48,
            20,
          ]}
        />
        <meshBasicMaterial
          color="#171329"
          transparent
          opacity={observed ? 0.18 : 0.3}
          depthWrite={false}
        />
      </mesh>
      <group ref={visualRef}>
        <EnemyVisual
          archetypeId={archetypeId}
          observed={observed}
          motionRef={motionRef}
          paused={!isActiveCombatPhase(phase) && !dying}
        />
      </group>
      <EnemyHealthBar archetypeId={archetypeId} ratio={health / maxHealth} />
      {gazeRuleMarkerKind ? (
        <GazeRuleMarker
          archetypeId={archetypeId}
          kind={gazeRuleMarkerKind}
          pulseUntil={
            archetypeId === 'veil-breaker' ? liberationPulseUntil : undefined
          }
          urgent={gazeDispelled}
        />
      ) : null}
      <AttackTelegraph
        archetypeId={archetypeId}
        attackRef={attackRef}
        positionRef={positionRef}
        observedRef={observedRef}
        boneArcherSpreads={pressureProfile.boneArcherSpreads}
        healthRatio={health / maxHealth}
      />
    </RigidBody>
  )
}
