import { BlendFunction, Effect, EffectAttribute } from 'postprocessing'
import { Uniform, Vector2 } from 'three'

export interface ToonGradeUniforms {
  readonly saturation: number
  readonly contrast: number
  readonly splitTone: number
  readonly vignetteStrength: number
  readonly highlightCompression: number
  readonly celBandStrength: number
  readonly inkEdgeStrength: number
}

/*
 * Tuned for the Echoes of Wisdom diorama read.
 *
 * The band pass and ink edge are pulled almost off. Both were doing the work
 * of a comic-book line, which is the opposite of that family's soft painted
 * toys — the silhouettes there come from value and from the tilt-shift blur,
 * not from a stroke. They are kept at a trace rather than removed so scenery
 * still gets a hint of separation where two similar values meet. The vignette
 * goes the other way and comes up, because a darkened frame edge is part of
 * what sells a miniature sitting under a lamp.
 */
export const TOON_GRADE_FULL: ToonGradeUniforms = {
  saturation: 1.18,
  contrast: 1.04,
  splitTone: 0.2,
  vignetteStrength: 0.24,
  highlightCompression: 0.24,
  celBandStrength: 0.08,
  inkEdgeStrength: 0.08,
}

export const TOON_GRADE_REDUCED_MOTION: ToonGradeUniforms = {
  saturation: 1.06,
  contrast: 1.04,
  splitTone: 0.12,
  vignetteStrength: 0.04,
  highlightCompression: 0.18,
  celBandStrength: 0.06,
  inkEdgeStrength: 0.06,
}

/*
 * Ported verbatim from the hand-rolled ShaderPass this replaces. The grade is
 * the project's authored look — cool shadows, warm highlights, a six-step cel
 * band and a navy ink edge — so migrating the compositor was never a reason to
 * throw it away. Only the entry point changed: `mainImage` instead of a bare
 * `main`, `uv` instead of a varying, and neighbour taps read from
 * `inputBuffer`, which requires the CONVOLUTION attribute.
 */
const FRAGMENT = /* glsl */ `
uniform float saturation;
uniform float contrast;
uniform float splitTone;
uniform float vignetteStrength;
uniform float highlightCompression;
uniform float celBandStrength;
uniform float inkEdgeStrength;
uniform vec2 gradeTexelSize;

float bodaLuma(vec3 color) {
  return dot(color, vec3(0.2126, 0.7152, 0.0722));
}

void mainImage(const in vec4 inputColor, const in vec2 uv, out vec4 outputColor) {
  vec3 color = max(inputColor.rgb, vec3(0.0));
  float sourceLuma = bodaLuma(color);

  float shadowMask = 1.0 - smoothstep(0.10, 0.58, sourceLuma);
  float highlightMask = smoothstep(0.54, 1.42, sourceLuma);
  vec3 coolShadow =
    color * vec3(0.97, 0.97, 1.0) + vec3(0.004, 0.004, 0.008);
  color = mix(color, coolShadow, shadowMask * splitTone);
  vec3 warmHighlight =
    color * vec3(1.02, 1.0, 1.0) + vec3(0.008, 0.004, 0.004);
  color = mix(color, warmHighlight, highlightMask * splitTone);

  float gradedLuma = bodaLuma(color);
  color = mix(vec3(gradedLuma), color, saturation);
  color = max((color - 0.18) * contrast + 0.18, vec3(0.0));

  // A compact shoulder keeps bright cel bands readable.
  float highlightLuma = max(bodaLuma(color) - 0.78, 0.0);
  color /= 1.0 + highlightLuma * highlightCompression;

  // MeshToonMaterial provides the key light planes. This restrained full-scene
  // band pass keeps indirect light, props, and VFX in the same graphic
  // language without lowering the render resolution.
  float celLuma = bodaLuma(color);
  float bandedLuma = floor(celLuma * 6.0 + 0.5) / 6.0;
  float celScale = bandedLuma / max(celLuma, 0.025);
  color = mix(color, color * celScale, celBandStrength);

  // A four-tap colour edge gives non-interactive scenery a subtle navy ink
  // edge. Characters retain their stronger inverted-hull silhouettes.
  vec3 north = texture2D(inputBuffer, uv + vec2(0.0, gradeTexelSize.y)).rgb;
  vec3 south = texture2D(inputBuffer, uv - vec2(0.0, gradeTexelSize.y)).rgb;
  vec3 east = texture2D(inputBuffer, uv + vec2(gradeTexelSize.x, 0.0)).rgb;
  vec3 west = texture2D(inputBuffer, uv - vec2(gradeTexelSize.x, 0.0)).rgb;
  float lumaEdge =
    abs(bodaLuma(north) - bodaLuma(south)) +
    abs(bodaLuma(east) - bodaLuma(west));
  float colorEdge = length(north - south) + length(east - west);
  float inkMask = smoothstep(0.11, 0.48, lumaEdge + colorEdge * 0.16);
  vec3 inked = color * vec3(0.22);
  color = mix(color, inked, inkMask * inkEdgeStrength);

  vec2 vignetteUv = (uv - 0.5) * vec2(1.0, 0.92);
  float vignette = smoothstep(0.32, 0.70, length(vignetteUv));
  color *= 1.0 - vignette * vignetteStrength;

  outputColor = vec4(color, inputColor.a);
}
`

export class ToonGradeEffect extends Effect {
  constructor(values: ToonGradeUniforms = TOON_GRADE_FULL) {
    super('BodaToonGrade', FRAGMENT, {
      blendFunction: BlendFunction.SET,
      attributes: EffectAttribute.CONVOLUTION,
      uniforms: new Map<string, Uniform>([
        ['saturation', new Uniform(values.saturation)],
        ['contrast', new Uniform(values.contrast)],
        ['splitTone', new Uniform(values.splitTone)],
        ['vignetteStrength', new Uniform(values.vignetteStrength)],
        ['highlightCompression', new Uniform(values.highlightCompression)],
        ['celBandStrength', new Uniform(values.celBandStrength)],
        ['inkEdgeStrength', new Uniform(values.inkEdgeStrength)],
        ['gradeTexelSize', new Uniform(new Vector2(1, 1))],
      ]),
    })
  }

  /** The ink edge samples neighbours, so it needs the real buffer resolution. */
  override setSize(width: number, height: number): void {
    const texel = this.uniforms.get('gradeTexelSize')?.value as
      Vector2 | undefined
    texel?.set(1 / Math.max(1, width), 1 / Math.max(1, height))
  }

  applyValues(values: ToonGradeUniforms): void {
    for (const [key, value] of Object.entries(values)) {
      const uniform = this.uniforms.get(key)
      if (uniform) uniform.value = value
    }
  }
}
