import type {
  BossArchetypeId,
  CombatantArchetypeId,
  EnemyArchetypeId,
} from '../game'

import { isMoonbriarQueen } from './sceneMetadata'

export const BOSS_REINFORCEMENT_FIRST_WAVE_MS = 6_500
export const BOSS_REINFORCEMENT_INTERVAL_MS = 13_000
export const BOSS_REINFORCEMENT_CAP = 4
export const BOSS_REINFORCEMENT_WAVE_SIZE = 2

export function canSpawnBossReinforcementWave(
  activeReinforcements: number,
): boolean {
  return (
    Number.isFinite(activeReinforcements) &&
    activeReinforcements >= 0 &&
    activeReinforcements + BOSS_REINFORCEMENT_WAVE_SIZE <=
      BOSS_REINFORCEMENT_CAP
  )
}

export interface BossReinforcementSpawn {
  readonly side: 'north' | 'east' | 'south' | 'west'
  readonly position: { readonly x: number; readonly z: number }
  readonly archetypeId: EnemyArchetypeId
}

const WARDEN_REINFORCEMENT_ROSTERS = [
  ['grave-husk', 'bone-archer'],
  ['grave-husk', 'crypt-brute'],
] as const satisfies readonly (readonly EnemyArchetypeId[])[]

const QUEEN_REINFORCEMENT_ROSTERS = [
  ['grave-husk', 'crypt-brute'],
  ['grave-husk', 'bone-archer'],
] as const satisfies readonly (readonly EnemyArchetypeId[])[]

/** Two opposite entry lanes, alternating north/south then east/west. */
export function getBossReinforcementWave(
  bossId: BossArchetypeId,
  halfWidth: number,
  halfDepth: number,
  waveIndex: number,
): readonly BossReinforcementSpawn[] {
  const x = Math.max(2.5, halfWidth - 1.5)
  const z = Math.max(2.5, halfDepth - 1.5)
  const laneOffset = Math.floor(waveIndex / 2) % 2 === 0 ? -1.35 : 1.35
  const rosters =
    bossId === 'grave-warden'
      ? WARDEN_REINFORCEMENT_ROSTERS
      : QUEEN_REINFORCEMENT_ROSTERS
  const roster = rosters[waveIndex % rosters.length]

  if (waveIndex % 2 === 0) {
    return [
      {
        side: 'north',
        position: { x: laneOffset, z: -z },
        archetypeId: roster[0],
      },
      {
        side: 'south',
        position: { x: -laneOffset, z },
        archetypeId: roster[1],
      },
    ]
  }

  return [
    {
      side: 'east',
      position: { x, z: -laneOffset },
      archetypeId: roster[0],
    },
    {
      side: 'west',
      position: { x: -x, z: laneOffset },
      archetypeId: roster[1],
    },
  ]
}

export type BossTelegraphKind = 'target-rune' | 'bramble-fan'

/** Shared danger red for every boss-owned projectile and attack telegraph. */
export const BOSS_PROJECTILE_COLOR = '#d81f4d'

/** Keeps regular-enemy gaze feedback intact while locking bosses to danger red. */
export function resolveBossAttackVisualColor(
  archetypeId: CombatantArchetypeId | string,
  fallbackColor: string,
): string {
  return isSceneBoss(archetypeId) ? BOSS_PROJECTILE_COLOR : fallbackColor
}

export interface BossProjectilePattern {
  readonly id: 'warden-volley' | 'queen-fan'
  readonly telegraph: BossTelegraphKind
  readonly spreads: readonly number[]
  readonly damage: number
  readonly radius: number
  readonly color: string
  readonly idPrefix: string
}

const WARDEN_PATTERN: BossProjectilePattern = Object.freeze({
  id: 'warden-volley',
  telegraph: 'target-rune',
  spreads: Object.freeze([-0.22, 0, 0.22]),
  damage: 16,
  radius: 0.2,
  color: BOSS_PROJECTILE_COLOR,
  idPrefix: 'warden-shot',
})

const WARDEN_SECOND_PHASE_PATTERN: BossProjectilePattern = Object.freeze({
  ...WARDEN_PATTERN,
  spreads: Object.freeze([-0.44, -0.22, 0, 0.22, 0.44]),
})

const QUEEN_FAN: BossProjectilePattern = Object.freeze({
  id: 'queen-fan',
  telegraph: 'bramble-fan',
  spreads: Object.freeze([-0.46, -0.23, 0, 0.23, 0.46]),
  damage: 8,
  radius: 0.18,
  color: BOSS_PROJECTILE_COLOR,
  idPrefix: 'moonbriar-thorn',
})

const QUEEN_ENRAGED_FAN: BossProjectilePattern = Object.freeze({
  ...QUEEN_FAN,
  spreads: Object.freeze([-0.63, -0.42, -0.21, 0, 0.21, 0.42, 0.63]),
  damage: 7,
})

export interface MoonbriarCombatPattern {
  readonly projectile: BossProjectilePattern
  readonly rootCrossWindupMs: 800
  readonly dashWindupMs: 600
  readonly dashCount: 1 | 2
  readonly recoveryMs: number
  readonly rootCrossDamage: number
  readonly dashImpulse: number
}

const QUEEN_NORMAL_COMBAT: MoonbriarCombatPattern = Object.freeze({
  projectile: QUEEN_FAN,
  rootCrossWindupMs: 800,
  dashWindupMs: 600,
  dashCount: 1,
  recoveryMs: 1_150,
  rootCrossDamage: 12,
  dashImpulse: 5.8,
})

const QUEEN_ENRAGED_COMBAT: MoonbriarCombatPattern = Object.freeze({
  projectile: QUEEN_ENRAGED_FAN,
  rootCrossWindupMs: 800,
  dashWindupMs: 600,
  dashCount: 2,
  recoveryMs: 900,
  rootCrossDamage: 10,
  dashImpulse: 5.8,
})

export function isSceneBoss(
  archetypeId: CombatantArchetypeId | string,
): archetypeId is BossArchetypeId {
  return archetypeId === 'grave-warden' || isMoonbriarQueen(archetypeId)
}

/**
 * Scene-owned projectile pattern selection. The Warden constants intentionally
 * mirror the legacy implementation, while the Queen moves from a five-thorn
 * fan to seven thorns at half health. The root-cross and dash sequence lives
 * in `getMoonbriarCombatPattern` so projectile and movement tuning stay clean.
 */
export function getBossProjectilePattern(
  archetypeId: CombatantArchetypeId | string,
  healthRatio = 1,
  rangedCastIndex = 0,
): BossProjectilePattern | null {
  if (archetypeId === 'grave-warden') {
    return healthRatio <= 0.5 && rangedCastIndex % 2 === 1
      ? WARDEN_SECOND_PHASE_PATTERN
      : WARDEN_PATTERN
  }
  if (!isMoonbriarQueen(archetypeId)) return null
  return healthRatio <= 0.5 ? QUEEN_ENRAGED_FAN : QUEEN_FAN
}

export function getMoonbriarCombatPattern(
  healthRatio = 1,
): MoonbriarCombatPattern {
  return healthRatio <= 0.5 ? QUEEN_ENRAGED_COMBAT : QUEEN_NORMAL_COMBAT
}
