let activeCompilationCount = 0
let flushScheduled = false

export type SceneMaterialDisposalErrorHandler = (error: Error) => void

interface DeferredDisposal {
  readonly dispose: () => void
  readonly label: string
  readonly onError?: SceneMaterialDisposalErrorHandler
}

const deferredDisposals = new Set<DeferredDisposal>()

function toError(cause: unknown, fallback: string): Error {
  return cause instanceof Error ? cause : new Error(fallback, { cause })
}

function reportDisposalError(disposal: DeferredDisposal, cause: unknown): void {
  const error = toError(cause, `BODA could not dispose ${disposal.label}.`)

  if (disposal.onError) {
    try {
      disposal.onError(error)
      return
    } catch (reportingCause) {
      try {
        console.error(
          '[BODA] Scene material disposal error handler failed.',
          reportingCause,
          error,
        )
      } catch {
        // Reporting must never create another uncaught asynchronous exception.
      }
      return
    }
  }

  try {
    console.error(`[BODA] Failed to dispose ${disposal.label}.`, error)
  } catch {
    // Console implementations supplied by hosts or tests are not guaranteed safe.
  }
}

function scheduleDisposalFlush(): void {
  if (
    flushScheduled ||
    activeCompilationCount > 0 ||
    deferredDisposals.size === 0
  ) {
    return
  }

  flushScheduled = true
  queueMicrotask(() => {
    flushScheduled = false
    if (activeCompilationCount > 0) return

    const disposals = [...deferredDisposals]
    deferredDisposals.clear()
    for (const disposal of disposals) {
      try {
        disposal.dispose()
      } catch (cause) {
        reportDisposalError(disposal, cause)
      }
    }

    if (deferredDisposals.size > 0) scheduleDisposalFlush()
  })
}

export function deferSceneMaterialDisposal(
  dispose: () => void,
  options: {
    label?: string
    onError?: SceneMaterialDisposalErrorHandler
  } = {},
): void {
  deferredDisposals.add({
    dispose,
    label: options.label ?? 'scene material',
    onError: options.onError,
  })
  scheduleDisposalFlush()
}

export function beginSceneMaterialCompilation(): () => void {
  activeCompilationCount += 1
  let released = false

  return () => {
    if (released) return
    released = true
    activeCompilationCount = Math.max(0, activeCompilationCount - 1)
    scheduleDisposalFlush()
  }
}

export class SceneMaterialCompilationTimeoutError extends Error {
  constructor(timeoutMs: number) {
    super(`BODA shader compilation timed out after ${timeoutMs}ms.`)
    this.name = 'SceneMaterialCompilationTimeoutError'
  }
}

export type SceneMaterialCompilationOutcome = 'completed' | 'cancelled'

export interface SceneMaterialCompilationTask {
  readonly promise: Promise<SceneMaterialCompilationOutcome>
  cancel: () => void
}

/**
 * Starts a compilation lease that can be released independently of the
 * renderer promise. Three.js compileAsync() has no cancellation or rejection
 * path for its polling loop, so Canvas teardown must not depend on it settling.
 */
export function startSceneMaterialCompilation(
  compile: () => unknown,
  options: { timeoutMs?: number; signal?: AbortSignal } = {},
): SceneMaterialCompilationTask {
  const release = beginSceneMaterialCompilation()
  const timeoutMs =
    Number.isFinite(options.timeoutMs) && (options.timeoutMs ?? 0) > 0
      ? Math.max(1, options.timeoutMs ?? 1)
      : null
  let releaseCalled = false
  let terminationRequested = false
  let settled = false
  let timeoutId: ReturnType<typeof setTimeout> | undefined
  let resolveCancellation!: (outcome: 'cancelled') => void

  const releaseOnce = () => {
    if (releaseCalled) return
    releaseCalled = true
    release()
  }

  const cancellationPromise = new Promise<'cancelled'>((resolve) => {
    resolveCancellation = resolve
  })

  const compilePromise = Promise.resolve().then(async () => {
    if (terminationRequested) return 'cancelled' as const
    await compile()
    return terminationRequested
      ? ('cancelled' as const)
      : ('completed' as const)
  })

  const timeoutPromise =
    timeoutMs === null
      ? new Promise<never>(() => undefined)
      : new Promise<never>((_, reject) => {
          timeoutId = setTimeout(() => {
            if (settled || terminationRequested) return
            terminationRequested = true
            releaseOnce()
            reject(new SceneMaterialCompilationTimeoutError(timeoutMs))
          }, timeoutMs)
        })

  const handleAbort = () => cancel()
  const cancel = () => {
    if (settled || terminationRequested) return
    terminationRequested = true
    if (timeoutId !== undefined) clearTimeout(timeoutId)
    releaseOnce()
    resolveCancellation('cancelled')
  }

  const promise = Promise.race([
    compilePromise,
    cancellationPromise,
    timeoutPromise,
  ]).finally(() => {
    settled = true
    if (timeoutId !== undefined) clearTimeout(timeoutId)
    options.signal?.removeEventListener('abort', handleAbort)
    releaseOnce()
  })

  if (options.signal?.aborted) {
    cancel()
  } else {
    options.signal?.addEventListener('abort', handleAbort, { once: true })
  }

  return { promise, cancel }
}
