import type { CombatantArchetypeId } from '../game/types'

export interface EnemyStatusLayout {
  readonly healthBarHeight: number
  readonly markerHeight: number
  readonly markerRadius: number
  readonly maxDistanceScale: number
  readonly clearance: number
}

const HEALTH_BAR_HALF_HEIGHT = 0.0925
const DEFAULT_HEALTH_BAR_HEIGHT = 1.45
const DEFAULT_MARKER_RADIUS = 0.5
const DEFAULT_CLEARANCE = 0.14
const MAX_DISTANCE_SCALE = 1.15

const healthBarHeights = {
  'grave-husk': DEFAULT_HEALTH_BAR_HEIGHT,
  'bone-archer': DEFAULT_HEALTH_BAR_HEIGHT,
  'crypt-brute': 1.75,
  'gaze-stalker': DEFAULT_HEALTH_BAR_HEIGHT,
  'veil-breaker': DEFAULT_HEALTH_BAR_HEIGHT,
  'blind-thrall': 1.28,
  'grave-warden': 2.45,
  'moonbriar-queen': 2.45,
} as const satisfies Readonly<Record<CombatantArchetypeId, number>>

export function getEnemyStatusLayout(
  archetypeId: CombatantArchetypeId,
): EnemyStatusLayout {
  const isBoss =
    archetypeId === 'grave-warden' || archetypeId === 'moonbriar-queen'
  const healthBarHeight = healthBarHeights[archetypeId]
  const markerRadius = isBoss ? 0.58 : DEFAULT_MARKER_RADIUS
  const clearance = isBoss ? 0.18 : DEFAULT_CLEARANCE

  return {
    healthBarHeight,
    markerHeight:
      healthBarHeight +
      HEALTH_BAR_HALF_HEIGHT +
      markerRadius * MAX_DISTANCE_SCALE +
      clearance,
    markerRadius,
    maxDistanceScale: MAX_DISTANCE_SCALE,
    clearance,
  }
}
