import { MathUtils } from 'three'

export interface CameraFramingInsets {
  readonly x: number
  readonly z: number
}

const PORTRAIT_ASPECT = 1
const WIDE_ASPECT = 16 / 9
const PORTRAIT_INSETS: CameraFramingInsets = { x: 3.5, z: 3 }
const WIDE_INSETS: CameraFramingInsets = { x: 7.5, z: 4.75 }

export function getCameraFramingInsets(
  viewportAspect: number,
): CameraFramingInsets {
  const safeAspect = Number.isFinite(viewportAspect)
    ? viewportAspect
    : PORTRAIT_ASPECT
  const wideBlend = MathUtils.clamp(
    (safeAspect - PORTRAIT_ASPECT) / (WIDE_ASPECT - PORTRAIT_ASPECT),
    0,
    1,
  )

  return {
    x: MathUtils.lerp(PORTRAIT_INSETS.x, WIDE_INSETS.x, wideBlend),
    z: MathUtils.lerp(PORTRAIT_INSETS.z, WIDE_INSETS.z, wideBlend),
  }
}

export function clampCameraAnchorToRoom(
  coordinate: number,
  roomMinimum: number,
  roomMaximum: number,
  edgeInset: number,
) {
  const safeInset = Math.max(0, edgeInset)
  const safeMinimum = roomMinimum + safeInset
  const safeMaximum = roomMaximum - safeInset

  if (safeMinimum > safeMaximum) {
    return (roomMinimum + roomMaximum) / 2
  }

  return MathUtils.clamp(coordinate, safeMinimum, safeMaximum)
}
