/**
 * Rolling frame-time sampler.
 *
 * Deliberately allocation-free on the hot path: one array write per frame into
 * a fixed ring buffer. Percentiles are only computed when something asks for
 * them, which in practice is the debug bridge during an e2e run.
 *
 * This exists so "holds 60fps" is a measurement rather than a claim.
 */

/** 4 seconds at 60Hz — long enough to survive a chamber transition spike. */
const SAMPLE_CAPACITY = 240

/** A frame that took longer than this missed a 60Hz vsync deadline. */
export const FRAME_BUDGET_MS = 1000 / 60

/**
 * Frames slower than this are counted as dropped. Above the budget, but below
 * the point where a single slow frame is visible as a stutter.
 */
export const DROPPED_FRAME_MS = 20

export interface FrameStats {
  readonly sampleCount: number
  readonly p50Ms: number
  readonly p95Ms: number
  readonly p99Ms: number
  readonly maxMs: number
  /** Frames slower than DROPPED_FRAME_MS, as a fraction of samples. */
  readonly droppedRatio: number
  /** AdaptiveDpr's current resolution factor, 1 being full resolution. */
  readonly performanceFactor: number
}

const samples = new Float32Array(SAMPLE_CAPACITY)
let writeIndex = 0
let written = 0
let performanceFactor = 1

/**
 * Records how far AdaptiveDpr has scaled resolution down, where 1 is full.
 * Without it a healthy p95 is ambiguous — it could mean the scene is cheap, or
 * that the monitor quietly traded away sharpness to get there.
 */
export function setPerformanceFactor(factor: number): void {
  if (!Number.isFinite(factor)) return
  performanceFactor = Math.max(0, Math.min(1, factor))
}

export function recordFrame(deltaSeconds: number): void {
  const ms = deltaSeconds * 1000
  // A tab returning from background reports one enormous delta that is not a
  // rendering problem. Discarding it keeps the percentiles honest.
  if (!Number.isFinite(ms) || ms <= 0 || ms > 1000) return
  samples[writeIndex] = ms
  writeIndex = (writeIndex + 1) % SAMPLE_CAPACITY
  if (written < SAMPLE_CAPACITY) written += 1
}

export function resetFrameStats(): void {
  writeIndex = 0
  written = 0
  performanceFactor = 1
  samples.fill(0)
}

function percentile(sorted: readonly number[], fraction: number): number {
  if (sorted.length === 0) return 0
  const index = Math.min(
    sorted.length - 1,
    Math.max(0, Math.ceil(fraction * sorted.length) - 1),
  )
  return sorted[index] ?? 0
}

export function readFrameStats(): FrameStats {
  if (written === 0) {
    return {
      sampleCount: 0,
      p50Ms: 0,
      p95Ms: 0,
      p99Ms: 0,
      maxMs: 0,
      droppedRatio: 0,
      performanceFactor,
    }
  }

  const window = Array.from(samples.subarray(0, written))
  const sorted = [...window].sort((a, b) => a - b)
  const dropped = window.reduce(
    (count, value) => (value > DROPPED_FRAME_MS ? count + 1 : count),
    0,
  )

  return {
    sampleCount: written,
    p50Ms: percentile(sorted, 0.5),
    p95Ms: percentile(sorted, 0.95),
    p99Ms: percentile(sorted, 0.99),
    maxMs: sorted[sorted.length - 1] ?? 0,
    droppedRatio: dropped / written,
    performanceFactor,
  }
}
