import { useFrame } from '@react-three/fiber'
import { useRapier } from '@react-three/rapier'
import { useEffect, useMemo, useRef, useState } from 'react'
import {
  AdditiveBlending,
  DoubleSide,
  Group,
  SRGBColorSpace,
  Texture,
  TextureLoader,
  Vector3,
} from 'three'

import { useGameStore, type ProjectileSpawn } from '../runtime/gameStore'
import { runtime } from '../runtime/registry'
import { yawFromNegativeZForward } from './direction'
import {
  createOutlineMaterial,
  TOON_OUTLINE_COLOR,
  TOON_PALETTE,
  toonGradientMap,
} from './toonMaterials'

const VFX_ROOT = `${import.meta.env.BASE_URL}assets/vfx/`
const textureCache = new Map<string, Promise<Texture | null>>()
const PROJECTILE_OUTLINE_DISTANCE = 34
const projectileOutlineMaterial = createOutlineMaterial(
  TOON_OUTLINE_COLOR,
  0.029,
)

function useOptionalTexture(filename: string): Texture | null | undefined {
  const url = `${VFX_ROOT}${filename}`
  const [texture, setTexture] = useState<Texture | null>()
  useEffect(() => {
    let active = true
    const cached = textureCache.get(url)
    const request =
      cached ??
      new Promise<Texture | null>((resolve) => {
        new TextureLoader().load(
          url,
          (loaded) => {
            loaded.colorSpace = SRGBColorSpace
            loaded.needsUpdate = true
            resolve(loaded)
          },
          undefined,
          () => resolve(null),
        )
      })
    textureCache.set(url, request)
    void request.then((loaded) => {
      if (active) setTexture(loaded)
    })
    return () => {
      active = false
    }
  }, [url])
  return texture
}

interface ProjectileTextures {
  trail: Texture | null | undefined
  magic: Texture | null | undefined
}

function ProjectileTrail({
  projectile,
  texture,
}: {
  projectile: ProjectileSpawn
  texture: Texture | null | undefined
}) {
  const radius = projectile.radius ?? 0.16
  return (
    <mesh position={[0, -0.03, radius * 3.2]} rotation={[-Math.PI / 2, 0, 0]}>
      <planeGeometry args={[radius * 3.2, radius * 8.5]} />
      <meshBasicMaterial
        map={texture ?? undefined}
        color={projectile.color}
        transparent
        opacity={texture ? 0.62 : 0.22}
        alphaTest={texture ? 0.01 : 0}
        depthWrite={false}
        blending={AdditiveBlending}
        toneMapped={false}
        side={DoubleSide}
      />
    </mesh>
  )
}

function ArrowVisual({ color }: { color: string }) {
  return (
    <group>
      <mesh castShadow>
        <boxGeometry args={[0.055, 0.055, 0.72]} />
        <meshToonMaterial
          color="#8c4d2e"
          emissive="#2e1b16"
          gradientMap={toonGradientMap}
        />
      </mesh>
      <mesh position={[0, 0, -0.47]} rotation={[-Math.PI / 2, 0, 0]}>
        <coneGeometry args={[0.115, 0.28, 6]} />
        <meshToonMaterial
          color={color}
          emissive={color}
          emissiveIntensity={1.2}
          gradientMap={toonGradientMap}
        />
      </mesh>
      <mesh position={[0, 0, 0.37]} rotation={[0, 0, Math.PI / 4]}>
        <boxGeometry args={[0.18, 0.025, 0.16]} />
        <meshToonMaterial
          color={TOON_PALETTE.goldLight}
          gradientMap={toonGradientMap}
        />
      </mesh>
    </group>
  )
}

function MagicVisual({
  projectile,
  texture,
}: {
  projectile: ProjectileSpawn
  texture: Texture | null | undefined
}) {
  const radius = projectile.radius ?? 0.2
  return (
    <group>
      {texture ? (
        <sprite scale={[radius * 4.8, radius * 4.8, 1]}>
          <spriteMaterial
            map={texture}
            color={projectile.color}
            transparent
            opacity={0.78}
            depthWrite={false}
            blending={AdditiveBlending}
            toneMapped={false}
          />
        </sprite>
      ) : null}
      <mesh castShadow>
        <icosahedronGeometry args={[radius, 1]} />
        <meshToonMaterial
          color={projectile.color}
          emissive={projectile.color}
          emissiveIntensity={2.8}
          gradientMap={toonGradientMap}
        />
      </mesh>
    </group>
  )
}

function ProjectileOutline({ projectile }: { projectile: ProjectileSpawn }) {
  return projectile.kind === 'arrow' ? (
    <>
      <mesh>
        <boxGeometry args={[0.055, 0.055, 0.72]} />
        <primitive attach="material" object={projectileOutlineMaterial} />
      </mesh>
      <mesh position={[0, 0, -0.47]} rotation={[-Math.PI / 2, 0, 0]}>
        <coneGeometry args={[0.115, 0.28, 6]} />
        <primitive attach="material" object={projectileOutlineMaterial} />
      </mesh>
    </>
  ) : (
    <mesh>
      <icosahedronGeometry args={[projectile.radius ?? 0.2, 1]} />
      <primitive attach="material" object={projectileOutlineMaterial} />
    </mesh>
  )
}

function EnemyProjectile({
  projectile,
  textures,
}: {
  projectile: ProjectileSpawn
  textures: ProjectileTextures
}) {
  const groupRef = useRef<Group>(null)
  const position = useMemo(
    () => new Vector3(...projectile.position),
    [projectile.position],
  )
  const direction = useMemo(
    () => new Vector3(...projectile.direction).normalize(),
    [projectile.direction],
  )
  const rotationY = yawFromNegativeZForward(direction)
  const lifetime = useRef(5)
  const activationDelay = useRef((projectile.activationDelayMs ?? 0) / 1_000)
  const targetDirection = useMemo(() => new Vector3(), [])
  const outlineRef = useRef<Group>(null)
  const outlineRefresh = useRef(0.2)
  const { world, rapier } = useRapier()

  useFrame(({ camera }, frameDelta) => {
    outlineRefresh.current += frameDelta
    if (outlineRefresh.current >= 0.2 && outlineRef.current) {
      outlineRefresh.current = 0
      outlineRef.current.visible =
        camera.position.distanceToSquared(position) <=
        PROJECTILE_OUTLINE_DISTANCE * PROJECTILE_OUTLINE_DISTANCE
    }
    const phase = String(useGameStore.getState().phase)
    if (phase !== 'playing') return
    const delta = Math.min(frameDelta, 0.08)
    let liberationTargetDistance: number | undefined
    if (projectile.kind === 'liberation') {
      const target = projectile.targetEnemyId
        ? runtime.enemies.get(projectile.targetEnemyId)
        : undefined
      if (!target) {
        useGameStore.getState().removeProjectile(projectile.id)
        return
      }
      if (activationDelay.current > 0) {
        activationDelay.current -= delta
        return
      }

      targetDirection
        .set(target.position.x, 0.74, target.position.z)
        .sub(position)
      const targetDistance = targetDirection.length()
      liberationTargetDistance = targetDistance
      if (targetDistance > 0.001) direction.copy(targetDirection).normalize()
      if (groupRef.current) {
        groupRef.current.rotation.y = yawFromNegativeZForward(direction)
      }
      const impactDistance = 0.2
      if (targetDistance <= impactDistance) {
        target.dispelObservation(1_400)
        useGameStore.getState().spawnEffect({
          id: `liberated-${projectile.id}`,
          kind: 'shatter',
          position: [target.position.x, 0.34, target.position.z],
          color: TOON_PALETTE.coralLight,
          durationMs: 420,
        })
        runtime.cameraTrauma = Math.max(runtime.cameraTrauma, 0.12)
        useGameStore.getState().removeProjectile(projectile.id)
        return
      }
    }
    const stepDistance =
      liberationTargetDistance === undefined
        ? projectile.speed * delta
        : Math.min(projectile.speed * delta, liberationTargetDistance)
    const ray = new rapier.Ray(
      { x: position.x, y: position.y, z: position.z },
      { x: direction.x, y: direction.y, z: direction.z },
    )
    const flags =
      rapier.QueryFilterFlags.EXCLUDE_DYNAMIC |
      rapier.QueryFilterFlags.EXCLUDE_KINEMATIC
    if (world.castRay(ray, stepDistance + 0.08, true, flags)) {
      useGameStore.getState().removeProjectile(projectile.id)
      return
    }

    position.addScaledVector(direction, stepDistance)
    groupRef.current?.position.copy(position)
    lifetime.current -= delta

    if (projectile.kind === 'liberation') {
      const target = projectile.targetEnemyId
        ? runtime.enemies.get(projectile.targetEnemyId)
        : undefined
      if (!target) {
        useGameStore.getState().removeProjectile(projectile.id)
        return
      }
      const dx = position.x - target.position.x
      const dy = position.y - 0.74
      const dz = position.z - target.position.z
      if (dx * dx + dy * dy + dz * dz <= 0.04) {
        target.dispelObservation(1_400)
        useGameStore.getState().spawnEffect({
          id: `liberated-${projectile.id}`,
          kind: 'shatter',
          position: [target.position.x, 0.34, target.position.z],
          color: TOON_PALETTE.coralLight,
          durationMs: 420,
        })
        runtime.cameraTrauma = Math.max(runtime.cameraTrauma, 0.12)
        useGameStore.getState().removeProjectile(projectile.id)
      }
      if (lifetime.current <= 0)
        useGameStore.getState().removeProjectile(projectile.id)
      return
    }

    const dx = position.x - runtime.playerPosition.x
    const dz = position.z - runtime.playerPosition.z
    if (dx * dx + dz * dz < 0.38) {
      useGameStore
        .getState()
        .damagePlayer(projectile.damage, [
          position.x - direction.x * 1.5,
          position.y,
          position.z - direction.z * 1.5,
        ])
      useGameStore.getState().removeProjectile(projectile.id)
      return
    }
    if (lifetime.current <= 0)
      useGameStore.getState().removeProjectile(projectile.id)
  })

  return (
    <group
      ref={groupRef}
      position={projectile.position}
      rotation={[0, rotationY, 0]}
      name={`projectile-${projectile.kind ?? 'magic'}`}
    >
      <ProjectileTrail projectile={projectile} texture={textures.trail} />
      {projectile.kind === 'arrow' ? (
        <ArrowVisual color={projectile.color} />
      ) : (
        <MagicVisual projectile={projectile} texture={textures.magic} />
      )}
      <group ref={outlineRef} name="projectile-outline">
        <ProjectileOutline projectile={projectile} />
      </group>
    </group>
  )
}

export function Projectiles() {
  const projectiles = useGameStore((state) => state.projectiles)
  const textures: ProjectileTextures = {
    trail: useOptionalTexture('particle-trail.png'),
    magic: useOptionalTexture('particle-magic.png'),
  }
  return projectiles.map((projectile) => (
    <EnemyProjectile
      key={projectile.id}
      projectile={projectile}
      textures={textures}
    />
  ))
}
